local config = {
  ui_story_5076_50760100_1_dialog_content = "Rápido... Acorda, Re...!",
  ui_story_5076_50760100_2_dialog_content = "Quem está aí?",
  ui_story_5076_50760100_3_dialog_content = "Ele está preso no pesadelo... nós devemos... a Colossus...",
  ui_story_5076_50760100_4_dialog_content = "Espere, você não é...?",
  ui_story_5076_50760100_5_dialog_content = "<size=45>Volte—</size>",
  ui_story_5076_50760100_6_dialog_content = "Ah, você finalmente acordou. Você me assustou por um minuto.",
  ui_story_5076_50760100_7_dialog_content = "Qual é essa cara? Não se lembra do seu amigo Celestita? Sou eu, Ludweiss!",
  ui_story_5076_50760100_8_dialog_content = "Parecia que você estava tendo um pesadelo realmente ruim agora mesmo. Você não estava acordando, então Marcela me chamou.",
  ui_story_5076_50760100_9_dialog_content = "Marcela? Marcela...",
  ui_story_5076_50760100_10_dialog_content = "Comandante? Você está bem? É uma coisa esquecer de um andarilho como eu, mas como você poderia esquecer da sua noiva?",
  ui_story_5076_50760100_11_dialog_content = "Estou bem aqui, Adras... Você está se sentindo mal? Você parece tão pálido.",
  ui_story_5076_50760100_12_dialog_content = "Marcela... Sua roupas...",
  ui_story_5076_50760100_13_dialog_content = "... D-Não me olhe assim. Ludweiss ainda está aqui, sabe.",
  ui_story_5076_50760100_14_dialog_content = "Ainda apreciando a vista mesmo depois dos últimos dias, hein, Comandante? Faz sentido, já que a roupa da Marcela está muito mais fofa do que antes.",
  ui_story_5076_50760100_15_dialog_content = "Por favor, não me provoque assim...",
  ui_story_5076_50760100_16_dialog_content = "E as minhas roupas...",
  ui_story_5076_50760100_17_dialog_content = "Você tem certeza de que está acordado? Não me diga que você esqueceu do casamento.",
  ui_story_5076_50760100_18_dialog_content = "O casamento... É verdade, eu estava sonhando agora mesmo.",
  ui_story_5076_50760100_19_dialog_content = "Eu estava de pé na escuridão, e tudo que eu conseguia ver era um mural em uma parede... Era vago, mas acho que era sobre um casamento.",
  ui_story_5076_50760100_20_dialog_content = "Eu estava preso lá por tanto tempo, e eu não conseguia me lembrar de nada. Foi um sonho terrível... Um que durou mil anos.",
  ui_story_5076_50760100_21_dialog_content = "Eu não acho que Adras estava apenas tendo um pesadelo, Ludweiss. Você acha que ele pode estar doente?",
  ui_story_5076_50760100_22_dialog_content = "Não posso dizer com certeza, mas deixe-me tentar usar minhas habilidades psíquicas nele.",
  ui_story_5076_50760100_23_dialog_content = "Adras, você está acordado?",
  ui_story_5076_50760100_24_dialog_content = "...",
  ui_story_5076_50760100_25_dialog_content = "Isto é-!",
  ui_story_5076_50760100_26_dialog_content = "Por que... Por que você está chorando?",
  ui_story_5076_50760100_27_dialog_content = "Você estava sonhando com o futuro distante, Adras? Ou você sonhou comigo depois de todos esses anos?",
  ui_story_5076_50760100_28_dialog_content = "Do que você tá falando, Ludweiss?",
  ui_story_5076_50760100_29_dialog_content = "Ah?",
  ui_story_5076_50760100_30_dialog_content = "Desculpe, caí no pesadelo de Adras e me perdi por um segundo...",
  ui_story_5076_50760100_31_dialog_content = "Então até mesmo os Celestitas podem ser incomodados por sonhos, hein?",
  ui_story_5076_50760100_32_dialog_content = "V-Você finalmente acordou... Ei, pare de rir! Apenas agradeça que eu te tirei daquele pesadelo!",
  ui_story_5076_50760100_33_dialog_content = "Obrigado, Ludweiss. Eu estava começando a me preocupar demais.",
  ui_story_5076_50760100_34_dialog_content = "Obrigado... Mas o que você disse sobre o meu sonho agora mesmo—",
  ui_story_5076_50760100_35_dialog_content = "Comandante, peço desculpas pela intromissão, mas há uma mensagem urgente!",
  ui_story_5076_50760100_36_dialog_content = "O General Aquiles ordena que a legião se reúna.",
  ui_story_5076_50760100_37_dialog_content = "Entendido. Estarei lá em breve.",
  ui_story_5076_50760100_38_dialog_content = "Peço desculpas por fazer vocês dois se preocuparem tanto. Prometo que voltarei em breve.",
  ui_story_5076_50760100_39_dialog_content = "Heh, só tente não deixar Marcela esperando.",
  ui_story_5076_50760100_40_dialog_content = "Por outro lado, você continuou falando sobre um casamento enquanto dormia, então provavelmente não precisa que eu te lembre.",
  ui_story_5076_50760100_41_dialog_content = "N-Não a escute. A missão vem primeiro, e o General Achilles está esperando por você.",
  ui_story_5076_50760100_42_dialog_content = "Voltarei o mais rápido possível.",
  ui_story_5076_50760100_43_dialog_content = "... Os diabólicos Eclipsitas reapareceram ao norte, ameaçando invadir nossas fronteiras.",
  ui_story_5076_50760100_44_dialog_content = "O rei nos ordenou para erradicar esses monstros!",
  ui_story_5076_50760100_45_dialog_content = "Assim que for dispensado, reúna seus equipamentos e se despeça de seus entes queridos.",
  ui_story_5076_50760100_46_dialog_content = "Entendido!",
  ui_story_5076_50760100_47_dialog_content = "Como a vida normal tem te tratado, Adras?",
  ui_story_5076_50760100_48_dialog_content = "É pacífico. Ainda não estou totalmente acostumado com isso.",
  ui_story_5076_50760100_49_dialog_content = "Comandante, é hora de deixar as batalhas para trás e aceitar essa vida pacífica.",
  ui_story_5076_50760100_50_dialog_content = "Você vai se casar em breve, mas ainda está... Isso é bastante preocupante.",
  ui_story_5076_50760100_51_dialog_content = "Estamos prestes a sair, Adras, mas parabéns pelo seu casamento.",
  ui_story_5076_50760100_52_dialog_content = "Do que você está falando? Quase parece que você não tem intenção de me deixar ir nessa missão.",
  ui_story_5076_50760100_53_dialog_content = "Isso mesmo. Os Eclipsitas relatados no norte não justificam a total extensão de nossas forças.",
  ui_story_5076_50760100_54_dialog_content = "Sua missão é ficar aqui e aproveitar a vida que você criou para si mesmo.",
  ui_story_5076_50760100_55_dialog_content = "Você sacrificou anos de sua vida pelo bem dos outros, e agora é hora de buscar sua própria felicidade. Pelo menos, você pode ver tudo o que protegeu com Marcela ao seu lado.",
  ui_story_5076_50760100_56_dialog_content = "General, eu...",
  ui_story_5076_50760100_57_dialog_content = "Comandante Adras, de acordo com as leis e políticas do reino, você está oficialmente de licença matrimonial para que possa aproveitar seu casamento!",
  ui_story_5076_50760100_58_dialog_content = "Tranquilize sua mente e aproveite seu tempo de folga.",
  ui_story_5076_50760100_59_dialog_content = "Parabéns, Comandante Adras!",
  ui_story_5076_50760100_60_dialog_content = "Você...",
  ui_story_5076_50760100_61_dialog_content = "Talvez você já tenha um pequenino quando voltarmos!",
  ui_story_5076_50760100_62_dialog_content = "O comandante pode não ser o melhor com crianças. Tomara que seu filho seja mais parecido com a mãe.",
  ui_story_5076_50760100_63_dialog_content = "Tudo bem, pessoal, deixem seus presentes e sigam com seus afazeres. Adras, você fica aqui.",
  ui_story_5076_50760100_64_dialog_content = "Você ouviu falar que o <color=#FFB400>Alto Sacerdote Lucius</color> retornou à capital real?",
  ui_story_5076_50760100_65_dialog_content = "Lúcio? Você quer dizer que ele...",
  ui_story_5076_50760100_66_dialog_content = "Comandante Adras, todos os rebeldes estão aqui.",
  ui_story_5076_50760100_67_dialog_content = "Deixe-me ir, deixe-me ir! Você sabe quem eu sou?",
  ui_story_5076_50760100_68_dialog_content = "Sou Lucius, o Sumo Sacerdote que todos vocês devem reverenciar! Mostrem-me algum respeito!",
  ui_story_5076_50760100_69_dialog_content = "Tudo o que vejo é um traidor, e nada mais.",
  ui_story_5076_50760100_70_dialog_content = "Oh? Então nosso poderoso herói é quem armou isso? Não é à toa que tiveram a audácia de invadir com uma força tão insignificante.",
  ui_story_5076_50760100_71_dialog_content = "Como você ousa ser tão pretensioso quando não é nada além de um mero plebeu!",
  ui_story_5076_50760100_72_dialog_content = "Você colocou em risco a paz do reino e, portanto, está preso!",
  ui_story_5076_50760100_73_dialog_content = "Arrependa-se pelo mal que você causou às pessoas.",
  ui_story_5076_50760100_74_dialog_content = "Solte-me! Quem você pensa que é?! Você não é nada mais do que uma peça de xadrez do Primeiro Ancião!",
  ui_story_5076_50760100_75_dialog_content = "Você vai se arrepender disso! Marque minhas palavras, eu pessoalmente farei você pagar—",
  ui_story_5076_50760100_76_dialog_content = "Ele não foi considerado culpado de traição?",
  ui_story_5076_50760100_77_dialog_content = "Sim, mas Lucius ainda é um nobre. Apesar de ter contato com os rebeldes, ele foi considerado culpado apenas por associação.",
  ui_story_5076_50760100_78_dialog_content = "Quando ele caiu do poder, a influência do Conselho dos Anciões cresceu de maneira sem precedentes. Seu retorno à relevância política é apenas para que o rei possa manter o Ancião Primordial sob controle.",
  ui_story_5076_50760100_79_dialog_content = "O rei e eu fomos amigos por tantos anos, mas ultimamente ele tem se tornado cada vez mais um estranho para mim. Parece que ele se tornou bastante habilidoso em usar métodos como esses.",
  ui_story_5076_50760100_80_dialog_content = "Tenha cuidado, Adras.",
  ui_story_5076_50760100_81_dialog_content = "Estou apenas cumprindo minhas ordens. Ele não deveria guardar rancor contra mim.",
  ui_story_5076_50760100_82_dialog_content = "Nem todos seguem as regras e a razão tanto quanto você.",
  ui_story_5076_50760100_83_dialog_content = "Em qualquer caso, lembre-se de permanecer vigilante mesmo em sua nova vida pacífica. A infelicidade está sempre à espreita nas sombras.",
  ui_story_5076_50760100_84_dialog_content = "Quando o exército rebelde estava ocupando a cidade... Foi quando a conheci.",
  ui_story_5076_50760100_85_dialog_content = "Há mais neste mundo do que apenas infortúnio.",
  ui_story_5076_50760100_86_dialog_content = "Você mudou, Adras.",
  ui_story_5076_50760100_87_dialog_content = "Estou feliz por você. Parece que você finalmente encontrou as respostas que estava procurando na vida.",
  ui_story_5076_50760100_88_dialog_content = "Tudo bem, é isso de mim, os presentes também estão todos aqui. Aproveite os bons momentos que estão por vir!",
  ui_story_5076_50760100_89_dialog_content = "Estarei rezando pelo seu retorno seguro, General Aquiles.",
  ui_story_5076_50760100_90_dialog_content = "Obrigado, agora vá. Está quase na hora do casamento, então não deixe a Marcela esperando.",
  ui_story_5076_50760200_1_dialog_content = "Olhe lá! Esse é o lendário herói, Adras, caminhando em nossa direção!",
  ui_story_5076_50760200_2_dialog_content = "Adras? O herói que reprimiu a rebelião naquele tempo?",
  ui_story_5076_50760200_3_dialog_content = "Naquela época? Eu sou meio novo aqui; o que aconteceu naquele tempo?",
  ui_story_5076_50760200_4_dialog_content = "Deixe-me te contar, durante aqueles anos...",
  ui_story_5076_50760200_5_dialog_content = "Rebeldes! Eu, em nome da Legião Northwind, estou aqui para oferecer a vocês uma chance: seus reforços foram cortados; RENDAM-SE AGORA!",
  ui_story_5076_50760200_6_dialog_content = "Continue sonhando! Enquanto esta cidade resistir, nós não perderemos...",
  ui_story_5076_50760200_7_dialog_content = "Arqueiros! Fogo! Alguém, traga essas pessoas para cá! Deixe-os proteger o ataque!",
  ui_story_5076_50760200_8_dialog_content = "A primeira legião? E daí? Com todos esses reféns que temos na cidade...",
  ui_story_5076_50760200_9_dialog_content = "Capitão, olhe! Eles estão avançando em nós com escudos erguidos!",
  ui_story_5076_50760200_10_dialog_content = "O quê? Eles pensam que são invencíveis? Continue atirando! Não deixe eles se aproximarem das muralhas da cidade!",
  ui_story_5076_50760200_11_dialog_content = "Ugh—!",
  ui_story_5076_50760200_12_dialog_content = "O que está acontecendo lá embaixo?",
  ui_story_5076_50760200_13_dialog_content = "Um esquadrão se infiltrou pela retaguarda durante o caos! Eles já estão na cidade!",
  ui_story_5076_50760200_14_dialog_content = "Quantos são?",
  ui_story_5076_50760200_15_dialog_content = "Apenas um punhado deles, cada um empunhando apenas uma espada - eles escalaram a parede com suas próprias mãos!",
  ui_story_5076_50760200_16_dialog_content = "Bando inútil! Eu tenho que resolver isso sozinho?!",
  ui_story_5076_50760200_17_dialog_content = "Mas... o cara que está liderando eles é loucamente forte...",
  ui_story_5076_50760200_18_dialog_content = "Pare de resistir! Não vou atacar civis desarmados!",
  ui_story_5076_50760200_19_dialog_content = "Vocês também são cidadãos deste reino, então parem de machucar seus compatriotas!",
  ui_story_5076_50760200_20_dialog_content = "Idiotas tolos, cercados por nós e ainda agindo durões... PEGUEM ELES!",
  ui_story_5076_50760200_21_dialog_content = "Você teve sua chance, vilões - Todas as forças, matem o inimigo à vista!",
  ui_story_5076_50760200_22_dialog_content = "Derrubem o comandante deles e abram caminho para nossos irmãos atacando a cidade! Comigo!",
  ui_story_5076_50760200_23_dialog_content = "Parem-nos! Traga os arqueiros para cá!",
  ui_story_5076_50760200_24_dialog_content = "Capitão, más notícias! Alguém invadiu a masmorra onde estão os moradores e nosso armazém está pegando fogo!",
  ui_story_5076_50760200_25_dialog_content = "Capitão! O portão oeste foi aberto; alguém está ajudando os civis a escapar!",
  ui_story_5076_50760200_26_dialog_content = "Cap-Capitão! Atrás de nós!",
  ui_story_5076_50760200_27_dialog_content = "<size=40>Maldição!</size> O que diabos está acontecendo de novo—!",
  ui_story_5076_50760200_28_dialog_content = "<size=45>Morrer!</size>",
  ui_story_5076_50760200_29_dialog_content = "Capitão!",
  ui_story_5076_50760200_30_dialog_content = "Rebeldes! Seu capitão está morto! Abaixem suas armas, todos vocês!",
  ui_story_5076_50760200_31_dialog_content = "Já houve mortes sem sentido suficientes na cidade, mas agora é a hora de acabar com isso! Ninguém mais precisa morrer, contanto que você me traga seu líder!",
  ui_story_5076_50760200_32_dialog_content = "Por que deveríamos acreditar em você? Qual é a sua prova...",
  ui_story_5076_50760200_33_dialog_content = "Porque eu sou Adras!",
  ui_story_5076_50760200_34_dialog_content = "O homem que acabará com esta guerra!",
  ui_story_5076_50760200_35_dialog_content = "Veja como ele está correndo rápido! Talvez ele tenha se juntado à expedição também?",
  ui_story_5076_50760200_36_dialog_content = "Se aquele herói também estiver indo para lá, meu filho no exército deverá estar mais seguro, certo...?",
  ui_story_5076_50760200_37_dialog_content = "Você esqueceu? O herói está prestes a se casar; a cerimônia está toda pronta.",
  ui_story_5076_50760200_38_dialog_content = "Marcela!",
  ui_story_5076_50760200_39_dialog_content = "Uau! Não me assuste assim! Qual é o problema?",
  ui_story_5076_50760200_40_dialog_content = "Não te deixei esperando muito tempo... Deixei?",
  ui_story_5076_50760200_41_dialog_content = "Estou bem. É por você que estou preocupado. O que está acontecendo na Legião?",
  ui_story_5076_50760200_42_dialog_content = "Os Eclipsitas estão começando a se concentrar no norte. O general tem ordens para eliminá-los.",
  ui_story_5076_50760200_43_dialog_content = "E você não vai?",
  ui_story_5076_50760200_44_dialog_content = "O General Aquiles diz que seus números não requerem minha presença. Ele me dispensou para que pudéssemos passar nosso casamento em paz.",
  ui_story_5076_50760200_45_dialog_content = "Se é por minha causa, você não precisa—",
  ui_story_5076_50760200_46_dialog_content = "Você disse que o telhado do orfanato precisava de conserto, não disse? Eu tenho tempo para cuidar disso agora.",
  ui_story_5076_50760200_47_dialog_content = "Gostaria de passar alguns dias com você fora da cidade, se isso não for um problema?",
  ui_story_5076_50760200_48_dialog_content = "... Claro. Eu adoraria.",
  ui_story_5076_50760200_49_dialog_content = "<color=#e8d9bb>Vários dias depois</color>",
  ui_story_5076_50760200_50_dialog_content = "O casamento está logo ali na esquina, e vocês dois de repente querem fazer uma viagem para fora da cidade?",
  ui_story_5076_50760200_51_dialog_content = "Hã? Eu só pensei que estaríamos ocupados nos próximos dias, então eu queria preparar material didático suficiente para as crianças.",
  ui_story_5076_50760200_52_dialog_content = "E você não poderia simplesmente deixar isso por minha conta?",
  ui_story_5076_50760200_53_dialog_content = "Você não vai viajar para um novo lugar em breve? Além disso, você já me ajudou muito compilando isso. Eu não posso continuar dependendo de você.",
  ui_story_5076_50760200_54_dialog_content = "Pegando a estrada de novo, hein? Cuide-se bem, Ludweiss.",
  ui_story_5076_50760200_55_dialog_content = "Igual para vocês dois... O orfanato parece muito mais agradável desta vez. Você realmente tem dado o seu melhor, não é, Adras?",
  ui_story_5076_50760200_56_dialog_content = "Não me importo, contanto que seja pelas crianças.",
  ui_story_5076_50760200_57_dialog_content = "Então, o que você está fazendo agora?",
  ui_story_5076_50760200_58_dialog_content = "Fazendo pão.",
  ui_story_5076_50760200_59_dialog_content = "Que forma elegante. Não combina com você de jeito nenhum, sabe.",
  ui_story_5076_50760200_60_dialog_content = "Você pode ter um pouco, se quiser.",
  ui_story_5076_50760200_61_dialog_content = "Adras é bastante habilidoso em fazer pão. Antes de se tornar um soldado, ele praticamente venerava o padeiro local e até serviu como seu aprendiz por um tempo.",
  ui_story_5076_50760200_62_dialog_content = "Isso porque ele sempre distribuía pão para as crianças na rua.",
  ui_story_5076_50760200_63_dialog_content = "Adras, é Adras!",
  ui_story_5076_50760200_64_dialog_content = "Não me abrace. Estou coberto de farinha.",
  ui_story_5076_50760200_65_dialog_content = "Ainda não estamos com fome; vamos praticar primeiro.",
  ui_story_5076_50760200_66_dialog_content = "Por favor, ensine-nos algumas habilidades de espada; também queremos proteger a Marcela!",
  ui_story_5076_50760200_67_dialog_content = "Você não poderá comer este pão se eu não assá-lo agora mesmo.",
  ui_story_5076_50760200_68_dialog_content = "Habilidades com a espada primeiro! Isso é mais importante, você sabe!",
  ui_story_5076_50760200_69_dialog_content = "Marcela...",
  ui_story_5076_50760200_70_dialog_content = "Dê a ele algum espaço. Ele estará com você assim que terminar de colocar o pão no forno, tá bom?",
  ui_story_5076_50760200_71_dialog_content = "Multar...",
  ui_story_5076_50760200_72_dialog_content = "Adras é impotente perto dessas crianças, e ainda assim você consegue fazê-las ouvir com apenas algumas palavras.",
  ui_story_5076_50760200_73_dialog_content = "Bem, eu tenho mantido eles sob controle desde que eram pequenos, afinal.",
  ui_story_5076_50760200_74_dialog_content = "Quase me esqueci... Mesmo sendo mais jovem do que eu, você tem administrado este orfanato há anos. Você realmente é uma pessoa incrível.",
  ui_story_5076_50760200_75_dialog_content = "Já vi todos os tipos de guerra e conflito em minhas viagens, mas é raro encontrar alguém como você que ajuda crianças que perderam tudo.",
  ui_story_5076_50760200_76_dialog_content = "Talvez seja porque... Eu também cresci em um orfanato.",
  ui_story_5076_50760200_77_dialog_content = "E mesmo tendo perdido tudo, tive tantas pessoas bondosas cuidando de mim todo esse tempo. Esta é a minha maneira de expressar minha gratidão e retribuir a bondade que o mundo me mostrou.",
  ui_story_5076_50760200_78_dialog_content = "... Isso deve ser suficiente. Marcela, eu vou... treinar com as crianças agora.",
  ui_story_5076_50760200_79_dialog_content = "Não vá muito duro com eles, tá bom?",
  ui_story_5076_50760200_80_dialog_content = "Ludweiss.",
  ui_story_5076_50760200_81_dialog_content = "Hum?",
  ui_story_5076_50760200_82_dialog_content = "Tenho certeza de que você já viu mais tragédias em suas viagens do que pode contar... Mas, por favor, não se desanime. Este mundo ainda está cheio de bondade.",
  ui_story_5076_50760200_83_dialog_content = "Por favor, não pare de acreditar nas outras pessoas.",
  ui_story_5076_50760200_84_dialog_content = "Claro que eu sei disso. Afinal, conhecer vocês dois foi apenas mais uma coisa boa sobre este mundo.",
  ui_story_5076_50760200_85_dialog_content = "É incrível pensar que cheguei a este reino justo quando todos estavam celebrando o retorno de Adras.",
  ui_story_5076_50760200_86_dialog_content = "Mesmo agora, ainda consigo me lembrar dos sorrisos e aplausos em todas as ruas da capital real.",
  ui_story_5076_50760200_87_dialog_content = "Eu sei o que você quer dizer! Conhecer o herói Adras pela primeira vez sempre tem um efeito deslumbrante nas pessoas.",
  ui_story_5076_50760200_88_dialog_content = "Parece muita fanfarronice para mim, futura Sra. Adras.",
  ui_story_5076_50760200_89_dialog_content = "Th-Não foi isso que eu quis dizer!",
  ui_story_5076_50760200_90_dialog_content = "Eu também tenho ouvido falar da história heroica de Adras o tempo todo. É assim que eu entendo por que as pessoas se sentem tão seguras quando o veem.",
  ui_story_5076_50760200_91_dialog_content = "As crianças também o admiram muito. Ele é o herói de todos, mas...",
  ui_story_5076_50760200_92_dialog_content = "Marcela?",
  ui_story_5076_50760200_93_dialog_content = "Huh? O-Oh, não é nada!",
  ui_story_5076_50760200_94_dialog_content = "Esqueci de perguntar antes, mas para onde você está indo a seguir?",
  ui_story_5076_50760200_95_dialog_content = "Vou viajar pelo reino com alguns novos amigos antes de voltar para cá. Eles são pessoas bastante interessantes, assim como Adras.",
  ui_story_5076_50760200_96_dialog_content = "Infelizmente, agora não é o momento para falar sobre isso. Com certeza vou te apresentar a eles quando tiver a chance.",
  ui_story_5076_50760200_97_dialog_content = "Você vai ficar para o nosso casamento pelo menos, certo...?",
  ui_story_5076_50760200_98_dialog_content = "Claro que estou. Não se preocupe com isso.",
  ui_story_5076_50760300_1_dialog_content = "Procurando por algo, Adras? Por que você parece tão preocupado?",
  ui_story_5076_50760300_2_dialog_content = "Ludweiss, você viu a Marcela? Ela desapareceu sem dizer uma palavra esta manhã...",
  ui_story_5076_50760300_3_dialog_content = "Não se preocupe tanto. É apenas uma manhã.",
  ui_story_5076_50760300_4_dialog_content = "... Com o casamento se aproximando, parece que algo está pesando em seu coração, mas ela não me diz o que é.",
  ui_story_5076_50760300_5_dialog_content = "Você poderia me ajudar a procurá-la, Ludweiss?",
  ui_story_5076_50760300_6_dialog_content = "Entendi. Não se preocupe. Vou usar meus poderes psíquicos para ajudá-lo a encontrá-la.",
  ui_story_5076_50760300_7_dialog_content = "Apenas se acalme e me siga.",
  ui_story_5076_50760300_8_dialog_content = "Lá! Ela está na frente do templo!",
  ui_story_5076_50760300_9_dialog_content = "Hã? Ela está... alimentando um gato?",
  ui_story_5076_50760300_10_dialog_content = "Não, ela parece estar atordoada. Aquela gata quase terminou de comer a comida que ela trouxe - Deve haver algo incomodando ela afinal.",
  ui_story_5076_50760300_11_dialog_content = "Ludweiss... Você poderia ir falar com ela, por favor?",
  ui_story_5076_50760300_12_dialog_content = "Qual é o problema? Nosso destemido comandante está com medo de que sua própria noiva não queira falar com ele?",
  ui_story_5076_50760300_13_dialog_content = "Não... Estou com medo de que ela não me conte a verdade.",
  ui_story_5076_50760300_14_dialog_content = "Mas se ela conversar com um Celestita que lê a mente, ela provavelmente vai te dizer o que está em sua mente... Eu não quero que ela esconda seus problemas de mim por minha causa.",
  ui_story_5076_50760300_15_dialog_content = "Tudo bem, tudo bem. Sinceramente, vocês estão agindo como um casal de adolescentes desajeitados, apesar de estarem se casando amanhã.",
  ui_story_5076_50760300_16_dialog_content = "A-Ahem! Que surpresa encontrar você aqui, Marcela! Alimentando um dos porcos selvagens, huh?",
  ui_story_5076_50760300_17_dialog_content = "L-Ludweiss?",
  ui_story_5076_50760300_18_dialog_content = "Um certo comandante ficaria preocupado ao vê-lo aqui sozinho.",
  ui_story_5076_50760300_19_dialog_content = "Ahn? Ah!",
  ui_story_5076_50760300_20_dialog_content = "Você está certo, Adras provavelmente está preocupado comigo! Eu deveria voltar—",
  ui_story_5076_50760300_21_dialog_content = "Qual é a pressa? Você não quer me contar o que está pensando primeiro?",
  ui_story_5076_50760300_22_dialog_content = "Não adianta esconder de mim. Afinal, nós Celestitas somos conhecidos pela nossa habilidade de compreender emoções. Você poderia até dizer que somos o povo do amor!",
  ui_story_5076_50760300_23_dialog_content = "Algo tem te incomodado nos últimos dias, não é?",
  ui_story_5076_50760300_24_dialog_content = "Entendi... Realmente não há como esconder nada de você.",
  ui_story_5076_50760300_25_dialog_content = "Então, o que tem te incomodado ultimamente?",
  ui_story_5076_50760300_26_dialog_content = "Não é nada demais, eu só... Talvez seja porque o casamento está tão próximo, mas estou me sentindo um pouco assustado.",
  ui_story_5076_50760300_27_dialog_content = "Assustada?",
  ui_story_5076_50760300_28_dialog_content = "Há muito tempo atrás, eu era como todos os outros que ouviram as histórias de Adras, o herói do povo.",
  ui_story_5076_50760300_29_dialog_content = "Sempre achei que encontrar uma lenda como ele era impossível, mas no caos daquele dia... eu o vi.",
  ui_story_5076_50760300_30_dialog_content = "Apesar de seus ferimentos, ele derrotou aquelas pessoas tão facilmente e declarou que a cidade estava segura.",
  ui_story_5076_50760300_31_dialog_content = "Um conto clássico de uma jovem donzela se apaixonando por um cavaleiro de armadura reluzente. Foi quando você se apaixonou loucamente por ele?",
  ui_story_5076_50760300_32_dialog_content = "Na verdade, o oposto - Meu coração se sentia insuportavelmente triste porque eu não conseguia aceitar que nosso herói não era totalmente honesto.",
  ui_story_5076_50760300_33_dialog_content = "O herói em nossas lendas deveria ser invencível, e ainda assim ele estava coberto de inúmeras feridas. Isso me fez pensar quantas vezes isso aconteceu com ele, e se alguém se preocupou em cuidar dele.",
  ui_story_5076_50760300_34_dialog_content = "Em pouco tempo, me vi fazendo exatamente isso. Cuidando dele, entendendo ele...",
  ui_story_5076_50760300_35_dialog_content = "Mas isso não é uma coisa boa? Tratá-lo como uma pessoa viva e respirando?",
  ui_story_5076_50760300_36_dialog_content = "Mas... você não acha que eu me intrometi demais na vida dele?",
  ui_story_5076_50760300_37_dialog_content = "Por minha causa, ele não pode ir em uma missão importante com seus companheiros soldados... Ele realmente está disposto a abandonar seus deveres assim?",
  ui_story_5076_50760300_38_dialog_content = "Adras parece perfeitamente feliz para mim, você não acha?",
  ui_story_5076_50760300_39_dialog_content = "Ele uma vez me disse que mesmo quando criança, ele nunca estava longe do campo de batalha. Por causa disso, ele não sabia o que significava ser feliz. É por isso que meu coração se enche de alegria quando o vejo brincando feliz com as crianças...",
  ui_story_5076_50760300_40_dialog_content = "Mas eu posso dizer que ele não está acostumado a viver assim, e parece que ele está fazendo isso apenas por minha causa.",
  ui_story_5076_50760300_41_dialog_content = "Dar a ele um lar para voltar é uma coisa maravilhosa—",
  ui_story_5076_50760300_42_dialog_content = "E ainda assim, essa vida normal é a razão pela qual ele começou a ter pesadelos tão terríveis.",
  ui_story_5076_50760300_43_dialog_content = "Adras é... um herói para as pessoas. Só estou preocupado que eu esteja o segurando.",
  ui_story_5076_50760300_44_dialog_content = "Ah, mas não se preocupe muito com isso. Tenho certeza de que são apenas os nervos pré-casamento me afetando...",
  ui_story_5076_50760300_45_dialog_content = "Você mencionou algo disso para Adras? Não, certo?",
  ui_story_5076_50760300_46_dialog_content = "... No Dia do Triunfo, o rei o visitou pessoalmente. Algumas pessoas até sugeriram erguer uma estátua dele na praça da cidade.",
  ui_story_5076_50760300_47_dialog_content = "Mas depois disso, as façanhas heroicas de Adras chegaram ao fim. As pessoas lentamente começaram a esquecer dele, e o assunto ficou sem resolução.",
  ui_story_5076_50760300_48_dialog_content = "Sei que ele não se importa com fama ou glória, mas não posso deixar de sentir que ele desistiu de tanto por minha causa.",
  ui_story_5076_50760300_49_dialog_content = "Estou muito grato a ele por me ajudar a administrar este orfanato, mas ele ainda é Adras, o herói do povo.",
  ui_story_5076_50760300_50_dialog_content = "Ele ainda é uma estrela brilhante, uma que queima com grandes ambições.",
  ui_story_5076_50760300_51_dialog_content = "Assim como eu tenho coisas que só eu posso fazer, Adras tem coisas que só ele pode realizar.",
  ui_story_5076_50760300_52_dialog_content = "Você não está dizendo essas coisas porque quer deixá-lo, certo...?",
  ui_story_5076_50760300_53_dialog_content = "Está brincando? Eu só o machucaria fazendo algo assim... assim como a mim mesmo.",
  ui_story_5076_50760300_54_dialog_content = "Eu só queria que ele pudesse ser livre.",
  ui_story_5076_50760300_55_dialog_content = "Se o coração dele diz para lutar por casa e pátria, então é exatamente isso que eu quero que ele faça. Eu não quero que ele fique aqui só por causa de mim...",
  ui_story_5076_50760300_56_dialog_content = "É isso que você acha? Porque pelo que eu posso ver, Adras ainda é o mesmo herói que era naquele dia.",
  ui_story_5076_50760300_57_dialog_content = "Ele ajuda os idosos a cortar lenha, conserta o telhado do templo, treina a milícia e ainda encontra tempo para brincar com as crianças...",
  ui_story_5076_50760300_58_dialog_content = "Ele está usando cada grama de sua força para fazer o bem, e é por isso que todos nesta cidade o amam.",
  ui_story_5076_50760300_59_dialog_content = "Não é isso que um herói deveria fazer?",
  ui_story_5076_50760300_60_dialog_content = "Mas... A ameaça dos Eclipsitas ainda é muito real neste mundo.",
  ui_story_5076_50760300_61_dialog_content = "Esta guerra custou a muitas pessoas suas casas e até suas famílias. Adras e eu não somos exceção...",
  ui_story_5076_50760300_62_dialog_content = "Preocupo-me que se o Adras não usar seus talentos, ele vai se arrepender algum dia.",
  ui_story_5076_50760300_63_dialog_content = "Você deve dizer a ele se isso realmente te preocupa.",
  ui_story_5076_50760300_64_dialog_content = "Você não conhecerá os pensamentos um do outro sobre o assunto se continuar reprimindo seus sentimentos.",
  ui_story_5076_50760300_65_dialog_content = "Forasteiros como nós só o conhecerão como o comandante invencível.",
  ui_story_5076_50760300_66_dialog_content = "Você, por outro lado, é o único que pode ver as feridas por baixo da armadura dele e se preocupar com a morte de suas ambições.",
  ui_story_5076_50760300_67_dialog_content = "Tenho certeza de que ele vai entender se você compartilhar seus sentimentos com ele.",
  ui_story_5076_50760300_68_dialog_content = "Mas estou com medo de que ele enterre seus sonhos apenas para me acomodar.",
  ui_story_5076_50760300_69_dialog_content = "É isso que vem te incomodando todo esse tempo?",
  ui_story_5076_50760300_70_dialog_content = "A culpa é minha por te chatear assim.",
  ui_story_5076_50760300_71_dialog_content = "Adras?!",
  ui_story_5076_50760300_72_dialog_content = "N-Não, eu sou o único que deveria pedir desculpas por te preocupar!",
  ui_story_5076_50760300_73_dialog_content = "Ah, Adras. É a primeira vez que você falha em fazer alguém se sentir seguro?",
  ui_story_5076_50760300_74_dialog_content = "Perdi minha casa para os Eclipsitas há muito tempo. Desde que eu era uma criança, não senti nada além de ódio por eles, e por isso me alistei no exército assim que pude.",
  ui_story_5076_50760300_75_dialog_content = "Talvez por causa disso, nunca consegui entender o que significa viver em paz. Mesmo assim, isso me deu a determinação para proteger tudo o que prezo.",
  ui_story_5076_50760300_76_dialog_content = "Sempre que eu dormia na minha tenda, meus sonhos eram preenchidos com o cheiro de sangue.",
  ui_story_5076_50760300_77_dialog_content = "Ódio, raiva e camaradagem me mantiveram avançando contra o inimigo.",
  ui_story_5076_50760300_78_dialog_content = "Não havia fim à vista, mas eu estava disposto a continuar lutando pelo bem daqueles que estavam atrás de mim.",
  ui_story_5076_50760300_79_dialog_content = "Eu não vivi e lutei por eles porque tinha que fazer, mas porque eu queria. Enquanto houvesse alguém atrás de mim, eu me recusava a cair.",
  ui_story_5076_50760300_80_dialog_content = "Adras...",
  ui_story_5076_50760300_81_dialog_content = "Mas naquele dia, quando eu acabei com a rebelião e entrei na cidade—",
  ui_story_5076_50760300_82_dialog_content = "Foi quando você entrou no meu mundo. Você era apenas mais uma pessoa na multidão, mantendo um grupo de órfãos em segurança.",
  ui_story_5076_50760300_83_dialog_content = "Mas então você correu até mim de repente, me repreendendo enquanto limpava e enfaixava minhas feridas.",
  ui_story_5076_50760300_84_dialog_content = "Naquele momento, quando você me disse para ficar parado e parar de me esforçar tanto—",
  ui_story_5076_50760300_85_dialog_content = "Eu sabia que finalmente havia encontrado salvação de uma vida de morte e destruição.",
  ui_story_5076_50760300_86_dialog_content = "Você ainda se lembra do sonho que me deu naquele dia?",
  ui_story_5076_50760300_87_dialog_content = "Se o mundo voltar à paz mais uma vez, o que o grande Adras fará?",
  ui_story_5076_50760300_88_dialog_content = "O que mais posso fazer?",
  ui_story_5076_50760300_89_dialog_content = "Tudo que eu sei é guerra - Mas talvez eu possa me tornar um bardo viajante? No passado, as pessoas praticamente voltavam correndo para o trabalho sempre que me ouviam cantar.",
  ui_story_5076_50760300_90_dialog_content = "Você deve ter uma voz bastante única então!",
  ui_story_5076_50760300_91_dialog_content = "Eu nunca pensei sobre a vida após a guerra, então realmente não tenho nenhuma ideia.",
  ui_story_5076_50760300_92_dialog_content = "Parece que planejar não é exatamente o seu forte, mas não se preocupe. Eu vou te ajudar a pensar em algo.",
  ui_story_5076_50760300_93_dialog_content = "Com sua postura imponente, você pode se sair bem em vendas ou negociações.",
  ui_story_5076_50760300_94_dialog_content = "Você também é muito forte, então construir e reparar estruturas vale a pena considerar.",
  ui_story_5076_50760300_95_dialog_content = "Tenho certeza de que você poderia se tornar um padeiro de primeira linha com suas habilidades de fazer pão também.",
  ui_story_5076_50760300_96_dialog_content = "Não tenho certeza se poderia listar todas as suas qualidades positivas de uma vez, mas uma coisa é certa: seu futuro será brilhante.",
  ui_story_5076_50760300_97_dialog_content = "Meu futuro... não será brilhante a menos que você esteja nele.",
  ui_story_5076_50760300_98_dialog_content = "O que você faria se a paz realmente voltasse, Marcela?",
  ui_story_5076_50760300_99_dialog_content = "Eu? Bem... Para ser honesto, não tenho aspirações grandiosas para falar.",
  ui_story_5076_50760300_100_dialog_content = "Mas em um mundo pacífico, eu adoraria construir uma pequena casa de campo no interior e me tornar um fazendeiro de trigo... E talvez adotar algumas crianças também.",
  ui_story_5076_50760300_101_dialog_content = "E se você estivesse lá comigo, eu levaria você e as crianças para colher os campos comigo no outono.",
  ui_story_5076_50760300_102_dialog_content = "Eu ficaria feliz em passar esses dias tranquilos com você, observando campos dourados de trigo sob o brilho quente do sol—",
  ui_story_5076_50760300_103_dialog_content = "Então esse também é o meu sonho.",
  ui_story_5076_50760300_104_dialog_content = "Marcela, meu passado está longe de ser feliz, então tenho pouquíssima fé em qualquer deus. Mesmo assim, eu juro para você—",
  ui_story_5076_50760300_105_dialog_content = "Que eu, Adras, nunca vou parar de lutar pelo nosso sonho dourado. Nem jamais vou deixar o seu lado.",
  ui_story_5076_50760300_106_dialog_content = "Fizemos essa promessa juntos, mas você tem sofrido tanto por causa disso.",
  ui_story_5076_50760300_107_dialog_content = "No passado, eu não me importava se vivia ou morria no campo de batalha. Eu lutava pelas pessoas que queria proteger, quase sem consideração pela minha própria segurança.",
  ui_story_5076_50760300_108_dialog_content = "Mas depois que me apaixonei por você, comecei a lembrar do seu rosto mesmo em meio à batalha. Cada encontro com os Eclipsitas me fazia temer que eu não conseguisse voltar para você.",
  ui_story_5076_50760300_109_dialog_content = "Uma vez que eu tinha alguém para me importar, aparentemente perdi a capacidade de lutar como um demônio. Em um momento, me perguntei se isso estava me tornando fraco—",
  ui_story_5076_50760300_110_dialog_content = "Mas então eu voltei para casa, para você e as crianças. Eles me importunavam com perguntas e me imploravam para brincar com eles, todos sem o menor sinal de dor ou ódio em seus olhos.",
  ui_story_5076_50760300_111_dialog_content = "O que eu vinha protegendo o tempo todo... Foi quando isso se tornou claro para mim pela primeira vez.",
  ui_story_5076_50760300_112_dialog_content = "Adras...",
  ui_story_5076_50760300_113_dialog_content = "Eu não me tornei mais fraco por causa de você, Marcela. Eu fiquei mais forte.",
  ui_story_5076_50760300_114_dialog_content = "Finalmente tive medo da morte, e esse medo me fez querer continuar vivendo para poder ficar ao seu lado.",
  ui_story_5076_50760300_115_dialog_content = "Depois de uma vida longa e dolorosa, finalmente entendi o que significa viver.",
  ui_story_5076_50760300_116_dialog_content = "Não preciso de estátuas ou glória eterna. Na verdade, ficaria encantado se todos me esquecessem completamente!",
  ui_story_5076_50760300_117_dialog_content = "Se esse dia chegar, então o mundo definitivamente estará em paz.",
  ui_story_5076_50760300_118_dialog_content = "Tudo o que eu quero é continuar criando memórias com você, não importa o quão comuns elas possam ser.",
  ui_story_5076_50760300_119_dialog_content = "Adras... Eu sinto muito! Eu não sei o que eu estava pensando.",
  ui_story_5076_50760300_120_dialog_content = "Nunca parei para considerar seus sentimentos.",
  ui_story_5076_50760300_121_dialog_content = "Você não precisa se preocupar com isso, Marcela. Pelos nossos sonhos e memórias que estão por vir, eu nunca vou desistir de mim mesmo.",
  ui_story_5076_50760300_122_dialog_content = "Se o mundo precisar de mim algum dia, então eu pisarei no campo de batalha mais uma vez.",
  ui_story_5076_50760300_123_dialog_content = "Porque eu sei que um mundo tão bonito quanto este merece ser protegido—",
  ui_story_5076_50760300_124_dialog_content = "Então, por favor, não se preocupe, Marcela.",
  ui_story_5076_50760300_125_dialog_content = "Com os deuses e Ludweiss como nossas testemunhas, por favor, deixe seus medos de lado e case-se comigo!",
  ui_story_5076_50760300_126_dialog_content = "Eu... Eu vou!",
  ui_story_5076_50760300_127_dialog_content = "<color=#e8d9bb>No dia seguinte, a cidade organiza um grandioso casamento para o herói, e todos derramam bênçãos sinceras sobre o casal.</color>",
  ui_story_5076_50760300_128_dialog_content = "Enquanto trabalhamos para o nosso sonho, vamos continuar criando belas memórias juntos.",
  ui_story_5076_50760300_129_dialog_content = "Prometo valorizar cada momento maravilhoso de nossas vidas—",
  ui_story_5076_50760300_130_dialog_content = "Eu te amo, Marcela.",
  ui_story_5076_50760300_131_dialog_content = "Assim como eu, meu querido Adras—",
  ui_story_5076_50760300_132_dialog_content = "Eu te amo.",
  ui_story_5076_50760400_1_dialog_content = "... É basicamente assim que as coisas estão na frente; a força expedicionária está enfrentando tempos difíceis e retornará à capital em breve.",
  ui_story_5076_50760400_2_dialog_content = "Quando o General Aquiles retornar, solicitarei imediatamente o meu retorno ao serviço.",
  ui_story_5076_50760400_3_dialog_content = "Lutarei ao lado de todos na próxima batalha.",
  ui_story_5076_50760400_4_dialog_content = "Mas, Comandante, de acordo com as ordens do General, suas férias ainda não acabaram.",
  ui_story_5076_50760400_5_dialog_content = "E você ainda não tem herdeiros, e o General Aquiles não aprovará sua ida para a linha de frente.",
  ui_story_5076_50760400_6_dialog_content = "A saúde da Marcela não nos permite ter um filho próprio... Além disso, as crianças do orfanato também são nossa família—",
  ui_story_5076_50760400_7_dialog_content = "Oh? Temos um visitante?",
  ui_story_5076_50760400_8_dialog_content = "Augustine! Que boas notícias você nos trouxe hoje?",
  ui_story_5076_50760400_9_dialog_content = "Já faz um tempo, madame, e você ficou ainda mais bonita.",
  ui_story_5076_50760400_10_dialog_content = "Acabei de trazer algumas notícias da capital. Faz um tempo que não vemos o Comandante, e todos nós sentimos falta dele.",
  ui_story_5076_50760400_11_dialog_content = "Tenho certeza de que Adras também sente falta de todos vocês. Vocês precisam que ele volte mais cedo do que o esperado?",
  ui_story_5076_50760400_12_dialog_content = "Todos certamente ficariam muito felizes - mas, senhora, não ousamos tirar o Comandante de você assim tão facilmente.",
  ui_story_5076_50760400_13_dialog_content = "Está ficando tarde, Comandante Adras. Eu também deveria voltar para a capital agora.",
  ui_story_5076_50760400_14_dialog_content = "Cuide-se. Estarei aí em breve.",
  ui_story_5076_50760400_15_dialog_content = "Cuidem-se bem também, vocês dois.",
  ui_story_5076_50760400_16_dialog_content = "Adras, é a força de expedição...",
  ui_story_5076_50760400_17_dialog_content = "Eles estão bem, Marcela. Não ouça os rumores.",
  ui_story_5076_50760400_18_dialog_content = "Você quer voltar, não é?",
  ui_story_5076_50760400_19_dialog_content = "... Experimenta isso. Estive trabalhando em uma nova técnica de preparo.",
  ui_story_5076_50760400_20_dialog_content = "E exatamente onde você aprendeu—Mmm! É tão doce!",
  ui_story_5076_50760400_21_dialog_content = "E não queima nada! Eu amo isso!",
  ui_story_5076_50760400_22_dialog_content = "Aprendi isso com os sacerdotes.",
  ui_story_5076_50760400_23_dialog_content = "Então você tem ajudado nas reformas do templo para roubar suas técnicas de fabricação de vinho?",
  ui_story_5076_50760400_24_dialog_content = "Isso não parece nada com você, ó grande herói.",
  ui_story_5076_50760400_25_dialog_content = "Eles compartilharam voluntariamente seu conhecimento comigo para sua informação. Eles também disseram que é bom para o corpo, então fiz dois barris disso só para você.",
  ui_story_5076_50760400_26_dialog_content = "Os ingredientes que usei também foram um presente de outros, um sinal de apreciação por tudo que você fez por eles.",
  ui_story_5076_50760400_27_dialog_content = "Você tem aceitado presentes por mim quando eu não estou por perto? É uma coisa eles te agradecerem por ajudar na cidade, mas o que eu fiz?",
  ui_story_5076_50760400_28_dialog_content = "Você deveria simplesmente aceitar os presentes deles. Devolvê-los só iria constranger a todos.",
  ui_story_5076_50760400_29_dialog_content = "Bem, graças ao seu carisma, nossa casa está repleta de presentes.",
  ui_story_5076_50760400_30_dialog_content = "Você acha que eu tenho carisma?",
  ui_story_5076_50760400_31_dialog_content = "Isso mesmo!",
  ui_story_5076_50760400_32_dialog_content = "Não, eu acho que essas pessoas são realmente gentis. As crianças também estão sendo especialmente úteis agora. Apenas esta tarde, eles foram comigo para colher os campos perto do orfanato.",
  ui_story_5076_50760400_33_dialog_content = "... Então eu sei que você será cuidado mesmo se eu não estiver por perto por um tempo.",
  ui_story_5076_50760400_34_dialog_content = "Sempre fui bom com as pessoas, Adras. Ou você esqueceu?",
  ui_story_5076_50760400_35_dialog_content = "Sei que há muitas pessoas que precisam de você além de nós. Nossos vizinhos também sabem disso, é por isso que eles têm sido tão gentis ultimamente.",
  ui_story_5076_50760400_36_dialog_content = "Eles não querem te manter aqui só para eles, porque sabem que você tem coisas mais importantes para fazer.",
  ui_story_5076_50760400_37_dialog_content = "As chamas da guerra tiraram tantas pessoas de suas casas. No mínimo, quero proteger este canto pacífico do nosso mundo.",
  ui_story_5076_50760400_38_dialog_content = "Prometo que voltarei assim que puder, Marcela.",
  ui_story_5076_50760400_39_dialog_content = "Não se preocupe. Estaremos aqui esperando por você.",
  ui_story_5076_50760400_40_dialog_content = "Cuidaremos de nossa casa em sua ausência... Para que nosso herói sempre tenha um lugar para onde possa retornar.",
  ui_story_5076_50760400_41_dialog_content = "Voltarei em segurança para você, minha querida Marcela—",
  ui_story_5076_50760400_42_dialog_content = "Por você e por essas pessoas gentis, eu vou livrar nosso mundo do mal que nos ameaça.",
  ui_story_5076_50760400_43_dialog_content = "E quando eu retornar, nos encontraremos novamente em um mar de trigo dourado.",
  ui_story_5076_50760400_44_dialog_content = "Então é uma promessa.",
  ui_story_5076_50760400_45_dialog_content = "Adras?",
  ui_story_5076_50760400_46_dialog_content = "Ludweiss? O que você está fazendo aqui? Você veio aqui com a força de expedição?",
  ui_story_5076_50760400_47_dialog_content = "É complicado, e não tenho certeza por onde começar... Ainda assim, estou feliz em vê-lo novamente.",
  ui_story_5076_50760400_48_dialog_content = "Tenho certeza de que Aquiles também ficará feliz em vê-lo. Venha comigo.",
  ui_story_5076_50760400_49_dialog_content = "É isso... Comandante Adras?",
  ui_story_5076_50760400_50_dialog_content = "O Comandante Adras voltou?",
  ui_story_5076_50760400_51_dialog_content = "Comandante Adras!",
  ui_story_5076_50760400_52_dialog_content = "Comandante Adras, você está voltando ao serviço?",
  ui_story_5076_50760400_53_dialog_content = "Como... Como todos acabaram tão feridos?",
  ui_story_5076_50760400_54_dialog_content = "Nós...",
  ui_story_5076_50760400_55_dialog_content = "Dominic! Bruno! Onde estão vocês?",
  ui_story_5076_50760400_56_dialog_content = "Comandante, é realmente bom ver você.",
  ui_story_5076_50760400_57_dialog_content = "Anthony... O que aconteceu com seus olhos?",
  ui_story_5076_50760400_58_dialog_content = "Acho que estou ficando velho mesmo. Tive um lapso momentâneo e um Eclipsite sorrateiro levou um deles de mim.",
  ui_story_5076_50760400_59_dialog_content = "Desculpe, Comandante, eu decepcionei o Dominick. Foi tudo porque eu perdi meu escudo, e para me salvar, ele...",
  ui_story_5076_50760400_60_dialog_content = "O que aconteceu durante a expedição?",
  ui_story_5076_50760400_61_dialog_content = "Adras? É você?",
  ui_story_5076_50760400_62_dialog_content = "Realmente é você... Todos devem estar tão aliviados em ver você, Adras.",
  ui_story_5076_50760400_63_dialog_content = "General? Você parece completamente exausto. O que aconteceu com o...",
  ui_story_5076_50760400_64_dialog_content = "Encontramos um abismo sombrio no extremo norte.",
  ui_story_5076_50760400_65_dialog_content = "Incontáveis, poderosos Eclipsitas continuavam saindo de lá... Em termos de força e números, eles eram como nada que já tínhamos visto antes.",
  ui_story_5076_50760400_66_dialog_content = "Falhei em comandar adequadamente nossas tropas e, por isso, sofremos baixas devastadoras.",
  ui_story_5076_50760400_67_dialog_content = "Durante nossa retirada, Ludweiss também foi ferido pelo poder dos Eclipsitas.",
  ui_story_5076_50760400_68_dialog_content = "Não pareça tão preocupado, Adras. Felizmente, a Santa Silenciosa estava lá para me salvar e me deixar como novo!",
  ui_story_5076_50760400_69_dialog_content = "Nunca tinha visto Eclipsitas como esses. Eles não são algo que podemos lidar agora.",
  ui_story_5076_50760400_70_dialog_content = "E alguns deles... Estão muito além da nossa compreensão. Eu nem consigo imaginar uma maneira de derrotar essas monstruosidades.",
  ui_story_5076_50760400_71_dialog_content = "Não conseguimos erradicá-los lá no norte, e agora eles estão marchando em direção à capital real... Amaldiçoo todos eles!",
  ui_story_5076_50760400_72_dialog_content = "Fique tranquilo, por enquanto, General Achilles. Estou pronto para retornar à linha de frente e lutar ao lado de todos.",
  ui_story_5076_50760400_73_dialog_content = "Fomos pegos de surpresa da última vez. Com as preparações corretas, tenho certeza de que podemos acabar com o mal deles.",
  ui_story_5076_50760400_74_dialog_content = "Adras tem razão. Não podemos nos dar ao luxo de perder para essas coisas.",
  ui_story_5076_50760400_75_dialog_content = "Para derrotar a horda invasora de Eclipsitas, acredito que o melhor é me deixar voltar para a força e começar os preparativos de combate juntos.",
  ui_story_5076_50760400_76_dialog_content = "Dessa forma, podemos interromper a marcha deles antes que alcancem nossa casa.",
  ui_story_5076_50760400_77_dialog_content = "Adras... Você realmente mudou.",
  ui_story_5076_50760400_78_dialog_content = "Como estão as coisas ultimamente?",
  ui_story_5076_50760400_79_dialog_content = "Tenho estado bem. Nossos vizinhos têm cuidado muito bem de nós lá fora.",
  ui_story_5076_50760400_80_dialog_content = "Finalmente entendi o que você quis dizer quando me falou sobre a \"beleza da paz\".",
  ui_story_5076_50760400_81_dialog_content = "Você não terá medo da morte se eu te enviar para a linha de frente novamente?",
  ui_story_5076_50760400_82_dialog_content = "Você não é mais o mesmo homem. Você realmente pode abandonar seu instinto de autopreservação como antes?",
  ui_story_5076_50760400_83_dialog_content = "Não posso, e isso é porque... Eu entendo o significado do medo agora.",
  ui_story_5076_50760400_84_dialog_content = "Mas mesmo assim, tenho que proteger esses campos de trigo dourado e as pessoas que chamam aquele lugar de lar.",
  ui_story_5076_50760400_85_dialog_content = "É por isso que eu tenho que sobreviver.",
  ui_story_5076_50760400_86_dialog_content = "Eu vou sobreviver junto com meus camaradas de armas, e voltaremos juntos para nossos entes queridos.",
  ui_story_5076_50760400_87_dialog_content = "Entendi... Isso é um alívio.",
  ui_story_5076_50760400_88_dialog_content = "Você está muito mais forte agora do que no passado.",
  ui_story_5076_50760400_89_dialog_content = "Estou confiante de que posso confiar na sua proteção com a minha vida, assim como antes.",
  ui_story_5076_50760400_90_dialog_content = "Pela glória do nosso reino, cavalgaremos para a batalha mais uma vez.",
  ui_story_5076_50760400_91_dialog_content = "Parece que você está se sentindo muito melhor agora. Eu não percebi que Adras era um orador tão poderoso!",
  ui_story_5076_50760400_92_dialog_content = "Acho que Adras realmente é um herói para todos.",
  ui_story_5076_50760400_93_dialog_content = "Concordo. Se todos no nosso exército fossem como Adras... Até os Eclipsitas mais fortes não teriam chance contra nós.",
  ui_story_5076_50760400_94_dialog_content = "Eu não me importaria de fazer parte desse exército!",
  ui_story_5076_50760400_95_dialog_content = "Devo começar os preparativos imediatamente. Se me dá licença.",
  ui_story_5076_50760400_96_dialog_content = "Adras.",
  ui_story_5076_50760400_97_dialog_content = "Sim?",
  ui_story_5076_50760400_98_dialog_content = "Valorize tudo o que você tem na vida.",
  ui_story_5076_50760400_99_dialog_content = "Não tenho intenção de fazer o contrário, senhor.",
  ui_story_5076_50760400_100_dialog_content = "Afinal, eu fiz uma promessa a ela.",
  ui_story_5076_50760501_1_dialog_content = "Isso deve ser o último. Não acho que haja mais nada para tirar do orfanato.",
  ui_story_5076_50760501_2_dialog_content = "São estas... espadas de treinamento de madeira Adras?",
  ui_story_5076_50760501_3_dialog_content = "As crianças continuam pedindo para aprender esgrima para que possam proteger a cidade. Trazer esses de volta pode acalmá-los.",
  ui_story_5076_50760501_4_dialog_content = "Ah, se eu pudesse trazer esse mural do nosso dia de casamento. Foi um momento tão precioso...",
  ui_story_5076_50760501_5_dialog_content = "Nunca pensei que os Eclipsitas chegariam a este lugar.",
  ui_story_5076_50760501_6_dialog_content = "Por quanto tempo mais o orfanato permanecerá fechado? Eu gostaria de poder ver aquelas crianças felizes correndo pelos campos de trigo mais uma vez.",
  ui_story_5076_50760501_7_dialog_content = "Tudo ficará bem. Enquanto Adras e os outros lutam na linha de frente, lutaremos para manter esta cidade segura.",
  ui_story_5076_50760501_8_dialog_content = "Desculpe por ainda não ter me recuperado... Caso contrário, eu estaria lá fora ajudando todo mundo também.",
  ui_story_5076_50760501_9_dialog_content = "Não precisa se desculpar, Ludweiss. Você já fez tanto por nós.",
  ui_story_5076_50760501_10_dialog_content = "Seus avisos oportunos têm nos mantido seguros nos últimos dias.",
  ui_story_5076_50760501_11_dialog_content = "As defesas da cidade estão sendo reparadas agora?",
  ui_story_5076_50760501_12_dialog_content = "Sim. Também estamos construindo um abrigo sob o templo e um túnel de fuga.",
  ui_story_5076_50760501_13_dialog_content = "Todos estão trabalhando tão duro juntos e se encorajando o tempo todo.",
  ui_story_5076_50760501_14_dialog_content = "As pessoas Adras treinadas também formaram uma pequena milícia. Posso dizer que todos estão cheios de esperança.",
  ui_story_5076_50760501_15_dialog_content = "Tudo isso é graças a você, Marcela... Antes dos reforços chegarem, você foi quem deu a eles esperança e os estimulou a agir.",
  ui_story_5076_50760501_16_dialog_content = "Eu estava apenas fazendo minha pequena parte. Eles são os que fizeram todo o trabalho—",
  ui_story_5076_50760501_17_dialog_content = "Vamos lá, vamos levar essas coisas de volta para as crianças.",
  ui_story_5076_50760501_18_dialog_content = "Achilles te enviou para entregar esta carta? Qual é a situação na linha de frente?",
  ui_story_5076_50760501_19_dialog_content = "Comandante Adras, com sua legião, está repelindo o massivo ataque à capital e garantiu uma série de vitórias.",
  ui_story_5076_50760501_20_dialog_content = "Sua Majestade ordenou que ele auxiliasse o General Aquiles na liderança das tropas para perseguir e exterminar os Eclipsitas.",
  ui_story_5076_50760501_21_dialog_content = "O comandante designado aqui para defender esta cidade é um seguidor do Alto Sacerdote Lucius. Essa é toda a mensagem que eu deveria entregar.",
  ui_story_5076_50760501_22_dialog_content = "Mas além disso, Srta. Ludweiss, eu tenho algumas informações...",
  ui_story_5076_50760501_23_dialog_content = "Parece que o Alto Sacerdote Lucius está disputando o mérito, pretendendo concentrar forças para atacar os flancos dos Eclipsitas. Ele já partiu e redistribuiu as forças de defesa ao longo do caminho!",
  ui_story_5076_50760501_24_dialog_content = "Em outras palavras, é improvável que esta cidade receba qualquer apoio militar. É isso?",
  ui_story_5076_50760501_25_dialog_content = "... Eu vou ficar, mesmo que isso signifique dar minha vida para proteger os civis na cidade.",
  ui_story_5076_50760501_26_dialog_content = "Não diga isso!",
  ui_story_5076_50760501_27_dialog_content = "A vida é a coisa mais preciosa deste mundo! Não fale sobre ela como se fosse algo menos do que isso!",
  ui_story_5076_50760501_28_dialog_content = "S-Sim! Peço desculpas por isso!",
  ui_story_5076_50760501_29_dialog_content = "Você tem experiência militar. Deixarei o comando da milícia em suas mãos.",
  ui_story_5076_50760501_30_dialog_content = "Eu tenho que...",
  ui_story_5076_50760501_31_dialog_content = "Tem que fazer o que, Ludweiss?",
  ui_story_5076_50760501_32_dialog_content = "Marcela...?",
  ui_story_5076_50760501_33_dialog_content = "Vou ajudar a defender as muralhas da cidade.",
  ui_story_5076_50760501_34_dialog_content = "Então você ouviu tudo?",
  ui_story_5076_50760501_35_dialog_content = "Sim, mas eu não vou contar a ninguém sobre isso ainda. Vocês dois têm que fazer o mesmo.",
  ui_story_5076_50760501_36_dialog_content = "Vou defender este lugar com todos. Esta é a nossa casa, assim como a casa do grande herói Adras.",
  ui_story_5076_50760501_37_dialog_content = "Tenho que sair por um tempo, Marcela.",
  ui_story_5076_50760501_38_dialog_content = "Então, por favor, tenha cuidado... E não se esforce demais.",
  ui_story_5076_50760501_39_dialog_content = "Onde exatamente você está indo?",
  ui_story_5076_50760501_40_dialog_content = "A horda de Eclipsitas chegará em breve. Eu tenho que fazer algo que só nós, os Caelestites, podemos fazer...",
  ui_story_5076_50760501_41_dialog_content = "Vou usar meus poderes para passar por suas fileiras e entregar uma mensagem para Adras.",
  ui_story_5076_50760501_42_dialog_content = "Mas isso é muito perigoso!",
  ui_story_5076_50760501_43_dialog_content = "Adras precisa saber. Por sua causa, e pelo bem de toda a cidade.",
  ui_story_5076_50760501_44_dialog_content = "Nunca poderíamos retribuir tudo o que você faz por nós, Ludweiss...",
  ui_story_5076_50760501_45_dialog_content = "Por favor, seja cuidadoso.",
  ui_story_5076_50760501_46_dialog_content = "Eu sou apenas uma andarilha que perdeu seu caminho. Foi apenas graças a todos aqui que eu me lembrei da beleza de Eraveil, minha casa.",
  ui_story_5076_50760501_47_dialog_content = "Vou garantir que traga Adras aqui. Até lá, fique atento e não perca a esperança.",
  ui_story_5076_50760501_48_dialog_content = "(Eu definitivamente vou conseguir—)",
  ui_story_5076_50760501_49_dialog_content = "(Não importa o quão longe ou quão difícil o caminho possa ser—)",
  ui_story_5076_50760501_50_dialog_content = "<color=#e8d9bb>Eclipsitas do extremo norte infestaram todo o continente, incendiando até mesmo a natureza selvagem.</color>",
  ui_story_5076_50760501_51_dialog_content = "<color=#e8d9bb>O fogo devasta as casas dos civis, e os outrora serenos campos de trigo estão quase totalmente queimados.</color>",
  ui_story_5076_50760501_52_dialog_content = "Adras!",
  ui_story_5076_50760501_53_dialog_content = "Huh? O que há com toda a gritaria?",
  ui_story_5076_50760501_54_dialog_content = "Adras! Eu... Eu finalmente encontrei você...",
  ui_story_5076_50760501_55_dialog_content = "Ludweiss? O que você está fazendo aqui? Essas queimaduras... Você está seriamente machucado!",
  ui_story_5076_50760501_56_dialog_content = "Chame um médico, Anthony!",
  ui_story_5076_50760501_57_dialog_content = "Esqueça isso! V-Você tem que vir comigo!",
  ui_story_5076_50760501_58_dialog_content = "Lucius transferiu todas as suas forças para fora da cidade! Ele deixou Marcela e os outros se defenderem sozinhos!",
  ui_story_5076_50760501_59_dialog_content = "O que você disse?",
  ui_story_5076_50760501_60_dialog_content = "Marcela, eu...",
  ui_story_5076_50760501_61_dialog_content = "Droga! Estávamos prestes a lançar um contra-ataque decisivo!",
  ui_story_5076_50760501_62_dialog_content = "Como comandante interino, não posso simplesmente abandonar meus soldados.",
  ui_story_5076_50760501_63_dialog_content = "Vá, Adras.",
  ui_story_5076_50760501_64_dialog_content = "Mas General—",
  ui_story_5076_50760501_65_dialog_content = "O inimigo já está praticamente morto. Você e a Legião Northwind já fizeram o suficiente pelo reino.",
  ui_story_5076_50760501_66_dialog_content = "Nossas forças principais deveriam ser as que protegem sua casa, mas infelizmente... Você e seus homens terão que fazer essa jornada sozinhos.",
  ui_story_5076_50760501_67_dialog_content = "Isso é uma ordem.",
  ui_story_5076_50760501_68_dialog_content = "General Achilles... entendido.",
  ui_story_5076_50760501_69_dialog_content = "Tem certeza de que quer vir comigo, Ludweiss? Nosso exército tem vários médicos capazes.",
  ui_story_5076_50760501_70_dialog_content = "Se você não conseguir fazer a marcha, sempre pode ficar aqui e se recuperar.",
  ui_story_5076_50760501_71_dialog_content = "Não, eu preciso voltar com você e garantir que a Marcela está bem.",
  ui_story_5076_50760501_72_dialog_content = "Prometi que te traria de volta para ela.",
  ui_story_5076_50760501_73_dialog_content = "Então, vamos indo.",
  ui_story_5076_50760501_74_dialog_content = "Soldados da Legião Northwind! Ouçam meu chamado—",
  ui_story_5076_50760501_75_dialog_content = "<color=#e8d9bb>Sua voz ressoante ecoa pelas tendas, e os soldados respondem em uníssono.</color>",
  ui_story_5076_50760501_76_dialog_content = "<color=#e8d9bb>Soldados, cuja pátria foi protegida por seu comandante inúmeras vezes, finalmente conseguem defender a casa de seu comandante.</color>",
  ui_story_5076_50760501_77_dialog_content = "Não há fim para eles - saia do meu caminho!!!",
  ui_story_5076_50760501_78_dialog_content = "Por que há tantos Eclipsitas embaixo da cidade?",
  ui_story_5076_50760501_79_dialog_content = "Todos eles estão se reunindo aqui?",
  ui_story_5076_50760501_80_dialog_content = "Quantos soldados Lucius retirou da luta? Quantas vidas foram perdidas por causa dele?!",
  ui_story_5076_50760501_81_dialog_content = "Mantenha a calma, Adras. Estamos perto da cidade—",
  ui_story_5076_50760501_82_dialog_content = "Você tem deixado tropas em todas as cidades que passamos. É por isso que parece que há ainda mais inimigos para lutar agora.",
  ui_story_5076_50760501_83_dialog_content = "Não estamos nos movendo rápido o suficiente... Eu prometi que protegeria todos eles! Eu dei minha palavra!",
  ui_story_5076_50760501_84_dialog_content = "Eu vi! Comandante Adras, os muros da cidade estão intactos, e parece que o portão da cidade acaba de ser violado.",
  ui_story_5076_50760501_85_dialog_content = "As pessoas estão se abrigando no templo, Adras.",
  ui_story_5076_50760501_86_dialog_content = "Há um túnel de fuga sob ele. Se eles não conseguirem defender os portões do templo, podem usar esse túnel para escapar atrás da cidade.",
  ui_story_5076_50760501_87_dialog_content = "Dieter, Vivia, levem uma equipe de cavaleiros e sigam para os arredores da cidade. Procurem por sobreviventes e eliminem quaisquer Eclipsitas vagando pela área.",
  ui_story_5076_50760501_88_dialog_content = "Quintas, formem uma falange e flanqueiem o inimigo de ambos os lados. Não deixem um único Eclipsita escapar.",
  ui_story_5076_50760501_89_dialog_content = "O resto de vocês, venham comigo. Vamos atacar a retaguarda deles e forçar nossa entrada na cidade!",
  ui_story_5076_50760501_90_dialog_content = "Fique perto, Ludweiss.",
  ui_story_5076_50760501_91_dialog_content = "<color=#FFB400>Para a batalha—!!!</color>",
  ui_story_5076_50760501_92_dialog_content = "<color=#FFB400>Elimine todos esses Eclipsitas imundos até o último!</color>",
  ui_story_5076_50760501_93_dialog_content = "Comandante, o Templo ainda não caiu, e os membros da milícia ainda estão defendendo dentro do salão principal!",
  ui_story_5076_50760501_94_dialog_content = "Só um pouco mais rápido—",
  ui_story_5076_50760501_95_dialog_content = "Espere por mim, Adras!",
  ui_story_5076_50760501_96_dialog_content = "Ai, é a minha velha ferida? Por que está incomodando justo agora...",
  ui_story_5076_50760501_97_dialog_content = "Não, tem algo errado... Algo na minha cabeça...",
  ui_story_5076_50760501_98_dialog_content = "Adras...",
  ui_story_5076_50760502_1_dialog_content = "É Adras!",
  ui_story_5076_50760502_2_dialog_content = "Adras veio em nosso socorro!",
  ui_story_5076_50760502_3_dialog_content = "Oi, Adras!",
  ui_story_5076_50760502_4_dialog_content = "Vocês estão todos seguros agora, então, por favor, permaneçam calmos. Conseguimos garantir uma rota de fuga.",
  ui_story_5076_50760502_5_dialog_content = "Estão todos bem? Houve alguma baixa?",
  ui_story_5076_50760502_6_dialog_content = "Há outras áreas que precisam de apoio?",
  ui_story_5076_50760502_7_dialog_content = "Não, Comandante Adras, nós somos a retaguarda; outros já escaparam pelo corredor.",
  ui_story_5076_50760502_8_dialog_content = "Tudo graças à Marcela; ela nos motivou a defender a cidade, e é por isso que conseguimos resistir por esses dias.",
  ui_story_5076_50760502_9_dialog_content = "Se você tivesse chegado aqui um pouco mais tarde, todos já poderiam ter...",
  ui_story_5076_50760502_10_dialog_content = "Marcela...? Onde ela está agora? Ela já fugiu?",
  ui_story_5076_50760502_11_dialog_content = "Huh? Você não encontrou a Marcela no seu caminho para cá?",
  ui_story_5076_50760502_12_dialog_content = "Para ganhar tempo para a retirada de todos, ela liderou a vanguarda perto do Templo para distrair os Eclipsitas...",
  ui_story_5076_50760502_13_dialog_content = "Não... Não...",
  ui_story_5076_50760502_14_dialog_content = "Não me assuste assim, meu amor—",
  ui_story_5076_50760502_15_dialog_content = "Espere, Adras! Deixe-me tentar sentir a localização dela!",
  ui_story_5076_50760502_16_dialog_content = "Por favor, Ludweiss...",
  ui_story_5076_50760502_17_dialog_content = "Não há necessidade do resto de vocês me seguirem! Recuem e defendam os civis da cidade—",
  ui_story_5076_50760502_18_dialog_content = "Não consigo filtrar todos os pensamentos e sentimentos caóticos. Tudo o que posso dizer é que há Eclipsitas se reunindo a leste do templo.",
  ui_story_5076_50760502_19_dialog_content = "Saia do meu caminho, seus monstros podres!",
  ui_story_5076_50760502_20_dialog_content = "Mais rápido! Preciso me mover mais rápido!!!",
  ui_story_5076_50760502_21_dialog_content = "Esse lugar—",
  ui_story_5076_50760502_22_dialog_content = "As pessoas no chão estavam com a milícia. Que visão horrível...",
  ui_story_5076_50760502_23_dialog_content = "Eles conseguiram matar muitos Eclipsites logo à frente também.",
  ui_story_5076_50760502_24_dialog_content = "Infelizmente, este lugar está além de ser salvo—",
  ui_story_5076_50760502_25_dialog_content = "Ah! Não... é o Augustine... Isso não pode ser.",
  ui_story_5076_50760502_26_dialog_content = "Valentes e honrados soldados... May suas almas finalmente conhecem a paz.",
  ui_story_5076_50760502_27_dialog_content = "... Eclipsitas podres.",
  ui_story_5076_50760502_28_dialog_content = "Marcela! Você consegue me ouvir?!",
  ui_story_5076_50760502_29_dialog_content = "Não se preocupe, estou indo atrás de você!",
  ui_story_5076_50760502_30_dialog_content = "(N-Não—)",
  ui_story_5076_50760502_31_dialog_content = "Quem? Quem está aí?",
  ui_story_5076_50760502_32_dialog_content = "(Alguém está na minha cabeça, falando comigo... Será por causa das minhas lesões anteriores?)",
  ui_story_5076_50760502_33_dialog_content = "(Você precisa acordar—)",
  ui_story_5076_50760502_34_dialog_content = "(Não assista até o final—)",
  ui_story_5076_50760502_35_dialog_content = "O quê?",
  ui_story_5076_50760502_36_dialog_content = "<size=40>Não... Nããão!!!</size>",
  ui_story_5076_50760502_37_dialog_content = "Adras???",
  ui_story_5076_50760502_38_dialog_content = "Argh, minha cabeça... Está me matando.",
  ui_story_5076_50760502_39_dialog_content = "<size=40>Não me assuste assim, Marcela—</size>",
  ui_story_5076_50760502_40_dialog_content = "<color=#FFB400><size=45>Marcela!!!</size></color>",
  ui_story_5076_50760502_41_dialog_content = "O que está acontecendo...",
  ui_story_5076_50760502_42_dialog_content = "Adras, Marcela...",
  ui_story_5076_50760502_43_dialog_content = "Espere por mim...",
  ui_story_5076_50760502_44_dialog_content = "!!!",
  ui_story_5076_50760502_45_dialog_content = "Graças aos deuses—",
  ui_story_5076_50760502_46_dialog_content = "Por não roubar minha amada de mim, minha doce Marcela—",
  ui_story_5076_50760502_47_dialog_content = "Marcela! Sou eu, estou bem aqui! Eu voltei, assim como prometi.",
  ui_story_5076_50760502_48_dialog_content = "Não se preocupe, estamos indo para casa agora...",
  ui_story_5076_50760502_49_dialog_content = "(Memórias são—)",
  ui_story_5076_50760502_50_dialog_content = "<color=#FFB400>(Uma maldição.)</color>",
  ui_story_5076_50760502_51_dialog_content = "(Mas por agora... Por favor, não atrapalhe o reencontro deles.)",
  ui_story_5076_50760502_52_dialog_content = "Essa voz na minha cabeça... Quem é você...?",
  ui_story_5076_50760502_53_dialog_content = "Você finalmente voltou, Adras.",
  ui_story_5076_50760502_54_dialog_content = "Esperei tanto... por você.",
  ui_story_5076_50760502_55_dialog_content = "Poupe suas forças, meu amor. Vou chamar um curandeiro para cuidar das suas feridas antes de irmos para casa.",
  ui_story_5076_50760502_56_dialog_content = "Aquelas duas barris de vinho que você me deixou... Eu compartilhei com todos.",
  ui_story_5076_50760502_57_dialog_content = "Todos disseram que estava delicioso e que a sua doçura os fez sentir tão felizes.",
  ui_story_5076_50760502_58_dialog_content = "É por isso que não tivemos medo, nem por um momento—",
  ui_story_5076_50760502_59_dialog_content = "Adras... sempre que penso em você, meu coração se enche de esperança.",
  ui_story_5076_50760502_60_dialog_content = "Obrigado por cumprir sua promessa.",
  ui_story_5076_50760600_1_dialog_content = "<color=#e8d9bb>A cidade, outrora devastada por monstros, agora abraça os dias de reconstrução. A fé vinda dos heróis enche seus moradores de esperança.</color>",
  ui_story_5076_50760600_2_dialog_content = "<color=#e8d9bb>Ainda assim, em meio a essa atmosfera próspera, muitos ainda se encontram sem um lar.</color>",
  ui_story_5076_50760600_3_dialog_content = "Tenha cuidado ao mover os destroços e fique atento aos pedestres! Se precisar de ajuda, peça aos soldados da Legião!",
  ui_story_5076_50760600_4_dialog_content = "Sim, senhor.",
  ui_story_5076_50760600_5_dialog_content = "Vamos.",
  ui_story_5076_50760600_6_dialog_content = "... Claro.",
  ui_story_5076_50760600_7_dialog_content = "Adras, o que...?",
  ui_story_5076_50760600_8_dialog_content = "Não é nada. Só vamos dar um passeio.",
  ui_story_5076_50760600_9_dialog_content = "\"Nós\"? Ah... Ah! Por favor, não se preocupe demais; em breve concluiremos a reconstrução.",
  ui_story_5076_50760600_10_dialog_content = "Marcela? Eu pensei que você era amiga daquele homem... Por que você não deu pelo menos um oi?",
  ui_story_5076_50760600_11_dialog_content = "... Está tudo bem. Vamos apenas continuar.",
  ui_story_5076_50760600_12_dialog_content = "Para onde você gostaria de ir? O templo, talvez?",
  ui_story_5076_50760600_13_dialog_content = "Não! Qualquer lugar, menos o templo! Eu... ainda tenho medo daquele lugar.",
  ui_story_5076_50760600_14_dialog_content = "Tudo bem, podemos ir a outro lugar. Que tal visitarmos as crianças? Elas estão indo bem, mas tenho certeza de que você ainda está preocupado com elas.",
  ui_story_5076_50760600_15_dialog_content = "Eu o encontrei, Aquiles. Ele está por aqui.",
  ui_story_5076_50760600_16_dialog_content = "...",
  ui_story_5076_50760600_17_dialog_content = "Adras... Você está bem?",
  ui_story_5076_50760600_18_dialog_content = "... Ludweiss?",
  ui_story_5076_50760600_19_dialog_content = "A batalha acabou, Adras. Por que você ainda está aqui?",
  ui_story_5076_50760600_20_dialog_content = "Não há mais ninguém para defender este lugar. Eu tenho que proteger as pessoas aqui.",
  ui_story_5076_50760600_21_dialog_content = "Ah! Não tenha medo, Marcela! É apenas o General Achilles.",
  ui_story_5076_50760600_22_dialog_content = "Desculpe, mas a batalha realmente afetou muito a Marcela. Por favor, perdoe-a se ela estiver com muito medo para dizer olá.",
  ui_story_5076_50760600_23_dialog_content = "Adras, Marcela é—",
  ui_story_5076_50760600_24_dialog_content = "Aquiles!",
  ui_story_5076_50760600_25_dialog_content = "O que é isso? Vocês dois estão agindo de maneira tão estranha, especialmente você Ludweiss. Por que você não vem visitar a Marcela com mais frequência?",
  ui_story_5076_50760600_26_dialog_content = "... Olhe para mim, Adras.",
  ui_story_5076_50760600_27_dialog_content = "Sim? Ah, antes que eu esqueça... Os Eclipsitas na linha de frente foram resolvidos? Podemos finalmente desfrutar de alguma paz novamente?",
  ui_story_5076_50760600_28_dialog_content = "Conseguimos empurrar os Eclipsitas de volta para o norte, mas ainda não podemos fazer nada sobre o abismo que encontramos lá.",
  ui_story_5076_50760600_29_dialog_content = "Está disposto a voltar para a luta, Adras?",
  ui_story_5076_50760600_30_dialog_content = "Claro. Afinal, é meu dever proteger minha casa e meu país.",
  ui_story_5076_50760600_31_dialog_content = "Você está disposta a me deixar voltar para a batalha, certo Marcela? Não se preocupe, sempre cumprirei minha promessa para você.",
  ui_story_5076_50760600_32_dialog_content = "...",
  ui_story_5076_50760600_33_dialog_content = "Ludweiss, você uma vez me disse que o amor é a fonte do poder de um Celestita. Impulsionado pela força das emoções, você e seu povo realizaram coisas extraordinárias.",
  ui_story_5076_50760600_34_dialog_content = "Diga-me, existe alguma maneira de extrair as emoções de um Auroriano e preservá-las?",
  ui_story_5076_50760600_35_dialog_content = "O que exatamente você está propondo?",
  ui_story_5076_50760600_36_dialog_content = "Neste momento, Adras precisa ser impulsionado à ação pelo ódio e vingança. No entanto, não quero que o amor em seu coração seja consumido por isso.",
  ui_story_5076_50760600_37_dialog_content = "Do que diabos vocês dois estão falando?",
  ui_story_5076_50760600_38_dialog_content = "Ludweiss, preciso saber se há uma maneira de extrair esse amor e mantê-lo seguro.",
  ui_story_5076_50760600_39_dialog_content = "Entendi... Vou pensar em alguma coisa.",
  ui_story_5076_50760600_40_dialog_content = "Você está disposto a me emprestar seu escudo e força novamente, Adras?",
  ui_story_5076_50760600_41_dialog_content = "É claro que sim!",
  ui_story_5076_50760600_42_dialog_content = "Quanto você odeia os Eclipsitas? Você está disposto a dedicar sua vida e tudo o que você é para a aniquilação completa deles?",
  ui_story_5076_50760600_43_dialog_content = "Os Eclipsitas... Isso nem precisa ser dito! Eu não tenho nada além de ódio no meu coração por eles...",
  ui_story_5076_50760600_44_dialog_content = "Mesmo com o peso da eternidade em seus ombros, você jura lutar contra esse mal com todo o seu coração até que nada reste?",
  ui_story_5076_50760600_45_dialog_content = "Eu... Eu juro.",
  ui_story_5076_50760600_46_dialog_content = "Então, em nome de nossos orgulhosos soldados e de mim mesmo, nossas vidas estão novamente em suas mãos capazes.",
  ui_story_5076_50760600_47_dialog_content = "Bem-vindo de volta à linha de serviço, Adras.",
  ui_story_5076_50760600_48_dialog_content = "Bem-vindo de volta à guerra.",
  ui_story_5076_50760600_49_dialog_content = "Então, por onde devo começar?",
  ui_story_5076_50760600_50_dialog_content = "Para erradicar o abismo no norte, a corte real propôs um novo método para aumentar nossos poderes.",
  ui_story_5076_50760600_51_dialog_content = "Um projeto que nos consumirá, mas não antes de purgarmos nosso mundo de todo o mal.",
  ui_story_5076_50760600_52_dialog_content = "E o nome desse projeto é—",
  ui_story_5076_50760600_53_dialog_content = "<color=#FFB400>Os Caçadores Silenciosos.</color>",
  ui_story_5076_50760701_1_dialog_content = "<color=#e8d9bb>Após uma grande vitória na frente principal, as forças reais se espalharam e contra-atacaram, com o objetivo de recuperar as cidades dominadas pelos Eclipsitas.</color>",
  ui_story_5076_50760701_2_dialog_content = "<color=#e8d9bb>Entre eles, alguns foram completamente reduzidos a um \"ninho\" dos Eclipsitas.</color>",
  ui_story_5076_50760701_3_dialog_content = "<color=#e8d9bb>Naquele momento, os \"heróis\" com novas fachadas pisarão no palco.</color>",
  ui_story_5076_50760701_4_dialog_content = "Relatório! As sentinelas confirmaram a condição dentro da cidade - ela caiu completamente, com Eclipsitas correndo à solta!",
  ui_story_5076_50760701_5_dialog_content = "E as pessoas? Existem sinais de sobrevivência delas?",
  ui_story_5076_50760701_6_dialog_content = "... Nenhum sobreviveu.",
  ui_story_5076_50760701_7_dialog_content = "Pare o ataque. Seus soldados não têm como lutar para entrar na cidade.",
  ui_story_5076_50760701_8_dialog_content = "Os Eclipsitas não conhecem o medo. A menos que façamos a cidade cair sobre suas cabeças, eles não recuarão.",
  ui_story_5076_50760701_9_dialog_content = "General... Não, Capitão, o que fazemos agora?",
  ui_story_5076_50760701_10_dialog_content = "Um dos meus companheiros de esquadrão já está a caminho. Coloque o resto de suas forças em espera na retaguarda.",
  ui_story_5076_50760701_11_dialog_content = "Você quer dizer... Ah!",
  ui_story_5076_50760701_12_dialog_content = "Você aí, soldado. Você está no meu caminho, então por favor dê um passo para a direita.",
  ui_story_5076_50760701_13_dialog_content = "<color=#e8d9bb>Seguindo as ordens do comandante desconhecido, o soldado se move ligeiramente para o lado, e um relâmpago irrompe de suas pontas dos dedos, demolindo o portão da cidade que havia resistido ao seu ataque prolongado.</color>",
  ui_story_5076_50760701_14_dialog_content = "Os portões podem estar abertos, mas ainda há muitos Eclipsitas astutos escondidos atrás das muralhas da cidade. Eu vou deixá-los para você... Cynthia.",
  ui_story_5076_50760701_15_dialog_content = "<color=#e8d9bb>Com o arco longo tenso como uma lua crescente, a heroína em um tom verdejante libera elegantemente uma chuva de flechas. Cada vez que ela puxa a corda do arco, os Eclipsitas habilidosos em ataques à distância caem um após o outro.</color>",
  ui_story_5076_50760701_16_dialog_content = "Bom tiro! Você deve ter realmente os agitado com aquele último ataque, porque eles estão começando a sair do portão.",
  ui_story_5076_50760701_17_dialog_content = "Comigo, cavaleiros! Estamos avançando para a batalha!",
  ui_story_5076_50760701_18_dialog_content = "Os cavaleiros não têm chance contra esses gigantes Eclipsitas, Freya.",
  ui_story_5076_50760701_19_dialog_content = "Eles vão ficar bem! Friegson - A primeira onda é toda sua!",
  ui_story_5076_50760701_20_dialog_content = "<color=#e8d9bb>Com suas palavras ressonantes, um incêndio se acende ao longe. Chamas rugindo engolem impiedosamente aqueles monstros robustos.</color>",
  ui_story_5076_50760701_21_dialog_content = "<color=#e8d9bb>Uma cidade que levaria dias para ser conquistada por forças comuns é facilmente dominada por eles.</color>",
  ui_story_5076_50760701_22_dialog_content = "<color=#e8d9bb>A cavalaria liderada pela Santa Silenciosa Freya passa sem esforço sobre os Eclipsitas, sua lança varrendo com uma dominação incomparável. Os Eclipsitas caídos são rapidamente envolvidos em línguas de fogo, contorcendo-se em agonia.</color>",
  ui_story_5076_50760701_23_dialog_content = "Que crueldade... Não há necessidade de brincar com eles assim, Friegson.",
  ui_story_5076_50760701_24_dialog_content = "Eclipsitas não merecem nenhuma simpatia.",
  ui_story_5076_50760701_25_dialog_content = "Onde está o Vice Capitão?",
  ui_story_5076_50760701_26_dialog_content = "Os Eclipsitas estão recuando para a cidade. Parece que eles podem sentir algum tipo de medo afinal... Mas tenho certeza de que ele já está esperando por eles lá dentro.",
  ui_story_5076_50760701_27_dialog_content = "Se eles não escaparem, pelo menos terão uma morte gentil... Isso é mais do que eles merecem.",
  ui_story_5076_50760701_28_dialog_content = "<color=#e8d9bb>... Enquanto os Eclipsitas, movidos pelo medo instintivo, fogem em direção ao portão traseiro, há uma figura sozinha bloqueando seu caminho.</color>",
  ui_story_5076_50760701_29_dialog_content = "<color=#e8d9bb>Mágica de água impiedosa, aliada àquela espada colossal frígida, esmaga sem esforço aqueles que ousaram avançar, deixando os Eclipsitas sem meios de escapar.</color>",
  ui_story_5076_50760701_30_dialog_content = "Morte a todos os inimigos... Morte a todos os inimigos... Morte a todos os inimigos...",
  ui_story_5076_50760701_31_dialog_content = "Eclipsitas! <size=45>Morram!!!</size>",
  ui_story_5076_50760702_1_dialog_content = "Eclipsitas—Morra—",
  ui_story_5076_50760702_2_dialog_content = "Todos vocês devem morrer!",
  ui_story_5076_50760702_3_dialog_content = "Acalme-se, Adras... Você está assustando os soldados.",
  ui_story_5076_50760702_4_dialog_content = "M-Marcela? Fique atrás, é perigoso aqui!",
  ui_story_5076_50760702_5_dialog_content = "É isso... o Caçador Silencioso?",
  ui_story_5076_50760702_6_dialog_content = "Tão assustador. Difícil de imaginar que ele é um herói lendário. Olhe para ele! Ele está completamente...",
  ui_story_5076_50760702_7_dialog_content = "Controle-se; ele pode nos ouvir.",
  ui_story_5076_50760702_8_dialog_content = "A batalha acabou? Todos estão seguros agora?",
  ui_story_5076_50760702_9_dialog_content = "Você fez bem, Adras.",
  ui_story_5076_50760702_10_dialog_content = "Mas... Não havia um único sobrevivente nesta cidade... Esses malditos Eclipsitas.",
  ui_story_5076_50760702_11_dialog_content = "Isso não é sua culpa. O resto da equipe está chegando, agora vamos.",
  ui_story_5076_50760702_12_dialog_content = "...",
  ui_story_5076_50760702_13_dialog_content = "Outra celebração da fogueira para os Caçadores Silenciosos!",
  ui_story_5076_50760702_14_dialog_content = "É mesmo? Não me lembro de fazer parte da equipe, nem do Anthony, aliás.",
  ui_story_5076_50760702_15_dialog_content = "Você deveria voltar, Anthony. Continue andando conosco, e as pessoas começarão a temer você também.",
  ui_story_5076_50760702_16_dialog_content = "Desculpe, General Aquiles, você é um herói mas...",
  ui_story_5076_50760702_17_dialog_content = "Eu não sou mais um general, Anthony. Você não precisa se referir a mim como um.",
  ui_story_5076_50760702_18_dialog_content = "Mas...",
  ui_story_5076_50760702_19_dialog_content = "Não há generais ou comandantes aqui. Apenas os Caçadores Silenciosos.",
  ui_story_5076_50760702_20_dialog_content = "Não rodeie, Anthony. Se você quer comer conosco, apenas diga.",
  ui_story_5076_50760702_21_dialog_content = "Entendo...",
  ui_story_5076_50760702_22_dialog_content = "Ei Ludweiss, não coma toda a carne cozida sozinho!",
  ui_story_5076_50760702_23_dialog_content = "Qual é o problema? Basta pedir ao Friegson para fazer mais para você.",
  ui_story_5076_50760702_24_dialog_content = "Ela simplesmente queimaria tudo até virar cinzas, seu idiota. Além disso, eu não quero nada do que ela cozinha.",
  ui_story_5076_50760702_25_dialog_content = "Você tem algo a dizer para mim?",
  ui_story_5076_50760702_26_dialog_content = "O que ela quer dizer é que não quer comer nada cozido pelo seu fogo matador de Eclipsitas.",
  ui_story_5076_50760702_27_dialog_content = "Isso mesmo!",
  ui_story_5076_50760702_28_dialog_content = "Vou para outro lugar para comer.",
  ui_story_5076_50760702_29_dialog_content = "Não, espera! Eu estava apenas brincando... Ah, isso é tudo culpa sua, Cynthia.",
  ui_story_5076_50760702_30_dialog_content = "Eu estava apenas ajudando você a expressar sua opinião.",
  ui_story_5076_50760702_31_dialog_content = "Não devemos brigar enquanto estamos comendo - Aqui, coma um pouco mais.",
  ui_story_5076_50760702_32_dialog_content = "Uau, estou tão emocionado! Você é a razão inteira pela qual eu escolhi me juntar aos Caçadores Silenciosos.",
  ui_story_5076_50760702_33_dialog_content = "Eu pensei que você disse que era para proteger o reino e seu povo...",
  ui_story_5076_50760702_34_dialog_content = "\"A Santa Silenciosa\", hein... Não consigo pensar em um nome menos adequado para alguém como você.",
  ui_story_5076_50760702_35_dialog_content = "Ah, estou cheio! Provavelmente deveria começar a tarefa de hoje agora...",
  ui_story_5076_50760702_36_dialog_content = "O quê, você ainda está escrevendo aquele seu diário?",
  ui_story_5076_50760702_37_dialog_content = "No dia em que deixei minha casa, decidi registrar tudo sobre minhas viagens. Não vou desistir de algo assim tão facilmente.",
  ui_story_5076_50760702_38_dialog_content = "Mas desde que Adras me resgatou dos Eclipsitas, eu não viajei para fora do reino.",
  ui_story_5076_50760702_39_dialog_content = "Ainda havia muitos lugares que eu queria ver, mas encontrei Eclipsitas no momento em que comecei a viajar novamente. Foi quando você me salvou, Freya—",
  ui_story_5076_50760702_40_dialog_content = "E depois de ficar preso aqui por tanto tempo, minhas notas agora são sobre você e seus companheiros de esquadrão.",
  ui_story_5076_50760702_41_dialog_content = "Você se certificou de escrever sobre o quão heróico eu fui hoje?",
  ui_story_5076_50760702_42_dialog_content = "Eu estava prestes a fazer isso, então você poderia me dar um pouco de espaço? Você vai derramar minha tinta por todo lugar—",
  ui_story_5076_50760702_43_dialog_content = "Estou surpreso que você ainda possa estar tão animado depois de ver o massacre lá fora hoje.",
  ui_story_5076_50760702_44_dialog_content = "Bem, considerando que você foi o responsável pela maior parte do estrago...",
  ui_story_5076_50760702_45_dialog_content = "Chega, Freya. Eu também sou culpado pela batalha de hoje.",
  ui_story_5076_50760702_46_dialog_content = "Ela realmente levanta um bom ponto, Friegson.",
  ui_story_5076_50760702_47_dialog_content = "Você não deveria se tensionar tanto na batalha. Até a corda de arco mais forte vai estalar sob pressão suficiente.",
  ui_story_5076_50760702_48_dialog_content = "Friegson está ao meu lado há muito tempo... Antes de eu ser estacionado no norte, nós dois servíamos como guardas do palácio.",
  ui_story_5076_50760702_49_dialog_content = "Comparada ao resto de vocês, que estão acostumados a ver batalhas assim, ela ainda tem alguns ajustes a fazer.",
  ui_story_5076_50760702_50_dialog_content = "Como um nobre desde o nascimento, tenho certeza de que você sempre viu o campo de batalha como um lugar de honra e glória, Freya. Mas você precisa entender que para tirar uma vida, você deve estar pronto para entregar a sua.",
  ui_story_5076_50760702_51_dialog_content = "O mesmo vale para você, Friegson. Agora todos nós fazemos parte dos Caçadores Silenciosos, então trate-os como você tratava seus camaradas no passado.",
  ui_story_5076_50760702_52_dialog_content = "Perdoe-me, Capitão...",
  ui_story_5076_50760702_53_dialog_content = "Corrija-me se eu estiver errado, capitão, mas você não fazia parte do Conselho Ancião antes? Isso faria de você um nobre ainda maior do que qualquer um de nós.",
  ui_story_5076_50760702_54_dialog_content = "O General Aquiles cresceu com o Rei naquela época.",
  ui_story_5076_50760702_55_dialog_content = "Isso explicaria como alguém tão jovem se tornou capitão dos guardas do palácio...",
  ui_story_5076_50760702_56_dialog_content = "Mas no final, você escolheu se tornar um \"supersoldado\", assim como nós.",
  ui_story_5076_50760702_57_dialog_content = "Prefiro enfrentar o inimigo na batalha do que participar de seus jogos políticos.",
  ui_story_5076_50760702_58_dialog_content = "Mas, mesmo que não seja sua intenção, o Rei está atualmente focado em suprimir o Conselho dos Anciões. Duvido que ele confie em você como costumava confiar.",
  ui_story_5076_50760702_59_dialog_content = "Caso contrário, ele não deixaria você se tornar...",
  ui_story_5076_50760702_60_dialog_content = "Chega disso! Você também era um guarda do palácio, certo Cynthia? Quase nunca ouço você falar sobre si mesmo, e o Capitão Aquiles também não nos conta nada.",
  ui_story_5076_50760702_61_dialog_content = "Ouvi dizer que você se aproximou do capitão e se voluntariou para o projeto, enquanto ele escolheu o resto de nós.",
  ui_story_5076_50760702_62_dialog_content = "Eu... Eu cresci na floresta, então não há muito o que dizer.",
  ui_story_5076_50760702_63_dialog_content = "Se meu arco for necessário na linha de frente, então é para lá que eu vou.",
  ui_story_5076_50760702_64_dialog_content = "Se eles precisarem de mim para o projeto, então vou deixá-los me aprimorar da maneira que acharem melhor.",
  ui_story_5076_50760702_65_dialog_content = "\"Aumentar\"?",
  ui_story_5076_50760702_66_dialog_content = "Ah! É-Eh nada, Adras... Ei, você não vai comer?",
  ui_story_5076_50760702_67_dialog_content = "Eu estava prestes a...",
  ui_story_5076_50760702_68_dialog_content = "É tudo por causa disso, huh? Nem pessoas nem monstros, e fomos forçados a comer em um canto, todos sozinhos.",
  ui_story_5076_50760702_69_dialog_content = "Temos uma missão especial. Nosso dever é lutar contra Eclipsitas ainda mais poderosos.",
  ui_story_5076_50760702_70_dialog_content = "Dando esse primeiro passo para o inferno... É melhor se pudermos manter outras pessoas longe desse tipo de coisa.",
  ui_story_5076_50760702_71_dialog_content = "Mesmo que tenhamos que pagar o preço, é melhor do que deixá-los sacrificar suas próprias vidas.",
  ui_story_5076_50760702_72_dialog_content = "Mas Vice Capitão... Você desistiu do seu status de comandante para se juntar aos Silent Hunters, assim como o capitão desistiu do seu status de general...",
  ui_story_5076_50760702_73_dialog_content = "Depois de pagar esse preço e constantemente arriscar sua vida, apenas para as pessoas terem medo de você... Você não acha isso injusto?",
  ui_story_5076_50760702_74_dialog_content = "Os Caçadores Silenciosos são monstros criados para combater os poderosos Eclipsitas. Nosso propósito é garantir a destruição deles; nada mais importa para nós.",
  ui_story_5076_50760702_75_dialog_content = "Apenas permanecendo neutros e mostrando moderação podemos continuar nossa luta contra a escuridão.",
  ui_story_5076_50760702_76_dialog_content = "Você se sente injustiçado, Freya?",
  ui_story_5076_50760702_77_dialog_content = "Talvez só um pouco... Mas não importa!",
  ui_story_5076_50760702_78_dialog_content = "Eu sou o único que tomou a decisão de proteger os outros. Não me importo com o que os outros pensam, contanto que eu consiga manter minha decisão.",
  ui_story_5076_50760702_79_dialog_content = "Tenho certeza que isso se aplica a cada um de nós.",
  ui_story_5076_50760702_80_dialog_content = "Como você se sente sobre as mudanças em seu corpo, Vice Capitão? Os olhares te incomodam quando você está lutando?",
  ui_story_5076_50760702_81_dialog_content = "... Estou autorizado a fazer esse tipo de pergunta, Capitão?",
  ui_story_5076_50760702_82_dialog_content = "Você já fez.",
  ui_story_5076_50760702_83_dialog_content = "Como o Capitão Aquiles uma vez disse, lutar contra esses monstros nos corromperá com o tempo. Eu estava totalmente preparado para aceitar as consequências.",
  ui_story_5076_50760702_84_dialog_content = "Contanto que ninguém mais tenha que sofrer assim, estou em paz com essas consequências.",
  ui_story_5076_50760702_85_dialog_content = "Como... Como você faz isso?",
  ui_story_5076_50760702_86_dialog_content = "Você é como uma pessoa completamente diferente fora do campo de batalha! Por favor, me mostre como você faz isso!",
  ui_story_5076_50760702_87_dialog_content = "Eu também! Ensine-nos como suprimir nossas emoções como você!",
  ui_story_5076_50760702_88_dialog_content = "Acho que sim...",
  ui_story_5076_50760702_89_dialog_content = "Tudo começa... Com amor.",
  ui_story_5076_50760702_90_dialog_content = "Ha?",
  ui_story_5076_50760702_91_dialog_content = "De acordo com Ludweiss, meu amor e saudade da minha esposa estão selados nesta lâmina.",
  ui_story_5076_50760702_92_dialog_content = "Enquanto eu segurá-lo em minhas mãos, nossos corações sempre estarão conectados, não importa a distância.",
  ui_story_5076_50760702_93_dialog_content = "Para protegê-la e impedir que este mal alcance nossa feliz casa... Isso é tudo o que me importa.",
  ui_story_5076_50760702_94_dialog_content = "De repente eu sinto... muito frio.",
  ui_story_5076_50760702_95_dialog_content = "Sempre que o Vice Capitão fala sobre sua esposa, todos os meus músculos começam a doer...",
  ui_story_5076_50760702_96_dialog_content = "Ainda me lembro dela...",
  ui_story_5076_50760702_97_dialog_content = "Ela ficou para trás para ajudar a reconstruir a cidade deles.",
  ui_story_5076_50760702_98_dialog_content = "Não é à toa que o Vice Capitão se recusa a ver alguém quando não está em uma missão—",
  ui_story_5076_50760702_99_dialog_content = "... Você também é amigo da esposa dele, Ludweiss?",
  ui_story_5076_50760702_100_dialog_content = "S-Sim! Isso me lembra que prometi trazer novos materiais de ensino para ela na próxima vez que eu voltar.",
  ui_story_5076_50760702_101_dialog_content = "Então, por que você continua nos acompanhando?",
  ui_story_5076_50760702_102_dialog_content = "Er—Para fazer mais registros, é claro!",
  ui_story_5076_50760702_103_dialog_content = "Acho que não falta gente estranha no campo de batalha nos dias de hoje.",
  ui_story_5076_50760702_104_dialog_content = "Chega disso. Aqui, tome uma taça deste vinho. Adras fez ele mesmo - Era o nosso favorito nos tempos de exército!",
  ui_story_5076_50760702_105_dialog_content = "Saúde, a todos!",
  ui_story_5076_50760800_1_dialog_content = "Saudações, Adras! Onde você está indo?",
  ui_story_5076_50760800_2_dialog_content = "Minha esposa e eu estamos mostrando às crianças alguns locais para o novo orfanato.",
  ui_story_5076_50760800_3_dialog_content = "Sua esposa? Eu não sabia sobre a sua... De qualquer forma, parabéns pelo seu novo casamento!",
  ui_story_5076_50760800_4_dialog_content = "Hã? Marcela e eu estamos casados há muito tempo, mas mesmo assim, obrigado. Vamos, minha querida.",
  ui_story_5076_50760800_5_dialog_content = "Não... Eu não quero ir a lugar nenhum perto do templo...",
  ui_story_5076_50760800_6_dialog_content = "Não está lá também? Então vamos escolher outro lugar.",
  ui_story_5076_50760800_7_dialog_content = "Ohh... Sinto muito, Adras! Foi... um descuido meu. Você é tão imponente; Eu não vi a Senhora Marcela à primeira vista.",
  ui_story_5076_50760800_8_dialog_content = "... Por favor, tome cuidado no seu caminho.",
  ui_story_5076_50760800_9_dialog_content = "Obrigado.",
  ui_story_5076_50760800_10_dialog_content = "Você tem perdido peso novamente, Marcela? As pessoas mal conseguem te ver atrás de mim; elas podem começar a pensar que você é outra pessoa.",
  ui_story_5076_50760800_11_dialog_content = "Hmph... Você já pensou que você é o único que está ganhando peso?",
  ui_story_5076_50760800_12_dialog_content = "A reconstrução parece estar indo bem, Adras. Você tem trabalhado duro, não é?",
  ui_story_5076_50760800_13_dialog_content = "Ludweiss! Há quanto tempo, meu amigo!",
  ui_story_5076_50760800_14_dialog_content = "Estou feliz em ver que você tem se saído tão bem ultimamente.",
  ui_story_5076_50760800_15_dialog_content = "Está, uh... Marcela também está bem?",
  ui_story_5076_50760800_16_dialog_content = "Você está falando comigo como se ela não estivesse bem na sua frente! Hmm? Para onde você está olhando, Ludweiss? Não vê a Marcela parada atrás de mim?",
  ui_story_5076_50760800_17_dialog_content = "... Adras tem te ouvido como um bom marido, Marcela?",
  ui_story_5076_50760800_18_dialog_content = "Não provoque ele demais, Ludweiss. Não é fácil para ele se afastar das linhas de frente, e ele acabou de retornar.",
  ui_story_5076_50760800_19_dialog_content = "Isso me lembra... Você não estava indo a algum lugar com Freya e os outros? Desculpe, talvez seja porque estive muito ocupado, mas não consigo me lembrar.",
  ui_story_5076_50760800_20_dialog_content = "É perfeitamente compreensível! Afinal, você está supervisionando a reconstrução de uma cidade inteira. Eu só vim entregar uma carta do Achilles.",
  ui_story_5076_50760800_21_dialog_content = "Uma carta?",
  ui_story_5076_50760800_22_dialog_content = "Adras, Marcela, olá!",
  ui_story_5076_50760800_23_dialog_content = "Oi lá, Adras!",
  ui_story_5076_50760800_24_dialog_content = "Idiota, por que cumprimentar apenas Adras? Não te ensinei—",
  ui_story_5076_50760800_25_dialog_content = "Agora, agora, não pegue no pé do seu irmãozinho.",
  ui_story_5076_50760800_26_dialog_content = "Você não se importa, não é, Marcela?",
  ui_story_5076_50760800_27_dialog_content = "Hum.",
  ui_story_5076_50760800_28_dialog_content = "Desculpe, Adras, e... Mar-Marcela.",
  ui_story_5076_50760800_29_dialog_content = "Adras, de volta dos arredores hoje?",
  ui_story_5076_50760800_30_dialog_content = "Adras, estas uvas são do nosso próprio vinhedo. Pegue-as; elas têm um ótimo sabor e são excelentes para fazer vinho.",
  ui_story_5076_50760800_31_dialog_content = "Camaradas, abram caminho! Adras, confira este tecido; é perfeito para fazer roupas novas para Marcela.",
  ui_story_5076_50760800_32_dialog_content = "Você realmente não precisa fazer isso. Se você fizer, Marcela não vai me deixar ouvir o fim disso.",
  ui_story_5076_50760800_33_dialog_content = "Ah—Marcela?",
  ui_story_5076_50760800_34_dialog_content = "Onde você foi, meu amor?",
  ui_story_5076_50760800_35_dialog_content = "...Eu vi ela correndo de volta!",
  ui_story_5076_50760800_36_dialog_content = "Sim, ela deve ser tímida, haha!",
  ui_story_5076_50760800_37_dialog_content = "Ou talvez ela esteja brava, é tudo culpa sua.",
  ui_story_5076_50760800_38_dialog_content = "Vamos lá; deixe algum espaço privado para o nosso poderoso herói, tudo bem?",
  ui_story_5076_50760800_39_dialog_content = "Desculpe Ludweiss, as pessoas aqui podem ser um pouco demais às vezes. O que você estava dizendo sobre—",
  ui_story_5076_50760800_40_dialog_content = "Ludweiss? P-por que você está chorando...? Você está bem?",
  ui_story_5076_50760800_41_dialog_content = "Eu... Eu... Eu estou bem, é só que... Isso foi realmente emocionante agora.",
  ui_story_5076_50760800_42_dialog_content = "Todos tratam vocês dois tão bem... Estou tão feliz por vocês.",
  ui_story_5076_50760800_43_dialog_content = "Isso é porque todos eles são boas pessoas.",
  ui_story_5076_50760800_44_dialog_content = "Eu sei... Eles realmente são boas pessoas...",
  ui_story_5076_50760800_45_dialog_content = "Aqui está um lenço. Pegue.",
  ui_story_5076_50760800_46_dialog_content = "Sentindo-se melhor agora?",
  ui_story_5076_50760800_47_dialog_content = "Sim. Obrigado, Adras—",
  ui_story_5076_50760800_48_dialog_content = "Você mencionou algo sobre uma carta. O capitão tem novas ordens para mim?",
  ui_story_5076_50760800_49_dialog_content = "... O rei está se preparando para uma nova expedição. Ele quer destruir o mal em sua origem.",
  ui_story_5076_50760800_50_dialog_content = "Desta vez, ele está enviando você e os Caçadores Silenciosos para lidar com o abismo descoberto pela primeira vez no norte.",
  ui_story_5076_50760800_51_dialog_content = "Então, o mundo ainda não está em paz.",
  ui_story_5076_50760800_52_dialog_content = "Eu aceito.",
  ui_story_5076_50760800_53_dialog_content = "Algumas outras forças se juntarão aos Caçadores Silenciosos nesta campanha?",
  ui_story_5076_50760800_54_dialog_content = "Pelo que eu sei, duas legiões também foram atribuídas a isso.",
  ui_story_5076_50760800_55_dialog_content = "Quem vai liderá-los?",
  ui_story_5076_50760800_56_dialog_content = "É o Sumo Sacerdote Lucius... Ele foi reintegrado pelo rei. Não só isso, ele assumirá o comando total de toda a expedição.",
  ui_story_5076_50760800_57_dialog_content = "O quê? Aquele escória traidora?!",
  ui_story_5076_50760800_58_dialog_content = "Mas ele mobilizou suas próprias forças privadas durante a última guerra! Inúmeras pessoas morreram por causa dele!",
  ui_story_5076_50760800_59_dialog_content = "Todas aquelas cidades onde ninguém sobreviveu foram resultados dos crimes dele! Você quer me dizer que esse homem está de repente no comando de nossa operação?!",
  ui_story_5076_50760800_60_dialog_content = "É culpa dele que tantas pessoas inocentes morreram! Marcela quase perdeu a vida por causa dele, também!",
  ui_story_5076_50760800_61_dialog_content = "Não! Ele não merece piedade! Eu não vou perdoá-lo por—",
  ui_story_5076_50760800_62_dialog_content = "Por favor, apenas se acalme, Adras. Essas são as ordens do rei.",
  ui_story_5076_50760800_63_dialog_content = "Mesmo assim, eu me recuso a trabalhar para alguém como Lucius!",
  ui_story_5076_50760800_64_dialog_content = "Amaldiçoe-o—",
  ui_story_5076_50760800_65_dialog_content = "Não desconte sua frustração em Ludweiss, Adras.",
  ui_story_5076_50760800_66_dialog_content = "Marcela? Você voltou...",
  ui_story_5076_50760800_67_dialog_content = "O rei pode estar cercado por mentirosos e bajuladores agora... Mas eles não são aqueles que você tem protegido, são?",
  ui_story_5076_50760800_68_dialog_content = "Ou você deseja ver nossa cidade destruída pela segunda vez?",
  ui_story_5076_50760800_69_dialog_content = "Para o rei engolir seu orgulho e deixar Lucius levar o crédito por esta campanha só irá promover ainda mais seus objetivos malignos.",
  ui_story_5076_50760800_70_dialog_content = "Mas por mais que me doa, não tenho como recusar a ele.",
  ui_story_5076_50760800_71_dialog_content = "O capitão precisa de mim, meus aliados precisam de mim... E as pessoas inocentes do nosso reino precisam de mim...",
  ui_story_5076_50760800_72_dialog_content = "... Aceito minhas ordens, Ludweiss.",
  ui_story_5076_50760800_73_dialog_content = "Assim que as crianças e eu decidirmos um novo local para o orfanato, reunirei meus equipamentos e partirei imediatamente.",
  ui_story_5076_50760800_74_dialog_content = "Entendido... Obrigado, Adras.",
  ui_story_5076_50760800_75_dialog_content = "Obrigado... Por continuar a lutar por este mundo.",
  ui_story_5076_50760800_76_dialog_content = "E você? Qual é o seu próximo curso de ação?",
  ui_story_5076_50760800_77_dialog_content = "Eu...? Bem, eu meio que quero ver a aurora por mim mesmo—",
  ui_story_5076_50760800_78_dialog_content = "A expedição será extremamente perigosa. É melhor se você não vier desta vez.",
  ui_story_5076_50760800_79_dialog_content = "Você deveria sair deste lugar, Ludweiss.",
  ui_story_5076_50760800_80_dialog_content = "O mundo é um lugar vasto e incrível. Tenho certeza de que você encontrará um lugar muito mais interessante para escrever em seu diário.",
  ui_story_5076_50760800_81_dialog_content = "... Desculpe, mas não posso ir embora ainda. Ainda tenho alguns assuntos para resolver aqui.",
  ui_story_5076_50760800_82_dialog_content = "Além disso, não me importaria de ficar e fazer companhia para Marcela. Certo, Marcela?",
  ui_story_5076_50760800_83_dialog_content = "Então vou deixá-la em suas mãos, Ludweiss.",
  ui_story_5076_50760800_84_dialog_content = "Apenas volte o mais rápido que puder. Nunca se sabe quando eu posso mudar de ideia, sabe!",
  ui_story_5076_50760800_85_dialog_content = "Então, farei a você a mesma promessa que fiz a ela—",
  ui_story_5076_50760800_86_dialog_content = "Que eu voltarei não importa o que aconteça.",
  ui_story_5076_50760800_87_dialog_content = "E se eu acontecer de encontrar a aurora durante minhas viagens—",
  ui_story_5076_50760800_88_dialog_content = "Com certeza vou te contar tudo sobre a beleza dela, meu amigo.",
  ui_story_5076_50760800_89_dialog_content = "Parece um acordo... Mal posso esperar para ouvir sua história, ó grande herói.",
  ui_story_5076_50760900_1_dialog_content = "\"O tempo sempre parece escorregar quando menos percebemos... E antes que percebamos—\"",
  ui_story_5076_50760900_2_dialog_content = "Professor Ludweiss, venha aqui rápido!",
  ui_story_5076_50760900_3_dialog_content = "O que há com toda essa agitação? Mal tenho a chance de escrever no meu diário nos dias de hoje, sabe...",
  ui_story_5076_50760900_4_dialog_content = "Há quanto tempo, Ludweiss.",
  ui_story_5076_50760900_5_dialog_content = "Adras? Você...",
  ui_story_5076_50760900_6_dialog_content = "Heh... Bem-vindo de volta, Adras.",
  ui_story_5076_50760900_7_dialog_content = "Apressem-se e fechem a porta, crianças! Se alguém ver que nosso poderoso herói está de volta, a cidade inteira vai pisotear este lugar até virar pó!",
  ui_story_5076_50760900_8_dialog_content = "As crianças me contam que você tem administrado o orfanato há algum tempo. Não posso agradecer o suficiente pela sua ajuda, meu amigo.",
  ui_story_5076_50760900_9_dialog_content = "Nunca pensei que criar um monte de crianças poderia ser tão difícil. Como diabos a Marcela conseguiu—Tosse, tosse, tosse!",
  ui_story_5076_50760900_10_dialog_content = "Isso me lembra, cadê ela? As crianças disseram que eu poderia encontrá-la aqui com você.",
  ui_story_5076_50760900_11_dialog_content = "Hã? Comigo?",
  ui_story_5076_50760900_12_dialog_content = "Ah! Ela me viu escrevendo no meu diário, então ela acabou de sair.",
  ui_story_5076_50760900_13_dialog_content = "Sinto muito, eu sei que você deve estar morrendo de vontade de vê-la...",
  ui_story_5076_50760900_14_dialog_content = "Está tudo bem, Ludweiss. Enquanto eu segurar essa espada em minhas mãos, ela nunca estará longe do meu lado.",
  ui_story_5076_50760900_15_dialog_content = "A expedição ao norte foi longa, mas não o suficiente para separar nossos corações.",
  ui_story_5076_50760900_16_dialog_content = "Ainda assim, é um pouco inquietante não ouvir a voz dela depois de uma longa jornada... Você sabe quando ela vai voltar?",
  ui_story_5076_50760900_17_dialog_content = "Não tenho certeza - Isso me lembra, ouvimos falar do seu retorno vitorioso há alguns dias! Ouvi dizer que o rei elogiou todos vocês pelo seu sucesso.",
  ui_story_5076_50760900_18_dialog_content = "Isso mesmo. Todos nós também recebemos novos títulos.",
  ui_story_5076_50760900_19_dialog_content = "Eu me lembro de ler sobre isso na carta de Freya também!",
  ui_story_5076_50760900_20_dialog_content = "Seu título agora é \"Regal\", certo? E Freya é \"Requiem\", Friegson é \"Frostfire\", e Cynthia é \"Mythos\".",
  ui_story_5076_50760900_21_dialog_content = "Ela esqueceu de me dizer o título de Aquiles, no entanto.",
  ui_story_5076_50760900_22_dialog_content = "\"Claymore.\" Esse é o novo título do Capitão Achilles.",
  ui_story_5076_50760900_23_dialog_content = "Parece imponente... Freya disse que eles também deram a ela uma coroa de louros. Onde está a sua?",
  ui_story_5076_50760900_24_dialog_content = "Eu recusei.",
  ui_story_5076_50760900_25_dialog_content = "Huh? Por quê?",
  ui_story_5076_50760900_26_dialog_content = "A coroa de louros que uso na batalha foi me dada há muitos anos, quando encerrei a guerra contra os rebeldes. Naquela época, fui recompensado com amor e honra.",
  ui_story_5076_50760900_27_dialog_content = "É por isso... Eu não preciso de outro.",
  ui_story_5076_50760900_28_dialog_content = "Ah, que pena. Eu adoraria ver todos sendo recompensados por seus esforços.",
  ui_story_5076_50760900_29_dialog_content = "Mesmo tendo recusado outra coroa, ainda pedi ao rei uma recompensa em forma de terras e dinheiro.",
  ui_story_5076_50760900_30_dialog_content = "Que prático da sua parte!",
  ui_story_5076_50760900_31_dialog_content = "É para os meus conterrâneos—Eles perderam tanto por causa da guerra. Eu sei que nunca será suficiente para substituir o que foi perdido, mas...",
  ui_story_5076_50760900_32_dialog_content = "Só espero que isso torne a vida deles um pouco mais fácil.",
  ui_story_5076_50760900_33_dialog_content = "Adras...",
  ui_story_5076_50760900_34_dialog_content = "Eu vi a aurora enquanto estava no norte, Ludweiss.",
  ui_story_5076_50760900_35_dialog_content = "Para ser honesto, vi a aurora muitas vezes durante meu tempo no norte, mas nunca a vi como algo especial. Não sei por quê, mas por algum motivo, senti algo diferente durante esta última expedição.",
  ui_story_5076_50760900_36_dialog_content = "Quando vi a aurora rasgar a escuridão e iluminar o céu, tudo o que eu podia pensar era em desejar que Marcela estivesse lá para vê-la.",
  ui_story_5076_50760900_37_dialog_content = "Se não houvesse tanto perigo oculto no mundo, talvez todos pudessem ver algo tão bonito quanto isso.",
  ui_story_5076_50760900_38_dialog_content = "Por esse motivo, não quero te contar mais sobre isso... Quero que você veja por si mesmo algum dia, Ludweiss.",
  ui_story_5076_50760900_39_dialog_content = "Parece que você mudou, Adras... Mas... Deixa pra lá. Já que você está tão animado, isso deve significar que a campanha correu muito bem, certo?",
  ui_story_5076_50760900_40_dialog_content = "Isso mesmo. Conseguimos destruir o abismo, mas a um custo. Felizmente, não parece que perdemos nenhum soldado normal.",
  ui_story_5076_50760900_41_dialog_content = "Até vimos uma espetacular chuva de meteoros antes de partirmos.",
  ui_story_5076_50760900_42_dialog_content = "Freya ficou sem palavras. Cynthia e os outros pareciam também estar curtindo.",
  ui_story_5076_50760900_43_dialog_content = "Logo depois, o capitão fez esses Brasões de Estrela para nós.",
  ui_story_5076_50760900_44_dialog_content = "Esses são tão bem feitos! Eu não fazia ideia de que Aquiles tinha jeito para esse tipo de coisa.",
  ui_story_5076_50760900_45_dialog_content = "Não importa para onde vamos, sempre seremos os Caçadores Silenciosos que contemplaram as estrelas naquele dia.",
  ui_story_5076_50760900_46_dialog_content = "Uma memória como esta é muito mais preciosa do que qualquer coroa de louros.",
  ui_story_5076_50760900_47_dialog_content = "Parece quase que você está dizendo adeus...",
  ui_story_5076_50760900_48_dialog_content = "É porque eu estou. Decidi me aposentar do serviço e passar o resto dos meus dias aqui, em paz e com Marcela ao meu lado.",
  ui_story_5076_50760900_49_dialog_content = "Freya não mencionou nada sobre isso em sua carta. O que acontecerá com os Silent Hunters?",
  ui_story_5076_50760900_50_dialog_content = "Nós... Ainda não nos desfizemos. Mas como subordinados diretos da coroa, eventualmente seremos submetidos ao controle de Lucius.",
  ui_story_5076_50760900_51_dialog_content = "Recuso-me a obedecer a ele. O mesmo vale para o resto dos Silent Hunters.",
  ui_story_5076_50760900_52_dialog_content = "Além disso, com a ameaça dos Eclipsitas eliminada, o reino não precisa mais de nós. Talvez essa tenha sido a razão pela qual nenhum deles tentou me impedir de sair.",
  ui_story_5076_50760900_53_dialog_content = "Não poderia concordar mais. Você deve estar cansado depois de tantos anos de luta, Adras; se alguém merece descansar, é você.",
  ui_story_5076_50760900_54_dialog_content = "Heheh, ainda não posso relaxar. Ainda preciso encontrar Marcela e surpreendê-la.",
  ui_story_5076_50760900_55_dialog_content = "Está ficando tarde. Tenho certeza de que ela voltará em breve, então não saia correndo por conta própria.",
  ui_story_5076_50760900_56_dialog_content = "Ele estava falando sério? Ele não viu a Marcela aqui, então onde mais ela poderia estar? Hmm...",
  ui_story_5076_50760900_57_dialog_content = "Será que o coração dele finalmente está começando a se curar? Isso é uma coisa boa... Certo?",
  ui_story_5076_50760900_58_dialog_content = "<color=#e8d9bb>O herói retorna após o triunfo, e a cidade o celebra com uma grande cerimônia.</color>",
  ui_story_5076_50760900_59_dialog_content = "<color=#e8d9bb>O <color=#FFB400>Templo</color>, o lugar de amor para o herói, é especialmente renovado e solenemente apresentado a ele.</color>",
  ui_story_5076_50760900_60_dialog_content = "<color=#e8d9bb>Ninguém antecipou que em breve testemunharia um tempo de grande turbulência.</color>",
  ui_story_5076_50760900_61_dialog_content = "Como isso aconteceu? O Templo que colocamos tanto esforço para renovar...",
  ui_story_5076_50760900_62_dialog_content = "O que no mundo aconteceu aqui?",
  ui_story_5076_50760900_63_dialog_content = "Adras? Você...",
  ui_story_5076_50760900_64_dialog_content = "Por que o templo está em ruínas?",
  ui_story_5076_50760900_65_dialog_content = "Talvez... sejam os Eclipsitas?",
  ui_story_5076_50760900_66_dialog_content = "Malditos Eclipsitas—Como ousam pisar neste lugar, especialmente quando significa tanto para Marcela e eu!!!",
  ui_story_5076_50760900_67_dialog_content = "Por favor, não fique bravo. Pelo menos ninguém está ferido agora. Vá com calma.",
  ui_story_5076_50760900_68_dialog_content = "... Estou aliviado em saber que ninguém se machucou. Deixe os reparos do templo comigo.",
  ui_story_5076_50760900_69_dialog_content = "Nós também vamos ajudar.",
  ui_story_5076_50760900_70_dialog_content = "Muito bem, mas fique alerta. Ainda podem haver Eclipsitas espreitando na área.",
  ui_story_5076_50760900_71_dialog_content = "Você também precisa ter cuidado!",
  ui_story_5076_50760900_72_dialog_content = "Vou trazer minha espada e vigiar este lugar quando a noite cair. Não podemos permitir que outra tragédia aconteça neste lugar, e não vou deixar os Eclipsitas fazerem o que quiserem novamente...",
  ui_story_5076_50760900_73_dialog_content = "<color=#e8d9bb>Graças ao esforço conjunto do herói e seus ajudantes trabalhadores, o Templo foi rapidamente reparado. No entanto—</color>",
  ui_story_5076_50760900_74_dialog_content = "O que é isso?!",
  ui_story_5076_50760900_75_dialog_content = "Eu nunca saí da cidade nem uma vez... Que tipo de Eclipsita é capaz de evitar minha detecção assim?",
  ui_story_5076_50760900_76_dialog_content = "Continua infiltrando a cidade bem debaixo do meu nariz... Os moradores da cidade estão em perigo...",
  ui_story_5076_50760900_77_dialog_content = "Não se preocupe muito com isso. Talvez o Eclipsite seja apenas muito fraco para chamar sua atenção. Aqui, vou tentar sentir isso.",
  ui_story_5076_50760900_78_dialog_content = "Huh? Tem algo estranho nesses destroços...",
  ui_story_5076_50760900_79_dialog_content = "Ei Adras? Você disse que a Marcela estava com tanto medo do templo que nem se atrevia a se aproximar, não foi?",
  ui_story_5076_50760900_80_dialog_content = "Sim, parece ser o caso. Sempre que vou ao templo, ela se recusa a ir junto.",
  ui_story_5076_50760900_81_dialog_content = "Então essa é a razão...",
  ui_story_5076_50760900_82_dialog_content = "Professor Ludweiss, olha!",
  ui_story_5076_50760900_83_dialog_content = "Isso meio que parece uma marca deixada por uma espada...",
  ui_story_5076_50760900_84_dialog_content = "Shh—!!!",
  ui_story_5076_50760900_85_dialog_content = "O que foi?",
  ui_story_5076_50760900_86_dialog_content = "N-Não é nada! Este garoto só quer ajudar a reconstruir o templo, mas ele ainda é muito jovem.",
  ui_story_5076_50760900_87_dialog_content = "Obrigado pela oferta, pequenino, mas você precisa voltar. Este lugar não é seguro.",
  ui_story_5076_50760900_88_dialog_content = "Vá em frente, apresse-se para casa!",
  ui_story_5076_50760900_89_dialog_content = "Então, você conseguiu sentir alguma coisa, Ludweiss?",
  ui_story_5076_50760900_90_dialog_content = "Eu fiz... Mas é algo muito pequeno, como um Eclipsita pequeno e travesso. Não acho que represente uma grande ameaça.",
  ui_story_5076_50760900_91_dialog_content = "Mesmo assim, não podemos nos dar ao luxo de correr riscos. Parece que vou precisar da sua ajuda para defender o templo, Ludweiss.",
  ui_story_5076_50760900_92_dialog_content = "Eu? Então... Vou começar pegando o turno de hoje à noite. Não se preocupe, a milícia estará de prontidão se algo acontecer. Por enquanto... Apenas vá para casa e descanse antes que Marcela comece a se preocupar...",
  ui_story_5076_50760900_93_dialog_content = "Ugh, que noite... O chão do templo não é o lugar mais macio para dormir.",
  ui_story_5076_50760900_94_dialog_content = "Professor Ludweiss, o Irmão Adras disse que passaria por aqui esta noite para vigiar. Ah, a propósito, ele parece bastante animado.",
  ui_story_5076_50760900_95_dialog_content = "Parece que ele descansou bastante, o que significa que o templo não deveria ter sido...",
  ui_story_5076_50760900_96_dialog_content = "Por que... Por que ele está tão estável de repente? Será que... Ele viu a Marcela novamente?",
  ui_story_5076_50760900_97_dialog_content = "Ludweiss, você deve estar cansado depois de ficar de vigia a noite toda. Você pode voltar agora.",
  ui_story_5076_50760900_98_dialog_content = "Se eu sair e Adras se aproximar do templo novamente...",
  ui_story_5076_50760900_99_dialog_content = "Não se preocupe, Ludweiss. Nós temos fé em Adras.",
  ui_story_5076_50760900_100_dialog_content = "Não podemos ter você aqui o tempo todo. Tudo bem; devemos muito a Adras, então todos nós vamos trabalhar juntos com você...",
  ui_story_5076_50760900_101_dialog_content = "... Eu tenho uma ideia. Se o templo acabar em ruínas novamente amanhã, preciso que todos entrem na brincadeira com isso—",
  ui_story_5076_50760900_102_dialog_content = "Como esperado, o templo foi danificado novamente.",
  ui_story_5076_50760900_103_dialog_content = "O que no mundo...",
  ui_story_5076_50760900_104_dialog_content = "... Você tem dormido bem em casa, Adras?",
  ui_story_5076_50760900_105_dialog_content = "Claro. Afinal, Marcela está comigo novamente... Mas por que você pergunta?",
  ui_story_5076_50760900_106_dialog_content = "Suspiro... Parece que estamos de volta à estaca zero novamente...",
  ui_story_5076_50760900_107_dialog_content = "Ainda assim, estou feliz em ver que sua mente está em paz novamente.",
  ui_story_5076_50760900_108_dialog_content = "Do que você está falando?",
  ui_story_5076_50760900_109_dialog_content = "Como um Celestita, eu apenas... Me sinto um pouco impotente. Afinal, esta é a primeira vez que desejei que uma <color=#FFB400>doença</color> permanecesse sem cura...",
  ui_story_5076_50760900_110_dialog_content = "Adras, pegamos aquele Eclipsite!",
  ui_story_5076_50760900_111_dialog_content = "Sério? Como você fez isso?",
  ui_story_5076_50760900_112_dialog_content = "Era um pequeno Eclipsite, ágil e rápido, causando problemas apenas nas primeiras horas. Mas não se preocupe, ele caiu em nossa armadilha e foi pego!",
  ui_story_5076_50760900_113_dialog_content = "Já eliminamos aquele Eclipsite. Você pode ficar tranquilo agora.",
  ui_story_5076_50760900_114_dialog_content = "Sim, irmão Adras, eu vi aquele pequeno Eclipsita ser esmagado com meus próprios olhos.",
  ui_story_5076_50760900_115_dialog_content = "Aham—",
  ui_story_5076_50760900_116_dialog_content = "Ah! A propósito, acabamos de passar pela sua casa e ouvimos que a Marcela pode precisar de você para alguma coisa. É melhor você voltar correndo.",
  ui_story_5076_50760900_117_dialog_content = "Entendido. Voltarei amanhã para ajudar com os reparos.",
  ui_story_5076_50760900_118_dialog_content = "Não, apenas deixe conosco! Você já fez tanto por nós e não queremos te incomodar mais. Volte e passe mais tempo com a Marcela.",
  ui_story_5076_50760900_119_dialog_content = "Seria muito embaraçoso se não conseguíssemos acertar uma coisa tão pequena.",
  ui_story_5076_50760900_120_dialog_content = "Apenas faça o que eles dizem, Adras. Depois de alguns dias—",
  ui_story_5076_50760900_121_dialog_content = "Professor Ludweiss! Ahem!",
  ui_story_5076_50760900_122_dialog_content = "—Apenas continue mantendo sua distância! Tudo está bem agora, então apenas fique de olho nas coisas de longe, ok?",
  ui_story_5076_50760900_123_dialog_content = "Todos vocês estão agindo de maneira tão estranha.",
  ui_story_5076_50760900_124_dialog_content = "Mas se Marcela precisa de mim agora... Eu deveria apenas ir para casa...",
  ui_story_5076_50760900_125_dialog_content = "Deixo o resto com você, Ludweiss.",
  ui_story_5076_50760900_126_dialog_content = "Hã? Er... Claro! Apenas... deixe tudo comigo.",
  ui_story_5076_50761000_1_dialog_content = "Eles realmente conseguiram reconstruir esta cidade.",
  ui_story_5076_50761000_2_dialog_content = "Viu? Eu te disse que Ludweiss não estava exagerando em sua carta!",
  ui_story_5076_50761000_3_dialog_content = "A última vez que nos reunimos aqui, esta cidade mal se diferenciava de uma pilha de escombros.",
  ui_story_5076_50761000_4_dialog_content = "O que poderia ter possivelmente motivado essas pessoas a fazer tal milagre acontecer?",
  ui_story_5076_50761000_5_dialog_content = "Tenho certeza de que era a fé deles em seu herói.",
  ui_story_5076_50761000_6_dialog_content = "Eles estão olhando para nós de novo... Esconda meu rosto, Freya.",
  ui_story_5076_50761000_7_dialog_content = "Ei! Por aqui!",
  ui_story_5076_50761000_8_dialog_content = "Senhorita Ludweiss, quem são eles? Você poderia apresentá-los, por favor?",
  ui_story_5076_50761000_9_dialog_content = "Estes são os amigos de Adras, os lendários Guerreiros Estelares do reino! Eles vieram para visitá-lo.",
  ui_story_5076_50761000_10_dialog_content = "Uau, estamos tão honrados em tê-los aqui! Adras e Marcela com certeza ficarão muito felizes.",
  ui_story_5076_50761000_11_dialog_content = "Marcela? Mas Capitã, você não disse que ela... Entendi. Todos vocês têm cuidado da Vice Capitã, certo?",
  ui_story_5076_50761000_12_dialog_content = "Obrigado.",
  ui_story_5076_50761000_13_dialog_content = "Hehe, estimados convidados, gostariam de experimentar nossas especialidades locais?",
  ui_story_5076_50761000_14_dialog_content = "Você poderia levar alguns para Adras também? Ele está... bem, ele e Marcela também precisam de cuidados.",
  ui_story_5076_50761000_15_dialog_content = "Pessoal...",
  ui_story_5076_50761000_16_dialog_content = "Hehe, por favor, diga oi para ele e para a \"Marcela\" por nós.",
  ui_story_5076_50761000_17_dialog_content = "É bom ver todos vocês novamente. Eu queria recebê-los pessoalmente, mas Marcela se ofereceu para fazer isso no meu lugar.",
  ui_story_5076_50761000_18_dialog_content = "Afinal, ela e Ludweiss já estão na cidade. Ambos trabalham no orfanato agora.",
  ui_story_5076_50761000_19_dialog_content = "Não se preocupe com isso. Marcela nos mostrou os campos agora mesmo. Eles são enormes! Você deve estar muito ocupado se preparando para a colheita, certo?",
  ui_story_5076_50761000_20_dialog_content = "Sim, mas também é muito pacífico... Eu não poderia pedir uma vida melhor.",
  ui_story_5076_50761000_21_dialog_content = "É bom ouvir isso... Adras.",
  ui_story_5076_50761000_22_dialog_content = "Como todos vocês têm estado?",
  ui_story_5076_50761000_23_dialog_content = "Tudo bem, eu suponho. Voltei a servir como guarda do palácio, para poder continuar defendendo o reino.",
  ui_story_5076_50761000_24_dialog_content = "Desde que não somos mais necessários, tenho vagado pelo reino... Os olhares frios nunca param, mas tenho me saído bem.",
  ui_story_5076_50761000_25_dialog_content = "A floresta é muito mais pacífica, Friegson. Que tal se juntar a mim em vez disso?",
  ui_story_5076_50761000_26_dialog_content = "... Eu não quero que minhas chamas destruam seu paraíso.",
  ui_story_5076_50761000_27_dialog_content = "Você sempre pode ficar aqui, Friegson. As pessoas nesta cidade são gentis e não vão te rejeitar por causa de suas cicatrizes.",
  ui_story_5076_50761000_28_dialog_content = "Obrigado pela oferta, Vice Capitão. Eu posso ver que eles são boas pessoas, mas... É melhor se eu não ficar.",
  ui_story_5076_50761000_29_dialog_content = "Um reencontro como este é difícil de acontecer, então por que não ficar um pouco mais e contar ao Adras sobre suas vidas? Podemos até fazer uma fogueira, como antes.",
  ui_story_5076_50761000_30_dialog_content = "Marcela está certa. Devemos fazer uma fogueira esta noite, como nos velhos tempos. Eu adoraria sentar e conversar um pouco mais com todos também.",
  ui_story_5076_50761000_31_dialog_content = "... Eu não vejo por que não.",
  ui_story_5076_50761000_32_dialog_content = "Por mim, tudo bem! Faz muito tempo que não como a comida caseira do Vice Capitão! Aposto que por aqui também tem muitas adegas de vinho—",
  ui_story_5076_50761000_33_dialog_content = "Vamos lá Friegson, vamos pegar um barril da coisa boa!",
  ui_story_5076_50761000_34_dialog_content = "Isso seria aceitável, Vice Capitão?",
  ui_story_5076_50761000_35_dialog_content = "Claro. Marcela pode te mostrar onde fica.",
  ui_story_5076_50761000_36_dialog_content = "Mas...",
  ui_story_5076_50761000_37_dialog_content = "A adega de vinhos é fácil de encontrar. A entrada fica no galpão atrás da casa.",
  ui_story_5076_50761000_38_dialog_content = "Vamos pegar mais alguns barris e fazer desta uma verdadeira festa! Agora pare de enrolar e nos dê uma mão, Cynthia!",
  ui_story_5076_50761000_39_dialog_content = "Mas eu tenho que observar a etiqueta adequada enquanto...",
  ui_story_5076_50761000_40_dialog_content = "Ah, supere isso e nos ajude!",
  ui_story_5076_50761000_41_dialog_content = "Tem passado bem ultimamente, Capitão?",
  ui_story_5076_50761000_42_dialog_content = "A autoridade de Lucius vai além de seu status como Sumo Sacerdote. Ele é poderoso o suficiente para enfrentar o Conselho dos Anciões agora... E minha família deseja que eu fique ao lado deles.",
  ui_story_5076_50761000_43_dialog_content = "Mas os Silent Hunters não são assassinos. Agora que o reino está seguro dos Eclipsitas, não temos motivo para nos envolver nessas questões.",
  ui_story_5076_50761000_44_dialog_content = "Eu só quero passar tempo com todos, Adras. Assim mesmo.",
  ui_story_5076_50761000_45_dialog_content = "... Eu entendo. Espero que você encontre alguma paz aqui, mesmo que por um curto período de tempo.",
  ui_story_5076_50761000_46_dialog_content = "Vamos preparar o jantar de hoje à noite, Marcela.",
  ui_story_5076_50761000_47_dialog_content = "Você acha que ele está feliz, Ludweiss?",
  ui_story_5076_50761000_48_dialog_content = "Pelo que eu posso dizer, ele está definitivamente feliz agora...",
  ui_story_5076_50761000_49_dialog_content = "Estamos continuando com essa mentira, mas se—",
  ui_story_5076_50761000_50_dialog_content = "Marcela uma vez disse que Adras está disposto a lutar por seu povo pelo resto de sua vida.",
  ui_story_5076_50761000_51_dialog_content = "E as pessoas aqui estão fazendo tudo o que podem para proteger o último pedaço de paz e felicidade de seu herói.",
  ui_story_5076_50761000_52_dialog_content = "Não é apenas uma mentira, Capitão Aquiles. Pelo menos não do jeito que eu vejo.",
  ui_story_5076_50761000_53_dialog_content = "Aqueles que se escondem de sua dor eventualmente despertarão até mesmo do sonho mais cuidadosamente elaborado. Quando isso acontecer... Ele sofrerá ainda mais? Ou ele ficará feliz com aquele breve sentimento de felicidade?",
  ui_story_5076_50761000_54_dialog_content = "Ele está melhorando.",
  ui_story_5076_50761000_55_dialog_content = "Não sinto mais a corrupção se espalhando nele. Se alguma coisa, ele ficou ainda mais energético.",
  ui_story_5076_50761000_56_dialog_content = "Então, se ele acordar do sonho algum dia... Eu estarei lá para suportar qualquer ressentimento que ele possa ter.",
  ui_story_5076_50761000_57_dialog_content = "Eu sou o capitão deles, Ludweiss. Se esse dia chegar, serei eu a assumir a responsabilidade por tudo.",
  ui_story_5076_50761000_58_dialog_content = "Isso me lembra; ouvi dizer que o orfanato agora é totalmente capaz de se administrar. Você planeja retomar suas viagens em breve?",
  ui_story_5076_50761000_59_dialog_content = "Bem, eu sempre quis ver as estrelas cadentes lá no norte!",
  ui_story_5076_50761000_60_dialog_content = "Estrelas cadentes? Não é a aurora?",
  ui_story_5076_50761000_61_dialog_content = "Por outro lado, você é livre para fazer o que quiser. Pelo menos, você pode escapar de suas armadilhas... E ver o mundo em nosso lugar.",
  ui_story_5076_50761000_62_dialog_content = "Eu vou, e você será o primeiro a ler sobre tudo o que eu vejo lá fora.",
  ui_story_5076_50761000_63_dialog_content = "Vire, vire, vire! Vamos, você consegue!",
  ui_story_5076_50761000_64_dialog_content = "Glup, glup, glup—",
  ui_story_5076_50761000_65_dialog_content = "Eu... eu me rendo... Não consigo beber mais.",
  ui_story_5076_50761000_66_dialog_content = "Levante-se, Friegson! Como você pôde perder para Cynthia de novo?!",
  ui_story_5076_50761000_67_dialog_content = "Um capitão... Dois capitães...",
  ui_story_5076_50761000_68_dialog_content = "Ah, ela está realmente bêbada agora.",
  ui_story_5076_50761000_69_dialog_content = "Você é o próximo, Freya?",
  ui_story_5076_50761000_70_dialog_content = "A-Ahem, quero que saiba que sou uma nobre altamente culta! Como eu poderia possivelmente me envolver neste tipo de comportamento?",
  ui_story_5076_50761000_71_dialog_content = "... Covarde.",
  ui_story_5076_50761000_72_dialog_content = "Você se importaria em ajudar Friegson a ir para o quarto dela, Marcela?",
  ui_story_5076_50761000_73_dialog_content = "... Estou feliz por você, Vice Capitão.",
  ui_story_5076_50761000_74_dialog_content = "Você está indo muito melhor do que qualquer um de nós... Ninguém te trata como um monstro, ou te faz fazer o trabalho sujo deles.",
  ui_story_5076_50761000_75_dialog_content = "Você está bêbado, Friegson. Você deveria ir deitar.",
  ui_story_5076_50761000_76_dialog_content = "Por que todos no reino me olham dessa maneira? Não é como se eu quisesse acabar assim!",
  ui_story_5076_50761000_77_dialog_content = "Eu não fiz nada de errado! Eu só queria protegê-los...",
  ui_story_5076_50761000_78_dialog_content = "Leve-a de volta para a cama, Freya.",
  ui_story_5076_50761000_79_dialog_content = "Mas Capitão... Ela está chorando.",
  ui_story_5076_50761000_80_dialog_content = "Ela está exausta. Acho que ela precisa desabafar.",
  ui_story_5076_50761000_81_dialog_content = "Eu não fiz nada! Sou um caçador de monstros, não um monstro!",
  ui_story_5076_50761000_82_dialog_content = "Eu só queria ajudar aquele velho a encontrar o caminho! Por que ele me xingou assim que me viu?!",
  ui_story_5076_50761000_83_dialog_content = "Ele estava claramente com medo de mim, mas isso não o impediu! Por quê? É porque ele sabia que eu não iria machucá-lo? Quem está sendo irracional aqui—",
  ui_story_5076_50761000_84_dialog_content = "...",
  ui_story_5076_50761000_85_dialog_content = "Não chore, Friegson. Realmente não combina com você.",
  ui_story_5076_50761000_86_dialog_content = "Vice Capitão? Eu... Eu realmente estou feliz por você. Pelo menos você consegue ser um herói. Mas por que o reino nos vê como monstros...?",
  ui_story_5076_50761000_87_dialog_content = "Por que, Vice Capitão...? O que devemos fazer...?",
  ui_story_5076_50761000_88_dialog_content = "O amor no meu coração está quase acabando agora... O que eu deveria fazer...?",
  ui_story_5076_50761000_89_dialog_content = "As pessoas aqui ainda conseguem ver você como o herói que você sempre foi... Então por que todos os outros são tão estúpidos?",
  ui_story_5076_50761000_90_dialog_content = "Friegson...",
  ui_story_5076_50761000_91_dialog_content = "Não se preocupe demais com ela, Adras. Ela tem guardado esses sentimentos para si mesma por muito tempo e finalmente encontrou alguém para compartilhá-los.",
  ui_story_5076_50761000_92_dialog_content = "... Beba, Vice Capitão! Vamos... Ficar bêbados juntos...!",
  ui_story_5076_50761000_93_dialog_content = "Saúde, Friegson. Este copo é para você.",
  ui_story_5076_50761000_94_dialog_content = "Vamos lá, Cynthia! O Capitão Vice parece que precisa de um bom desafio!",
  ui_story_5076_50761000_95_dialog_content = "Você deveria saber que eu sou extremamente confiante em mim mesmo.",
  ui_story_5076_50761000_96_dialog_content = "Bem, eu não estou, então parece que estou destinado a perder.",
  ui_story_5076_50761000_97_dialog_content = "Glup, glup, glup—",
  ui_story_5076_50761000_98_dialog_content = "Continuem vindo! Vou mostrar a vocês a coragem da Legião Northwind!",
  ui_story_5076_50761000_99_dialog_content = "Marcela... Onde você está... Não consigo te alcançar.",
  ui_story_5076_50761000_100_dialog_content = "Uma canção? Mas não estamos no horário de trabalho... Ah, acho que uma música não faria mal.",
  ui_story_5076_50761000_101_dialog_content = "\"Pegue minha mão—\"",
  ui_story_5076_50761000_102_dialog_content = "O Vice Capitão deve estar realmente bêbado... Eu acho que nunca ouvi uma música tão única antes...",
  ui_story_5076_50761000_103_dialog_content = "Não se preocupe, o canto dele não é muito melhor quando ele está sóbrio.",
  ui_story_5076_50761000_104_dialog_content = "\"Leve-me para casa—\"",
  ui_story_5076_50761000_105_dialog_content = "Foi essa a canção da Legião Northwind? É tão... cheia de emoção.",
  ui_story_5076_50761000_106_dialog_content = "Valeu...",
  ui_story_5076_50761000_107_dialog_content = "Eu me pergunto se algum dia teremos um lar?",
  ui_story_5076_50761000_108_dialog_content = "É assim que se faz, Vice Capitão. Nossos problemas não podem nos incomodar se estivermos bêbados demais para nos lembrar deles, certo?",
  ui_story_5076_50761000_109_dialog_content = "É ótimo...",
  ui_story_5076_50761000_110_dialog_content = "Eu acho que nunca vi Adras tão feliz.",
  ui_story_5076_50761000_111_dialog_content = "Isso realmente está bem, Capitão?",
  ui_story_5076_50761000_112_dialog_content = "Parece que Friegson está quase no seu limite, e apesar do aparente otimismo de Freya, tenho certeza que ela também está...",
  ui_story_5076_50761000_113_dialog_content = "Este mundo não precisa mais de nós. Se for o caso, nossa existência é uma ameaça demais para a paz.",
  ui_story_5076_50761000_114_dialog_content = "Eu te disse antes, não disse? Não somos nada além de armas à disposição do reino. Mais cedo ou mais tarde, eles vão nos usar novamente.",
  ui_story_5076_50761000_115_dialog_content = "Mesmo agora, sinto como se minha consciência estivesse sendo consumida.",
  ui_story_5076_50761000_116_dialog_content = "Quanto tempo mais até um de nós cometer um erro?",
  ui_story_5076_50761000_117_dialog_content = "Chega, Cynthia. Não há nada mais valioso para nós do que a racionalidade, mas isso não nos torna sem coração.",
  ui_story_5076_50761000_118_dialog_content = "Mas se não formos tratados em breve, um desses dias, nós vamos—",
  ui_story_5076_50761000_119_dialog_content = "Essas não são as coisas que você deveria estar pensando! Não somos como monstros em um conto de fadas!",
  ui_story_5076_50761000_120_dialog_content = "Parem de brigar, vocês dois! É raro todos nós passarmos tempo juntos assim...",
  ui_story_5076_50761000_121_dialog_content = "Eu me recuso a machucar meus amigos de qualquer maneira.",
  ui_story_5076_50761000_122_dialog_content = "É fácil dizer isso quando ainda temos uma escolha... Mas o que acontece quando não temos?",
  ui_story_5076_50761000_123_dialog_content = "Tem certeza de que não vai se arrepender?",
  ui_story_5076_50761000_124_dialog_content = "Enquanto eu continuar sendo Aquiles, juro pelo meu nome que nunca levantarei minha lâmina contra meus camaradas.",
  ui_story_5076_50761000_125_dialog_content = "Eu só entrei para o exército para impedir que as chamas da guerra chegassem à floresta...",
  ui_story_5076_50761000_126_dialog_content = "No momento em que coloquei o pé fora de casa, percebi que este mundo é apenas uma floresta ainda maior.",
  ui_story_5076_50761000_127_dialog_content = "Eu gostaria de poder pedir desculpas a você com toda a minha alma...",
  ui_story_5076_50761000_128_dialog_content = "Mas infelizmente, não tenho certeza se este corpo ainda tem uma alma ou não.",
  ui_story_5076_50761000_129_dialog_content = "De qualquer forma, me desculpe.",
  ui_story_5076_50761101_1_dialog_content = "Regal, há uma nova ordem para você.",
  ui_story_5076_50761101_2_dialog_content = "Frostfire, seu companheiro Caçador Silencioso, enlouqueceu em outra cidade.",
  ui_story_5076_50761101_3_dialog_content = "O quê?!",
  ui_story_5076_50761101_4_dialog_content = "Use sua magia de água para impedi-la.",
  ui_story_5076_50761101_5_dialog_content = "Se necessário... sem piedade, leve-a para baixo.",
  ui_story_5076_50761101_6_dialog_content = "Friegson... Por que...",
  ui_story_5076_50761101_7_dialog_content = "Isso é-",
  ui_story_5076_50761101_8_dialog_content = "A cidade inteira... Foi queimada até o chão?",
  ui_story_5076_50761101_9_dialog_content = "Sentinelas, relatem a situação! Há sobreviventes na cidade?",
  ui_story_5076_50761101_10_dialog_content = "Relatório! Sem sobreviventes na cidade, e ela ainda está fora de controle!",
  ui_story_5076_50761101_11_dialog_content = "Rápido! Lance o novo \"monstro\" e deixe-os lutar, ou outros lugares podem estar em perigo!",
  ui_story_5076_50761101_12_dialog_content = "Friegson... Friegson...",
  ui_story_5076_50761101_13_dialog_content = "Vice Capitão...? Por favor... Me ajude...",
  ui_story_5076_50761101_14_dialog_content = "Não... Você é—Um Eclipsite!",
  ui_story_5076_50761101_15_dialog_content = "<size=45>Um Eclipsite!!!</size>",
  ui_story_5076_50761101_16_dialog_content = "<size=45>Morra!!!</size>",
  ui_story_5076_50761102_1_dialog_content = "Aaaaaaah—Morra, Eclipsita!!!",
  ui_story_5076_50761102_2_dialog_content = "Parem, vocês dois!",
  ui_story_5076_50761102_3_dialog_content = "Eu não posso—Eu tenho que queimar tudo—",
  ui_story_5076_50761102_4_dialog_content = "Saiam dessa, vocês dois! Ludweiss, use seus poderes para trazê-los à razão!",
  ui_story_5076_50761102_5_dialog_content = "Por favor, acorde—",
  ui_story_5076_50761102_6_dialog_content = "C... Capitão?",
  ui_story_5076_50761102_7_dialog_content = "Ludweiss?",
  ui_story_5076_50761102_8_dialog_content = "Vocês finalmente voltaram ao normal... Por que estavam brigando assim?!",
  ui_story_5076_50761102_9_dialog_content = "Capitão, eu...",
  ui_story_5076_50761102_10_dialog_content = "Algemas? Por que estão em mim...?",
  ui_story_5076_50761102_11_dialog_content = "Olhe em volta, Friegson. Essas correntes são para te proteger.",
  ui_story_5076_50761102_12_dialog_content = "Monstros... Por que ainda manter esses seres perigosos por perto...",
  ui_story_5076_50761102_13_dialog_content = "Você jurou proteger este lugar, mas o incendiou junto com os Eclipsitas que o estavam atacando.",
  ui_story_5076_50761102_14_dialog_content = "Como isso aconteceu?",
  ui_story_5076_50761102_15_dialog_content = "Alguém... Alguém transferiu os guardas para outro posto e permitiu que uma horda de Eclipsitas infiltrasse a cidade e matasse inúmeros inocentes...",
  ui_story_5076_50761102_16_dialog_content = "Não consigo acreditar que alguém poderia fazer algo tão horrível.",
  ui_story_5076_50761102_17_dialog_content = "Então você sabia que estava sendo incriminado desde o começo?",
  ui_story_5076_50761102_18_dialog_content = "Sim, mas... eu não conseguia mais me controlar.",
  ui_story_5076_50761102_19_dialog_content = "Alguém sacrificou todas aquelas vidas inocentes apenas para despedaçar meu coração em pedaços...",
  ui_story_5076_50761102_20_dialog_content = "No momento em que percebi isso, a escuridão nublou minha visão. Eu perdi... E antes que eu percebesse, perdi toda semelhança com quem eu costumava ser.",
  ui_story_5076_50761102_21_dialog_content = "Não sou um herói. Não mais.",
  ui_story_5076_50761102_22_dialog_content = "Friegson...",
  ui_story_5076_50761102_23_dialog_content = "Você tem que manter a cabeça erguida, Friegson. Não desista.",
  ui_story_5076_50761102_24_dialog_content = "Estaremos sempre ao seu lado.",
  ui_story_5076_50761102_25_dialog_content = "Mas o que eu deveria fazer agora, Capitão? Eu sou...",
  ui_story_5076_50761102_26_dialog_content = "Vou escoltá-lo até a capital real e contar ao rei a verdade sobre o que aconteceu aqui. Vamos solicitar um julgamento justo para você.",
  ui_story_5076_50761102_27_dialog_content = "O quê? Você não pode fazer isso, Capitão!",
  ui_story_5076_50761102_28_dialog_content = "Você mesmo ouviu: Friegson foi incriminada, e é provável que a pessoa responsável faça parte do tribunal real! Enviá-la para lá seria o mesmo que enviá-la para a morte!",
  ui_story_5076_50761102_29_dialog_content = "Isso mesmo, deve ter sido o Lucius! Ele sempre esteve contra nós, e agora está se livrando de nós um por um...",
  ui_story_5076_50761102_30_dialog_content = "Não importa mais, Vice Capitão. Não é como se eu tivesse um lar para voltar, de qualquer maneira...",
  ui_story_5076_50761102_31_dialog_content = "Não, isso não é justo com você! As mãos de Lucius já estão no pescoço do nosso amigo, capitão; até quando você vai deixar isso continuar?",
  ui_story_5076_50761102_32_dialog_content = "Temos que... parar aquele homem...",
  ui_story_5076_50761102_33_dialog_content = "Calma, Adras! Freya e Cynthia ainda estão sendo observados!",
  ui_story_5076_50761102_34_dialog_content = "Você também tem uma cidade inteira e seu povo para pensar... Agora não é hora para decisões imprudentes.",
  ui_story_5076_50761102_35_dialog_content = "Temos que trabalhar juntos e encontrar uma maneira de provar a inocência de Friegson, entendeu?",
  ui_story_5076_50761102_36_dialog_content = "Capitão... Por que você não diz nada? Você costumava proteger até o mais baixo de seus subordinados, mas agora você nem mesmo levanta um dedo para defender um de seus amigos mais próximos?",
  ui_story_5076_50761102_37_dialog_content = "Capitão... Por que...",
  ui_story_5076_50761102_38_dialog_content = "Adras, Friegson... Desculpe.",
  ui_story_5076_50761102_39_dialog_content = "Custa muito para restaurar a paz em nosso reino. Não posso deixar cair no caos novamente.",
  ui_story_5076_50761102_40_dialog_content = "Se eu escolher resistir, o Conselho dos Anciões e Lucius iniciarão outra guerra. Você não quer ver outra rebelião sangrenta acontecer, quer?",
  ui_story_5076_50761102_41_dialog_content = "Então por favor... Perdoe-me.",
  ui_story_5076_50761102_42_dialog_content = "Por mais doloroso que seja fazer concessões, tudo o que podemos fazer agora é suportar—",
  ui_story_5076_50761200_1_dialog_content = "<color=#e8d9bb>A perda de controle do herói rapidamente provoca medo em todo o reino, com reclamações inundando a capital de todos os cantos.</color>",
  ui_story_5076_50761200_2_dialog_content = "<color=#e8d9bb>Frostfire, a responsável por desencadear tudo, agora está acorrentada e forçada a \"continuar lutando\" sob os olhos atentos do reino.</color>",
  ui_story_5076_50761200_3_dialog_content = "<color=#e8d9bb>O restante dos Caçadores Silenciosos está dividido e destacado para guarnecer as cidades fronteiriças. Até mesmo os Celestitas próximos estão em prisão domiciliar.</color>",
  ui_story_5076_50761200_4_dialog_content = "Vá embora! Mantenha essas coisas assustadoras longe do nosso lugar.",
  ui_story_5076_50761200_5_dialog_content = "Sou apenas um soldado e esta é minha arma. Se você se recusar a fazer negócios comigo, pelo menos deixe minha esposa entrar.",
  ui_story_5076_50761200_6_dialog_content = "Esposa...? Que lunático. Suma daqui!",
  ui_story_5076_50761200_7_dialog_content = "Seria sábio da sua parte mudar o tom e retirar seus comentários rudes.",
  ui_story_5076_50761200_8_dialog_content = "Deixe pra lá, Adras... Você ainda é o protetor deles, então brigar com eles sobre essas coisas não adianta.",
  ui_story_5076_50761200_9_dialog_content = "... Multar.",
  ui_story_5076_50761200_10_dialog_content = "Acontece que os rumores são verdadeiros. Os Caçadores Silenciosos são realmente todos um bando de lunáticos...",
  ui_story_5076_50761200_11_dialog_content = "Eu não gosto daqui, Marcela.",
  ui_story_5076_50761200_12_dialog_content = "Tudo bem, Adras. Eles simplesmente não te entendem, só isso.",
  ui_story_5076_50761200_13_dialog_content = "Tenho certeza de que eles te tratariam melhor se apenas tivessem a chance de te conhecer—",
  ui_story_5076_50761200_14_dialog_content = "Olha, aquele cara está lá de novo...",
  ui_story_5076_50761200_15_dialog_content = "Eca, parece que ele pode perder a qualquer momento. Quem sabe quando ele pode...",
  ui_story_5076_50761200_16_dialog_content = "Como está todo mundo hoje?",
  ui_story_5076_50761200_17_dialog_content = "Se perder! Mova-se!",
  ui_story_5076_50761200_18_dialog_content = "...",
  ui_story_5076_50761200_19_dialog_content = "Não se sinta desanimado. Talvez você encontre alguém mais simpático na próxima vez?",
  ui_story_5076_50761200_20_dialog_content = "<color=#e8d9bb>Segurando uma esperança tênue, o herói anseia que alguém mais venha ao resgate.</color>",
  ui_story_5076_50761200_21_dialog_content = "Olha, aqui vem o \"Eclipsite.\"",
  ui_story_5076_50761200_22_dialog_content = "Eclipsita? Onde?",
  ui_story_5076_50761200_23_dialog_content = "Fiquem atrás de mim, crianças! Você também, Marcela!",
  ui_story_5076_50761200_24_dialog_content = "Eu vou lidar com o Eclipsite—",
  ui_story_5076_50761200_25_dialog_content = "Hah! Idiota!",
  ui_story_5076_50761200_26_dialog_content = "Um tolo, assim como o Eclipsite! Hahaha!",
  ui_story_5076_50761200_27_dialog_content = "Essas crianças... Elas estão começando a pensar como os adultos?",
  ui_story_5076_50761200_28_dialog_content = "O que eu fiz de errado?",
  ui_story_5076_50761200_29_dialog_content = "<color=#e8d9bb>A situação continua dia após dia...</color>",
  ui_story_5076_50761200_30_dialog_content = "Por que todos aqui têm medo de mim...?",
  ui_story_5076_50761200_31_dialog_content = "É por causa dessas malditas cicatrizes...?",
  ui_story_5076_50761200_32_dialog_content = "Eu não sou um Eclipsita! Eu sei que não sou—",
  ui_story_5076_50761200_33_dialog_content = "Viu isso? Aquele cara ficaria louco sem motivo nenhum.",
  ui_story_5076_50761200_34_dialog_content = "Ouvi falar de um Caçador Silencioso que era exatamente assim, acabou incendiando uma cidade inteira no final.",
  ui_story_5076_50761200_35_dialog_content = "Não sei por que Sua Majestade ainda os mantém; ele é muito gentil.",
  ui_story_5076_50761200_36_dialog_content = "<color=#e8d9bb>Ele continua sofrendo ataques pelas costas, contra os quais ele é totalmente indefeso.</color>",
  ui_story_5076_50761200_37_dialog_content = "Se você me perguntar, todos eles deveriam ser executados. Quem sabe o que eles costumavam ser?",
  ui_story_5076_50761200_38_dialog_content = "Quem é \"Marcela\"? Quando aquele cara chama esse nome, ele parece realmente triste...",
  ui_story_5076_50761200_39_dialog_content = "Talvez seja alguém que ele já matou, uma pobre alma. Ouvi dizer que alguns Eclipsitas entendem o Universese e usam mentiras para enganar os outros e se aproximar deles.",
  ui_story_5076_50761200_40_dialog_content = "É verdade? Muito assustador, não é?",
  ui_story_5076_50761200_41_dialog_content = "<color=#e8d9bb>As estrelas outrora brilhantes estão se apagando rapidamente.</color>",
  ui_story_5076_50761200_42_dialog_content = "Marcela... É isso que aconteceu com Friegson e os outros? É esse tipo de vida que eles levaram?",
  ui_story_5076_50761200_43_dialog_content = "Naquela época, eu não sabia como ela se sentia.",
  ui_story_5076_50761200_44_dialog_content = "Se eu tivesse entendido na época, poderia ter estado lá para ela. As coisas teriam terminado de maneira diferente para ela?",
  ui_story_5076_50761200_45_dialog_content = "<color=#e8d9bb>Então, os corações dessas estrelas são capturados e puxados para o abismo.</color>",
  ui_story_5076_50761200_46_dialog_content = "Ah, Marcela? Finalmente recebi uma carta de Ludweiss hoje.",
  ui_story_5076_50761200_47_dialog_content = "Parece que ela finalmente teve a chance de se afastar, e ela está vindo nos visitar em breve. Ainda assim, eu gostaria que ela visitasse seus antigos vizinhos primeiro—",
  ui_story_5076_50761200_48_dialog_content = "Hum? O que você está fazendo?",
  ui_story_5076_50761200_49_dialog_content = "\"Mar—ce—la—\"",
  ui_story_5076_50761200_50_dialog_content = "Há uma resposta! Ah, não, ele está olhando para cá! CORRA!",
  ui_story_5076_50761200_51_dialog_content = "O que... O que exatamente eu sou para eles?",
  ui_story_5076_50761200_52_dialog_content = "E por que você parou de sussurrar no meu ouvido? Marcela...",
  ui_story_5076_50761200_53_dialog_content = "<color=#e8d9bb>Quando as estrelas cortam o céu e caem na terra, elas finalmente retornarão à paz que merecem? Ou é simplesmente uma queda dos céus distantes?</color>",
  ui_story_5076_50761200_54_dialog_content = "<color=#e8d9bb>Estrelas que uma vez brilharam sobre as massas, elas algum dia encontrarão um lugar para pertencer?</color>",
  ui_story_5076_50761200_55_dialog_content = "<color=#e8d9bb>Se o futuro for deixado apenas com desespero quando o belo sonho é despedaçado... a luta ainda tem algum significado nesse ponto?</color>",
  ui_story_5076_50761200_56_dialog_content = "Afaste-se de mim, seu pirralho! Pare de me seguir!",
  ui_story_5076_50761200_57_dialog_content = "\"Marcela—Marcela—\"",
  ui_story_5076_50761200_58_dialog_content = "Parece que ele está prestes a chorar.",
  ui_story_5076_50761200_59_dialog_content = "Vamos, rápido! O \"Eclipsite\" vai perder a paciência.",
  ui_story_5076_50761200_60_dialog_content = "Morra... Morra... Morra... Morra...",
  ui_story_5076_50761200_61_dialog_content = "<size=45>Eclipsita!!!</size>",
  ui_story_5076_50761200_62_dialog_content = "Eu não vejo... Onde está o Eclipsite?",
  ui_story_5076_50761200_63_dialog_content = "E onde você está, Marcela?",
  ui_story_5076_50761200_64_dialog_content = "Por favor, apenas me chame como costumava fazer...",
  ui_story_5076_50761300_1_dialog_content = "<color=#e8d9bb>O poder do reino deveria ser delicadamente equilibrado, mas a atitude persistente do Rei finalmente esmagou o Conselho dos Anciãos que ele odiava.</color>",
  ui_story_5076_50761300_2_dialog_content = "<color=#e8d9bb>Desde a expulsão do Primeiro Ancião, o Sumo Sacerdote Lucius iniciou sua purgação.</color>",
  ui_story_5076_50761300_3_dialog_content = "<color=#e8d9bb>As ações do Sumo Sacerdote são realmente motivadas por seus motivos egoístas? Ou ele sempre foi um porta-voz para outra pessoa?</color>",
  ui_story_5076_50761300_4_dialog_content = "Abra, Adras.",
  ui_story_5076_50761300_5_dialog_content = "Quem são vocês? Espere... Capitão?",
  ui_story_5076_50761300_6_dialog_content = "Qual é o problema? Você já esqueceu nossos rostos?",
  ui_story_5076_50761300_7_dialog_content = "Isso é duro, Vice Capitão. Especialmente porque viemos buscar abrigo aqui com você.",
  ui_story_5076_50761300_8_dialog_content = "O que houve?",
  ui_story_5076_50761300_9_dialog_content = "Uma conspiração rebelde foi descoberta dentro do Conselho dos Anciãos. Sob ordens secretas do rei, Lucius queria usar os Caçadores Silenciosos para suprimi-la.",
  ui_story_5076_50761300_10_dialog_content = "Mas Friegson e Freya se recusaram a cumprir, e como resultado... Eles foram presos e encarcerados.",
  ui_story_5076_50761300_11_dialog_content = "Eu me recuso a desencadear minhas chamas nas pessoas, mesmo que isso signifique que eu tenha que morrer.",
  ui_story_5076_50761300_12_dialog_content = "Foi quando Aquiles organizou um resgate perigoso e me tirou da prisão domiciliar para completar.",
  ui_story_5076_50761300_13_dialog_content = "Mas foi tudo graças a Cynthia e Ludweiss que conseguimos escapar da capital em segurança.",
  ui_story_5076_50761300_14_dialog_content = "Os pedidos para a captura imediata deles serão feitos em breve. Quero que você os escolte para fora do reino antes disso.",
  ui_story_5076_50761300_15_dialog_content = "E você?",
  ui_story_5076_50761300_16_dialog_content = "Assumo total responsabilidade por tudo isso, e é por isso que vou retornar à capital e aceitar o castigo do rei.",
  ui_story_5076_50761300_17_dialog_content = "Ele acredita que, se entregando, ele pode garantir nossa liberdade.",
  ui_story_5076_50761300_18_dialog_content = "O quê? Você perdeu a cabeça, Aquiles?! Temos que ficar juntos!",
  ui_story_5076_50761300_19_dialog_content = "O homem que se senta no trono já foi meu irmão de armas. Como dois lados de uma falange, ele salvou minha vida inúmeras vezes.",
  ui_story_5076_50761300_20_dialog_content = "Eu nunca poderia virar as costas para ele.",
  ui_story_5076_50761300_21_dialog_content = "Fique tranquilo, eu vou encontrar uma maneira de falar com o rei. Ainda há esperança para um resultado melhor.",
  ui_story_5076_50761300_22_dialog_content = "Não há como mudar a mente do Capitão uma vez que ele decide fazer algo. Desista, Vice Comandante.",
  ui_story_5076_50761300_23_dialog_content = "Pelo menos vamos passar algum tempo juntos antes de nos separarmos novamente.",
  ui_story_5076_50761300_24_dialog_content = "Com as coisas do jeito que estão hoje em dia, isso ainda importa?",
  ui_story_5076_50761300_25_dialog_content = "Nada de bom virá de nós nos reunindo assim.",
  ui_story_5076_50761300_26_dialog_content = "Não diga isso, Friegson. Achilles lutou muito para resgatar todos e nos trazer aqui.",
  ui_story_5076_50761300_27_dialog_content = "Desculpe.",
  ui_story_5076_50761300_28_dialog_content = "Acho que é uma ótima ideia! Faz muito tempo desde que bebi o vinho do Vice Capitão, e só de pensar nisso, realmente me traz boas lembranças.",
  ui_story_5076_50761300_29_dialog_content = "Então é só me esperar aqui. Eu volto em um minuto.",
  ui_story_5076_50761300_30_dialog_content = "Não devemos apenas sentar e esperar pela bebida. Vamos preparar algo para comer enquanto isso!",
  ui_story_5076_50761300_31_dialog_content = "Este lugar já viu dias melhores. O Vice Capitão sempre foi tão bagunçado?",
  ui_story_5076_50761300_32_dialog_content = "... Alguém notou algo diferente no estado mental do Vice Capitão?",
  ui_story_5076_50761300_33_dialog_content = "Do que você está falando? Além do Capitão, ele sempre se saiu melhor do que qualquer um de nós.",
  ui_story_5076_50761300_34_dialog_content = "Esse amor puro e poderoso em seu coração tem mantido sua corrupção afastada por anos.",
  ui_story_5076_50761300_35_dialog_content = "Mas Freya, eu posso sentir algo nele... O cheiro de desespero.",
  ui_story_5076_50761300_36_dialog_content = "Ele é um de nós, afinal.",
  ui_story_5076_50761300_37_dialog_content = "De jeito nenhum! Não consigo pensar em algo mais esperançoso—",
  ui_story_5076_50761300_38_dialog_content = "<size=50>Aaaaahhhh!!!!</size>",
  ui_story_5076_50761300_39_dialog_content = "O que foi isso? Vamos, Aquiles!",
  ui_story_5076_50761300_40_dialog_content = "Foi aquela... A voz do Vice Capitão?",
  ui_story_5076_50761300_41_dialog_content = "E se eu te dissesse que a pessoa mais gravemente ferida do nosso grupo é nada menos que nosso \"escudo\"?",
  ui_story_5076_50761300_42_dialog_content = "Você ainda acha que há esperança, Freya?",
  ui_story_5076_50761300_43_dialog_content = "<size=45>Aahhhh!!!</size>",
  ui_story_5076_50761300_44_dialog_content = "<size=45>Eclipsitas! Eclipsitas!!!</size>",
  ui_story_5076_50761300_45_dialog_content = "O que é isso?!",
  ui_story_5076_50761300_46_dialog_content = "Tanta destruição... É como se nem um único centímetro deste lugar fosse poupado...",
  ui_story_5076_50761300_47_dialog_content = "Por quê?! O que os Eclipsitas estão fazendo no porão da minha casa?!",
  ui_story_5076_50761300_48_dialog_content = "Por que eu não percebi eles antes?!",
  ui_story_5076_50761300_49_dialog_content = "Essas marcas de corte foram feitas por uma espada, Ludweiss...",
  ui_story_5076_50761300_50_dialog_content = "<size=45>Por que? Por que?!?</size>",
  ui_story_5076_50761300_51_dialog_content = "Acalme-se, Adras. Estamos todos aqui agora, e não há nenhum Eclipsita por perto.",
  ui_story_5076_50761300_52_dialog_content = "Não! Eles mentiram! Todos eles mentiram para mim!",
  ui_story_5076_50761300_53_dialog_content = "Eles nunca se livraram do Eclipsita que estava destruindo o templo, e agora ele me seguiu até em casa!",
  ui_story_5076_50761300_54_dialog_content = "Todos estavam com muito medo de matá-lo, mas eu mesmo não consegui encontrá-lo...",
  ui_story_5076_50761300_55_dialog_content = "Como pode existir um Eclipsita tão poderoso quanto este? Eu não tenho como derrotá-lo, e a Marcela não sai do esconderijo por causa dele...",
  ui_story_5076_50761300_56_dialog_content = "Você consegue sentir a localização dele, Ludweiss? Eu não posso deixar que machuque mais alguém!",
  ui_story_5076_50761300_57_dialog_content = "Não vou deixar mais ninguém cair nas mãos dos Eclipsitas. Não de novo...",
  ui_story_5076_50761300_58_dialog_content = "Capitão... Eu acho que ele finalmente...",
  ui_story_5076_50761300_59_dialog_content = "Então, mesmo um amor tão puro quanto o dele não pode impedir que essa horrível corrupção se espalhe?",
  ui_story_5076_50761300_60_dialog_content = "Realmente não há futuro para nós, afinal.",
  ui_story_5076_50761300_61_dialog_content = "Você não pode usar seus poderes de Celestita para estabilizar a mente dele, Ludweiss?",
  ui_story_5076_50761300_62_dialog_content = "Desculpe-me, Aquiles, mas eu teria feito isso há muito tempo se fosse possível...",
  ui_story_5076_50761300_63_dialog_content = "Fiquem atrás de mim, pessoal! Não dá para saber quando aquele Eclipsita vai atacar, então fiquem alertas!",
  ui_story_5076_50761300_64_dialog_content = "É poderoso demais para...",
  ui_story_5076_50761300_65_dialog_content = "Para...",
  ui_story_5076_50761300_66_dialog_content = "O que você fez?",
  ui_story_5076_50761300_67_dialog_content = "Acabei de colocá-lo para dormir por um tempo...",
  ui_story_5076_50761300_68_dialog_content = "Você fez isso tão facilmente, como se ele estivesse completamente indefeso.",
  ui_story_5076_50761300_69_dialog_content = "Ele deve estar tão cansado. Todo esse tempo, ele foi o mais solitário de todos nós.",
  ui_story_5076_50761300_70_dialog_content = "Você acha que ele ainda pode ter bons sonhos?",
  ui_story_5076_50761300_71_dialog_content = "Eu certamente espero que sim.",
  ui_story_5076_50761300_72_dialog_content = "Você estava certo, Cynthia: sinto tanto arrependimento agora. Eu estava sendo muito arrogante?",
  ui_story_5076_50761300_73_dialog_content = "Eu pensei que poderia suportar tudo, mas não ajudei uma única pessoa.",
  ui_story_5076_50761300_74_dialog_content = "Se eu tivesse tomado minha decisão naquela época e libertado todos vocês de sua dor—",
  ui_story_5076_50761300_75_dialog_content = "Você estava planejando nos eliminar naquela caverna durante nossa última missão, não estava? Mas no final, você não conseguiu fazer isso.",
  ui_story_5076_50761300_76_dialog_content = "Isso é tudo culpa minha.",
  ui_story_5076_50761300_77_dialog_content = "Não é sua culpa que as coisas acabaram assim, nem a culpa de mais ninguém.",
  ui_story_5076_50761300_78_dialog_content = "Matar com uma arma em tempos de guerra não é um pecado, mas em tempos de paz... A própria existência de uma arma é um pecado.",
  ui_story_5076_50761300_79_dialog_content = "Essas pessoas comuns que nos rejeitam realmente nos odeiam do fundo de seus corações? Não - acho que elas simplesmente não tiveram a chance de nos entender.",
  ui_story_5076_50761300_80_dialog_content = "Tudo o que é preciso é a oportunidade certa... Assim como o Vice Capitão e sua esposa protegeram essas pessoas, e eles cuidaram dele em troca...",
  ui_story_5076_50761300_81_dialog_content = "Infelizmente, não temos como fazer com que todos no mundo nos entendam.",
  ui_story_5076_50761300_82_dialog_content = "Se há alguém ou algo para culpar por tudo isso, é o destino.",
  ui_story_5076_50761300_83_dialog_content = "Mesmo assim, não tenho arrependimentos.",
  ui_story_5076_50761300_84_dialog_content = "Concordo. Eu aceitei voluntariamente esse resultado em troca de salvar nossa terra dos Eclipsitas. Se eu tiver que queimar por essa causa, que assim seja.",
  ui_story_5076_50761300_85_dialog_content = "Isso não me torna um covarde, torna?",
  ui_story_5076_50761300_86_dialog_content = "Friegson, todos vocês... Se o dia chegar em que eu me transformar completamente em um Eclipsita, não ousem me mostrar qualquer misericórdia.",
  ui_story_5076_50761300_87_dialog_content = "Acho que vou partir antes de você... Então até lá, mantenha seus raios tão precisos quanto estão hoje.",
  ui_story_5076_50761300_88_dialog_content = "... Isso é realmente o único resultado para todos?",
  ui_story_5076_50761300_89_dialog_content = "Pelo menos, eu me recuso a aceitar isso.",
  ui_story_5076_50761300_90_dialog_content = "Ainda escrevendo no seu diário, hein?",
  ui_story_5076_50761300_91_dialog_content = "Fazer um registro disso não vai mudar nada.",
  ui_story_5076_50761300_92_dialog_content = "Mesmo monstros imortais como nós não conseguem ver nosso próprio futuro claramente.",
  ui_story_5076_50761300_93_dialog_content = "Estou mal conseguindo me agarrar às minhas memórias do passado como estão. Todos aqueles dias felizes estão sendo lentamente corroídos pela escuridão...",
  ui_story_5076_50761300_94_dialog_content = "Talvez as coisas fossem melhores se todos nós fôssemos esquecidos—",
  ui_story_5076_50761300_95_dialog_content = "Claro que faz diferença!",
  ui_story_5076_50761300_96_dialog_content = "Sou um Celestita, lembra? Ninguém entende sentimentos e memórias melhor do que o meu povo!",
  ui_story_5076_50761300_97_dialog_content = "Se alguém algum dia ler este diário... Pelo menos saberão sobre as estrelas que guiaram as pessoas do nosso tempo.",
  ui_story_5076_50761300_98_dialog_content = "E se essa pessoa acontecer de ser outro Celestita, ela herdará minhas memórias e minha vontade, e saberá exatamente como me sinto sobre todos vocês...",
  ui_story_5076_50761300_99_dialog_content = "Até as estrelas cadentes têm um lugar nos corações daqueles que veem sua beleza.",
  ui_story_5076_50761300_100_dialog_content = "Isso definitivamente significa algo, então por favor... Apenas deixe-me continuar escrevendo.",
  ui_story_5076_50761300_101_dialog_content = "Tudo bem, mas você vai encharcar todas as suas páginas se não parar de chorar.",
  ui_story_5076_50761300_102_dialog_content = "Você pode ser tão teimoso às vezes, Ludweiss... Então vamos fazer isso juntos.",
  ui_story_5076_50761300_103_dialog_content = "Afinal... Uma pessoa não poderia possivelmente escrever todas as nossas memórias juntas, certo?",
  ui_story_5076_50761300_104_dialog_content = "Vamos ajudá-lo a manter a esperança viva!",
  ui_story_5076_50761300_105_dialog_content = "Pelo menos um de nós está destinado a chegar longe no futuro. Quando isso acontecer, não importa quem seja—",
  ui_story_5076_50761300_106_dialog_content = "Por favor, não se esqueça de nós.",
  ui_story_5076_50761400_1_dialog_content = "<color=#e8d9bb>À medida que os viajantes cruzam a fronteira, o capitão se vira conforme planejado.</color>",
  ui_story_5076_50761400_2_dialog_content = "<color=#e8d9bb>Ele agiria como um \"sacrifício\", entregando-se aos perseguidores para garantir a liberdade dos outros cinco.</color>",
  ui_story_5076_50761400_3_dialog_content = "<color=#e8d9bb>Mas esses Guerreiros Estelares realmente aceitariam tal troca?</color>",
  ui_story_5076_50761400_4_dialog_content = "Eles estão em suas mãos agora, Ludweiss. Se algum deles acordar, coloque-os para dormir imediatamente.",
  ui_story_5076_50761400_5_dialog_content = "Você realmente pretende resgatar Aquiles sozinho, Adras?",
  ui_story_5076_50761400_6_dialog_content = "Não está esquecendo quem eu sou? Eu sou Adras, o homem que acabou com uma guerra! Eu sou mais do que suficiente para eles.",
  ui_story_5076_50761400_7_dialog_content = "Volte por agora. O Capitão e eu iremos alcançá-lo em breve.",
  ui_story_5076_50761400_8_dialog_content = "Adras...",
  ui_story_5076_50761400_9_dialog_content = "O Vice Capitão se foi?",
  ui_story_5076_50761400_10_dialog_content = "Ainda consigo ouvir fracamente seus passos. Deixe-o ir um pouco mais longe primeiro.",
  ui_story_5076_50761400_11_dialog_content = "H-Huh?",
  ui_story_5076_50761400_12_dialog_content = "Somos os Caçadores Silenciosos. Não existem mais outros como nós no mundo.",
  ui_story_5076_50761400_13_dialog_content = "Podemos não ter uma casa, mas enquanto estivermos juntos, isso é mais do que suficiente para nós.",
  ui_story_5076_50761400_14_dialog_content = "Vagando pela terra como um grupo de párias odiados... Isso me parece bom.",
  ui_story_5076_50761400_15_dialog_content = "Mesmo que o mundo inteiro negue nosso futuro, ainda nos recusamos a nos render.",
  ui_story_5076_50761400_16_dialog_content = "Você ainda planeja nos impedir, Ludweiss?",
  ui_story_5076_50761400_17_dialog_content = "Eu tinha a sensação de que estava sendo seguido, e justo quando eu pensei...",
  ui_story_5076_50761400_18_dialog_content = "Nos encontramos de novo, herói. Certamente isso deve ser destino?",
  ui_story_5076_50761400_19_dialog_content = "Lucius, seu vilão! Pelo futuro do reino, eu juro que vou—",
  ui_story_5076_50761400_20_dialog_content = "Você e os outros Caçadores já escolheram nos trair. Que direito você tem de falar sobre o futuro do reino?",
  ui_story_5076_50761400_21_dialog_content = "Guardas! Prendam esse suposto \"herói\"!",
  ui_story_5076_50761400_22_dialog_content = "Afaste-se! Não pense que pode me impedir!",
  ui_story_5076_50761400_23_dialog_content = "Eu me recuso a levantar minha lâmina contra pessoas inocentes!",
  ui_story_5076_50761400_24_dialog_content = "Um sentimento comovente, mas completamente inútil. Dê uma olhada nesses soldados, Adras; eles não são diferentes de você!",
  ui_story_5076_50761400_25_dialog_content = "O quê?",
  ui_story_5076_50761400_26_dialog_content = "Rarrr! Grrrr!",
  ui_story_5076_50761400_27_dialog_content = "São todos Eclipsitas?!",
  ui_story_5076_50761400_28_dialog_content = "Mas eles estão vestindo uniformes de soldado! Isso não pode estar certo!",
  ui_story_5076_50761400_29_dialog_content = "Assim como você, eles não são nada mais do que monstros modificados agora. Concedido, eles não são quase tão fortes quanto você, mas são muito mais obedientes.",
  ui_story_5076_50761400_30_dialog_content = "O que você quer dizer com \"modificado\"? O que você fez com os orgulhosos soldados do nosso reino?!",
  ui_story_5076_50761400_31_dialog_content = "Você já esqueceu, Adras? Talvez a corrupção finalmente tenha se espalhado para a sua mente?",
  ui_story_5076_50761400_32_dialog_content = "Se for assim, seria ainda mais risível.",
  ui_story_5076_50761400_33_dialog_content = "Não dê ouvidos a ele, Adras! Assim que eu estiver livre, eu vou—",
  ui_story_5076_50761400_34_dialog_content = "Guardas, subjuguem o capitão!",
  ui_story_5076_50761400_35_dialog_content = "Aquiles! Você monstro, Lucius! Como pôde fazer algo tão horrível com esses soldados leais? Eu—",
  ui_story_5076_50761400_36_dialog_content = "Heheh, eles são um pouco mais fortes do que você esperava, não?",
  ui_story_5076_50761400_37_dialog_content = "Isso é porque eles são o último lote de soldados aumentados do projeto Silent Hunters.",
  ui_story_5076_50761400_38_dialog_content = "Esplêndidos, não são? Eles estão ainda mais perto de serem Eclipsites do que quaisquer versões anteriores!",
  ui_story_5076_50761400_39_dialog_content = "Eles são mais seguros, mais fáceis de controlar e completamente desprovidos de razão. Afinal, isso só atrapalharia eles.",
  ui_story_5076_50761400_40_dialog_content = "Pare de falar, Lucius, ou eu não vou conseguir me conter por muito mais tempo.",
  ui_story_5076_50761400_41_dialog_content = "Ah não, você não poderia possivelmente me matar. Eu sou o conselheiro mais confiável do rei, lembra? Se você levantar sequer um dedo contra mim, destruirei tudo o que você trabalhou tanto para proteger.",
  ui_story_5076_50761400_42_dialog_content = "Além disso, você já aguentou tanto. Por que parar agora?",
  ui_story_5076_50761400_43_dialog_content = "Por mais poderosos que os Silent Hunters possam ser, todos foram corrompidos pelo Darkflow. Seus estados psicológicos que deterioram rapidamente são a razão pela qual acredito que todos vocês deveriam ser erradicados.",
  ui_story_5076_50761400_44_dialog_content = "Diga-me, poderoso herói: quantas de suas preciosas memórias foram engolidas pela escuridão em seu coração? Ou você tem vivido em um estado de delírio todo esse tempo?",
  ui_story_5076_50761400_45_dialog_content = "Morra, seu monstro!",
  ui_story_5076_50761400_46_dialog_content = "Me solta!",
  ui_story_5076_50761400_47_dialog_content = "Lucius! Por brincar com a vida das pessoas e pisotear nossa lealdade, você não merece nada além da pior das mortes!",
  ui_story_5076_50761400_48_dialog_content = "Se é isso que eu mereço, então o que dizer de uma abominação meio Eclipsita como você?",
  ui_story_5076_50761400_49_dialog_content = "Dê uma olhada no reflexo da sua lâmina, Adras. Você consegue se ver claramente agora?",
  ui_story_5076_50761400_50_dialog_content = "Parece que você realmente esqueceu a verdade. O monstro sobre o qual você tem uivado...",
  ui_story_5076_50761400_51_dialog_content = "Não é ninguém menos que você!",
  ui_story_5076_50761400_52_dialog_content = "Não dê ouvidos a ele, Adras!",
  ui_story_5076_50761400_53_dialog_content = "Ele está certo, Adras! Você não é um monstro!",
  ui_story_5076_50761400_54_dialog_content = "Marcela? Quando você chegou aqui?",
  ui_story_5076_50761400_55_dialog_content = "Você não sabe o quão perigoso é aqui? Fique atrás de mim, rápido!",
  ui_story_5076_50761400_56_dialog_content = "Este é realmente o homem pelo qual você arriscou vida e membro para proteger, Aquiles? Um completo louco?",
  ui_story_5076_50761400_57_dialog_content = "Volte! Eu não vou deixar você machucá-la!",
  ui_story_5076_50761400_58_dialog_content = "Urgh—",
  ui_story_5076_50761400_59_dialog_content = "Você perdeu muito sangue, Adras! Pare de tentar me defender!",
  ui_story_5076_50761400_60_dialog_content = "Isso não é nada, Marcela. Apenas fique atrás e deixe tudo comigo...",
  ui_story_5076_50761400_61_dialog_content = "Não! Eu não quero ver você se machucar por minha causa!",
  ui_story_5076_50761400_62_dialog_content = "Parem, todos vocês! Ele é o maior herói do nosso reino—",
  ui_story_5076_50761400_63_dialog_content = "Não machuque mais meu pobre Adras!",
  ui_story_5076_50761400_64_dialog_content = "<size=45>Marcela!!!</size>",
  ui_story_5076_50761400_65_dialog_content = "Tá tudo bem, Adras... Eu sempre estarei com você...",
  ui_story_5076_50761400_66_dialog_content = "Por que... Isso não pode ser...",
  ui_story_5076_50761400_67_dialog_content = "Você tem gritado esse nome como uma lunática todo esse tempo. Marcela...",
  ui_story_5076_50761400_68_dialog_content = "Esse era o nome da sua falecida esposa, não era?",
  ui_story_5076_50761400_69_dialog_content = "Morta? Não—Ela não estava morta! Eu a salvei!",
  ui_story_5076_50761400_70_dialog_content = "Cheguei até ela bem na hora...",
  ui_story_5076_50761400_71_dialog_content = "Você finalmente voltou, Adras.",
  ui_story_5076_50761400_72_dialog_content = "Esperei tanto... Por você.",
  ui_story_5076_50761400_73_dialog_content = "É mesmo?",
  ui_story_5076_50761400_74_dialog_content = "Acredito que você se lembre da verdade agora, Adras. Sua esposa já faz muito tempo que...",
  ui_story_5076_50761400_75_dialog_content = "<size=45>Lúcio!</size>",
  ui_story_5076_50761400_76_dialog_content = "Não... Isso não pode ser... Me diga que não é verdade, Marcela...",
  ui_story_5076_50761400_77_dialog_content = "Todos aqueles dias felizes que passamos juntos depois... Todas as vezes que você me recebeu de volta das linhas de frente... Me diga que não foi uma mentira, Marcela...",
  ui_story_5076_50761400_78_dialog_content = "Naquele dia...",
  ui_story_5076_50761400_79_dialog_content = "Urgh... Minha cabeça... Não...",
  ui_story_5076_50761400_80_dialog_content = "Não!!!",
  ui_story_5076_50761400_81_dialog_content = "Não me faça ver isso de novo!!!",
  ui_story_5076_50761400_82_dialog_content = "Ao se juntar aos Caçadores Silenciosos, você deve aceitar que as modificações lhe concederão uma parcela do poder Eclipsita.",
  ui_story_5076_50761400_83_dialog_content = "Quando as modificações estiverem completas, você será mais forte do que nunca, mas também deve resistir à corrupção do Fluxo Escuro o tempo todo.",
  ui_story_5076_50761400_84_dialog_content = "Pode interferir com sua sanidade, ou até mesmo privá-lo de suas memórias.",
  ui_story_5076_50761400_85_dialog_content = "Eu... Eu não me importo mais.",
  ui_story_5076_50761400_86_dialog_content = "Para evitar que suas memórias de Marcela sejam destruídas, pedi a Ludweiss para extrair seu amor por ela e selá-lo dentro de sua espada.",
  ui_story_5076_50761400_87_dialog_content = "Você não deveria mais ser incomodado por suas alucinações... Olhe para mim, Adras. Você se lembra de mais alguma coisa?",
  ui_story_5076_50761400_88_dialog_content = "Marcela... Naquela época, ela...",
  ui_story_5076_50761400_89_dialog_content = "Não, não, não—",
  ui_story_5076_50761400_90_dialog_content = "Chega!",
  ui_story_5076_50761400_91_dialog_content = "... Eu falhei em cumprir minha promessa. Eu a decepcionei.",
  ui_story_5076_50761400_92_dialog_content = "Eu a abandonei, e ela <size=45>morreu na escuridão e no desespero</size>.",
  ui_story_5076_50761400_93_dialog_content = "Eu não quero mais pensar em nada, então me modifique o máximo possível... Além disso, eu já perdi tudo.",
  ui_story_5076_50761400_94_dialog_content = "Farei qualquer coisa se isso significa que posso continuar matando Eclipsitas.",
  ui_story_5076_50761400_95_dialog_content = "No momento em que Marcela morreu, ele começou a ter essas alucinações... Ninguém deveria ter que viver assim.",
  ui_story_5076_50761400_96_dialog_content = "Você tem certeza de que não há como apagar as memórias dele sobre a morte dela, Ludweiss?",
  ui_story_5076_50761400_97_dialog_content = "As memórias não são como uma corda, Aquiles. Eu não posso simplesmente cortar um pedaço e amarrar o resto junto.",
  ui_story_5076_50761400_98_dialog_content = "Se eu tentar remover uma memória tão dolorosa quanto essa, também afetará o resto de suas memórias de Marcela.",
  ui_story_5076_50761400_99_dialog_content = "Ou você está me pedindo para apagar ela completamente da mente dele? Porque isso seria muito mais cruel do que qualquer outra coisa.",
  ui_story_5076_50761400_100_dialog_content = "Deixe-o assim. Pelo menos, o amor em sua lâmina está a salvo da corrupção em seu corpo. Ele vai conseguir, tenho certeza disso...",
  ui_story_5076_50761400_101_dialog_content = "Mesmo que você não concorde com o meu uso do ódio para levá-lo à batalha, eu queria protegê-lo assim como você.",
  ui_story_5076_50761400_102_dialog_content = "Você realmente acha que isso é o melhor? Deixá-lo preso em uma ilusão, constantemente buscando um <color=#FFB400>falso</color> conforto? Se algo o acordar dessa <color=#FFB400>doce ilusão</color>...",
  ui_story_5076_50761400_103_dialog_content = "Enquanto <color=#FFB400>a espada dele estiver ao seu lado</color>, a ilusão continuará a preservar seu senso de identidade, bem como suas memórias de Marcela.",
  ui_story_5076_50761400_104_dialog_content = "Confie em mim, é melhor do que deixá-lo enfrentar a cruel realidade da morte dela e permitir que o ódio deforme seu coração...",
  ui_story_5076_50761400_105_dialog_content = "M-Marcela? Fique atrás, é perigoso aqui!",
  ui_story_5076_50761400_106_dialog_content = "É isso... o Caçador Silencioso?",
  ui_story_5076_50761400_107_dialog_content = "Tão aterrorizante. Difícil de imaginar que ele é um herói lendário. Olhe para ele! Ele é completamente... <color=#FFB400>LOUCO</color>!",
  ui_story_5076_50761400_108_dialog_content = "Se você se recusa a fazer negócios comigo, pelo menos deixe minha esposa entrar.",
  ui_story_5076_50761400_109_dialog_content = "<color=#FFB400>Esposa? Quando você arranjou uma esposa? Suma daqui, seu lunático!</color>",
  ui_story_5076_50761400_110_dialog_content = "Parece que você realmente esqueceu a verdade. O monstro sobre o qual você tem uivado...",
  ui_story_5076_50761400_111_dialog_content = "Não é ninguém menos que você!",
  ui_story_5076_50761400_112_dialog_content = "O templo—",
  ui_story_5076_50761400_113_dialog_content = "Marcela tem medo do templo—",
  ui_story_5076_50761400_114_dialog_content = "Não, não é isso. Eu sou o que tem medo disso... Porque aquele monte de escombros é onde Marcela <color=#FFB400>morreu</color>.",
  ui_story_5076_50761400_115_dialog_content = "É por isso que eu tenho que destruí-lo—",
  ui_story_5076_50761400_116_dialog_content = "<color=#FFB400>Eu tenho que destruir tudo!</color>",
  ui_story_5076_50761400_117_dialog_content = "<size=45>Aaaaaah!!!</size>",
  ui_story_5076_50761400_118_dialog_content = "<size=45>Morram, Eclipsitas!!!</size>",
  ui_story_5076_50761400_119_dialog_content = "<size=50>Todos vocês devem morrer!!!</size>",
  ui_story_5076_50761500_1_dialog_content = "O que aconteceu aqui? O chão... Está coberto com restos de Eclipsita!",
  ui_story_5076_50761500_2_dialog_content = "É o Vice Capitão. Ele deve ter enlouquecido novamente.",
  ui_story_5076_50761500_3_dialog_content = "Temos que detê-lo antes que ele machuque Ludweiss!",
  ui_story_5076_50761500_4_dialog_content = "Vejo alguém tentando escapar de lá...",
  ui_story_5076_50761500_5_dialog_content = "Venha até aqui, Cynthia! Nós... Nós não conseguimos mais segurar o Capitão Vice!",
  ui_story_5076_50761500_6_dialog_content = "Marcela—Marcela—!",
  ui_story_5076_50761500_7_dialog_content = "Por que... Por que não poderia ter sido eu...",
  ui_story_5076_50761500_8_dialog_content = "Eclipsitas! Morram, seus monstros!!!",
  ui_story_5076_50761500_9_dialog_content = "O que aconteceu com ele?",
  ui_story_5076_50761500_10_dialog_content = "Ele foi empurrado demais agora, e suas memórias se estilhaçaram através da ilusão que o estava protegendo.",
  ui_story_5076_50761500_11_dialog_content = "Então, o que devemos fazer?",
  ui_story_5076_50761500_12_dialog_content = "Ainda temos uma última opção! Lembra, Ludweiss?",
  ui_story_5076_50761500_13_dialog_content = "Mas se fizermos isso...",
  ui_story_5076_50761500_14_dialog_content = "Você está dizendo que quer deixá-lo assim?",
  ui_story_5076_50761500_15_dialog_content = "Você ainda se lembra do que conversamos naquele dia, capitão?",
  ui_story_5076_50761500_16_dialog_content = "Eu não acho que o Vice Capitão se importaria se fosse você a fazer isso—",
  ui_story_5076_50761500_17_dialog_content = "Não! Apenas... Deixe-me lidar com isso.",
  ui_story_5076_50761500_18_dialog_content = "Contamos com você, Ludweiss...",
  ui_story_5076_50761500_19_dialog_content = "Sinto muito, Adras... Desta vez, vou acabar com a fonte do seu sofrimento!",
  ui_story_5076_50761500_20_dialog_content = "O que você está fazendo, Ludweiss?!",
  ui_story_5076_50761500_21_dialog_content = "Estou removendo completamente as memórias da Marcela da mente dele! Assim, ele finalmente pode começar a buscar um novo futuro...",
  ui_story_5076_50761500_22_dialog_content = "Não...",
  ui_story_5076_50761500_23_dialog_content = "Eu não quero um novo futuro, então...",
  ui_story_5076_50761500_24_dialog_content = "Não ouse tocar nas minhas memórias dela! São tudo o que me resta!!!",
  ui_story_5076_50761500_25_dialog_content = "Cuidado!",
  ui_story_5076_50761500_26_dialog_content = "Ludweiss!",
  ui_story_5076_50761500_27_dialog_content = "(Eu estava tão perto... Mas eu não consegui terminar...)",
  ui_story_5076_50761500_28_dialog_content = "O que você está lendo?",
  ui_story_5076_50761500_29_dialog_content = "Ah, apenas um velho e fragmentado diário que a Sra. Sheol me vendeu barato. Mesmo que esteja faltando muitas páginas, o que está escrito aqui é realmente interessante!",
  ui_story_5076_50761500_30_dialog_content = "(Isto é... Uma memória? Mas este sentimento... É tão distante... Não consigo ver claramente...)",
  ui_story_5076_50761500_31_dialog_content = "... Por algum motivo, parece estranhamente familiar.",
  ui_story_5076_50761500_32_dialog_content = "Eu sei o que você quer dizer! Assim que peguei, senti como se estivesse de volta em Eraveil.",
  ui_story_5076_50761500_33_dialog_content = "Eraveil?",
  ui_story_5076_50761500_34_dialog_content = "Hã? Você disse alguma coisa?",
  ui_story_5076_50761500_35_dialog_content = "Eu não ouvi ninguém falando.",
  ui_story_5076_50761500_36_dialog_content = "Isso é estranho... De qualquer forma, este diário é um registro das viagens de um celestita! Mesmo que eu não consiga ler a escrita deles, posso ver as memórias do celestita apenas segurando-o em minhas mãos.",
  ui_story_5076_50761500_37_dialog_content = "Você pode me mostrar também?",
  ui_story_5076_50761500_38_dialog_content = "Sério? Esta é a primeira vez que te vejo tão interessado em algo.",
  ui_story_5076_50761500_39_dialog_content = "Claro, vamos vê-los juntos! Eu deveria ser capaz de usar minhas habilidades psíquicas em você e no diário ao mesmo tempo...",
  ui_story_5076_50761500_40_dialog_content = "Apenas me avise se algo não parecer certo—",
  ui_story_5076_50761500_41_dialog_content = "<color=#FFB400>Regal.</color>",
  ui_story_5076_50761500_42_dialog_content = "Você estava sonhando com o futuro distante, Adras? Ou você sonhou comigo depois de todos esses anos?",
  ui_story_5076_50761500_43_dialog_content = "Poderia ser... Que naquela época...",
  ui_story_5076_50761500_44_dialog_content = "Finalmente acordou, hein?",
  ui_story_5076_50761500_45_dialog_content = "Capitão...? O que aconteceu? Onde estamos?",
  ui_story_5076_50761500_46_dialog_content = "Você consegue se lembrar de alguma coisa?",
  ui_story_5076_50761500_47_dialog_content = "Eu... Eu sou Regal, e eu...",
  ui_story_5076_50761500_48_dialog_content = "Eu deveria fazer algo... Mas não consigo lembrar o que é.",
  ui_story_5076_50761500_49_dialog_content = "Capitão, ele...",
  ui_story_5076_50761500_50_dialog_content = "O reino está seguro dos Eclipsitas, o que significa que finalmente posso voltar para casa e desfrutar de uma vida tranquila... Mas onde é a minha casa?",
  ui_story_5076_50761500_51_dialog_content = "Há esse calor no meu peito... Não consigo realmente descrevê-lo, mas me sinto muito mais leve agora.",
  ui_story_5076_50761500_52_dialog_content = "Sinto como se estivesse sentindo falta de alguém. Por algum motivo, não consigo me lembrar do rosto deles, mas ainda me sinto contente.",
  ui_story_5076_50761500_53_dialog_content = "É essa a felicidade sobre a qual você estava me falando, Capitão?",
  ui_story_5076_50761500_54_dialog_content = "Capitão? Qual é o problema?",
  ui_story_5076_50761500_55_dialog_content = "... Saia.",
  ui_story_5076_50761500_56_dialog_content = "Sair? Mas para onde devo ir?",
  ui_story_5076_50761500_57_dialog_content = "Eu... Eu não sei. Mas se o seu coração te disser para ir a algum lugar, apenas siga-o.",
  ui_story_5076_50761500_58_dialog_content = "Saia e nunca mais volte, Adras.",
  ui_story_5076_50761500_59_dialog_content = "Meu coração...?",
  ui_story_5076_50761500_60_dialog_content = "Isso mesmo... Eu quero viver uma vida tranquila e pacífica... Mas onde devo ir para fazer isso?",
  ui_story_5076_50761500_61_dialog_content = "Sinto muito, a todos. Isso é tudo culpa minha... Eu não consegui me obrigar a fazer isso.",
  ui_story_5076_50761500_62_dialog_content = "Eu queria que seus sonhos terminassem no momento perfeito, mas eu não consegui... Eu não consegui apontar minha espada para você.",
  ui_story_5076_50761500_63_dialog_content = "Então, por favor, apenas fiquem longe. Não mostrem seus rostos no reino nunca mais.",
  ui_story_5076_50761500_64_dialog_content = "Tem certeza de que não pode vir conosco, Capitão?",
  ui_story_5076_50761500_65_dialog_content = "O reino está descendo ao caos novamente. Eu não posso simplesmente deixar assim.",
  ui_story_5076_50761500_66_dialog_content = "Esse covarde sumo sacerdote conseguiu escapar... Parece que tudo está intimamente ligado ao rei. Não há realmente nada que possamos fazer?",
  ui_story_5076_50761500_67_dialog_content = "Eu... Eu jurei nunca atacar civis, então não conte comigo.",
  ui_story_5076_50761500_68_dialog_content = "Esqueça isso, Cynthia. Confrontar o rei não mudará nada, mesmo que consigamos nos vingar dele. Só criaria mais tumulto para o reino.",
  ui_story_5076_50761500_69_dialog_content = "A verdade é, o rei está apenas tentando manter seu poder. Além disso, ele é definitivamente digno de liderar seus súditos.",
  ui_story_5076_50761500_70_dialog_content = "Mas os súditos dele não merecem justiça também? Se nada for feito, como eles poderão possivelmente prevenir que mais pessoas se machuquem?",
  ui_story_5076_50761500_71_dialog_content = "O reino está em ruínas, e somos vistos apenas como monstros. Não há razão para alimentarmos as chamas.",
  ui_story_5076_50761500_72_dialog_content = "Entendo... De ficar juntos a se separar, tudo que é preciso é um único passo.",
  ui_story_5076_50761500_73_dialog_content = "Cynthia?",
  ui_story_5076_50761500_74_dialog_content = "Parece que nossos caminhos são diferentes afinal. Nesse caso, estou indo embora agora.",
  ui_story_5076_50761500_75_dialog_content = "Eu respeitarei a decisão de todos e me absterrei de fazer qualquer coisa.",
  ui_story_5076_50761500_76_dialog_content = "... Espero que você encontre a paz algum dia, Cynthia. Adeus.",
  ui_story_5076_50761500_77_dialog_content = "Quais são os seus pensamentos, Friegson?",
  ui_story_5076_50761500_78_dialog_content = "Não importa para onde eu vá, sempre serei visto como um criminoso. É por isso que... eu quero ir com você e me entregar, Capitão.",
  ui_story_5076_50761500_79_dialog_content = "Freya e Adras, cuidem-se bem.",
  ui_story_5076_50761500_80_dialog_content = "Por quanto tempo mais você vai trabalhar para aquele homem?",
  ui_story_5076_50761500_81_dialog_content = "Eu não vou trabalhar para ele, Freya. Depois de tudo isso, não tenho esperança de algo assim.",
  ui_story_5076_50761500_82_dialog_content = "Mas o reino precisa de seu Claymore se quiser extinguir a rebelião iminente.",
  ui_story_5076_50761500_83_dialog_content = "Assim como você, eu tenho um dever que não posso simplesmente abandonar.",
  ui_story_5076_50761500_84_dialog_content = "Meu único conselho para você é pegar Ludweiss e ir para algum lugar bem longe daqui.",
  ui_story_5076_50761500_85_dialog_content = "Nossos caminhos nunca podem se cruzar novamente.",
  ui_story_5076_50761500_86_dialog_content = "Tenho o dever de eliminar todas e quaisquer ameaças ao nosso reino. Na próxima vez que nos encontrarmos, não terei escolha a não ser...",
  ui_story_5076_50761601_1_dialog_content = "Adras!",
  ui_story_5076_50761601_2_dialog_content = "Você finalmente acordou? Você esteve dormindo por tanto tempo.",
  ui_story_5076_50761601_3_dialog_content = "Por que a Vice Capitã atacou você de repente assim? Felizmente, a ferida não foi muito séria. Eu já cuidei dela para você.",
  ui_story_5076_50761601_4_dialog_content = "Mas, julgando pelas suas antigas feridas, parece que ainda há um risco de corrupção... Como você conseguiu mantê-lo afastado todo esse tempo? Isso é mais um dos seus poderes de Celestita?",
  ui_story_5076_50761601_X4_dialog_content = "... Cadê o resto?",
  ui_story_5076_50761601_5_dialog_content = "Todos se foram agora, até mesmo nosso Vice Capitão amnésico. Ele também não sabia para onde estava indo.",
  ui_story_5076_50761601_6_dialog_content = "Mas, para ser justo, eu também não. Ainda bem que você ainda está aqui... Pelo menos podemos continuar vagando juntos.",
  ui_story_5076_50761601_7_dialog_content = "Não consegui apagar completamente as memórias dele sobre Marcela... Se ele se lembrar dela novamente...",
  ui_story_5076_50761601_8_dialog_content = "Mas parece que o Vice Capitão já perdeu a maioria de suas memórias... Eu me pergunto para onde ele vai vagar agora?",
  ui_story_5076_50761601_9_dialog_content = "Isso mesmo... Com sua longa expectativa de vida, vagar faz muito sentido...",
  ui_story_5076_50761601_10_dialog_content = "Ludweiss?",
  ui_story_5076_50761601_11_dialog_content = "Você confia em mim, Freya?",
  ui_story_5076_50761601_12_dialog_content = "Se você fizer isso, então me ajude a procurar por todos novamente.",
  ui_story_5076_50761601_13_dialog_content = "Dessa forma, pode haver uma chance de mudar as coisas para nós.",
  ui_story_5076_50761601_14_dialog_content = "Essas ruínas... Que lugar é esse? Por que vim aqui sem perceber?",
  ui_story_5076_50761601_15_dialog_content = "Isso parece tão familiar... Eu já estive aqui antes?",
  ui_story_5076_50761601_16_dialog_content = "Talvez.",
  ui_story_5076_50761601_17_dialog_content = "Huh? Freya... É você?",
  ui_story_5076_50761601_18_dialog_content = "Não ligue para mim, apenas continue procurando. Tenho certeza de que há algo familiar para você escondido aqui.",
  ui_story_5076_50761601_19_dialog_content = "Esses vestígios de fogo e destruição... Foram os Eclipsitas responsáveis por isso?",
  ui_story_5076_50761601_20_dialog_content = "Há uma tumba aqui também... Mas quem colocaria isso dentro de uma casa?",
  ui_story_5076_50761601_21_dialog_content = "Este lugar está coberto de ervas daninhas, huh?",
  ui_story_5076_50761601_22_dialog_content = "O que é isso—",
  ui_story_5076_50761601_23_dialog_content = "Um mural queimado...?",
  ui_story_5076_50761601_24_dialog_content = "Você ainda se lembra disso?",
  ui_story_5076_50761601_25_dialog_content = "O quê? Não me lembro de nada... Mas este mural parece retratar uma cerimônia de algum tipo.",
  ui_story_5076_50761601_26_dialog_content = "O que poderia ser...?",
  ui_story_5076_50761601_27_dialog_content = "\"Dizem que a primeira pessoa a pintar um mural assim era um louco.\"",
  ui_story_5076_50761601_28_dialog_content = "\"E que para escapar do sofrimento em sua vida, ele criou uma nova realidade completamente.\"",
  ui_story_5076_50761601_29_dialog_content = "\"Isso pôs um fim ao sofrimento dele?\"",
  ui_story_5076_50761601_30_dialog_content = "\"Não. Ele apenas o selou.\"",
  ui_story_5076_50761601_31_dialog_content = "\"Entendo...\"",
  ui_story_5076_50761601_32_dialog_content = "M... Marcela?",
  ui_story_5076_50761601_33_dialog_content = "Enquanto trabalhamos para o nosso sonho, vamos continuar criando belas memórias juntos.",
  ui_story_5076_50761601_34_dialog_content = "Prometo valorizar cada momento maravilhoso de nossas vidas—",
  ui_story_5076_50761601_35_dialog_content = "Ah... Ahhh...",
  ui_story_5076_50761601_36_dialog_content = "Marcela... Minha querida Marcela...",
  ui_story_5076_50761601_37_dialog_content = "Finalmente... Estou ao seu lado mais uma vez...",
  ui_story_5076_50761601_38_dialog_content = "E assim termina a história do grande herói Adras. Diga-me, Freya; por que insistimos em viver?",
  ui_story_5076_50761601_39_dialog_content = "Qual o sentido de sobreviver neste mundo distorcido se isso significa perder tudo o que nos importamos?",
  ui_story_5076_50761601_40_dialog_content = "Este mundo não precisa mais de nós.",
  ui_story_5076_50761601_41_dialog_content = "Talvez seja finalmente a hora de libertar Adras de sua miséria... E a nós mesmos.",
  ui_story_5076_50761601_42_dialog_content = "Ludweiss disse que encontrou um caminho para um novo futuro para nós, embora a um custo.",
  ui_story_5076_50761601_43_dialog_content = "Você ainda está disposto a confiar em outras pessoas?",
  ui_story_5076_50761601_44_dialog_content = "Isso mesmo. Sempre colocarei minha fé na esperança.",
  ui_story_5076_50761601_45_dialog_content = "Vamos, Cynthia. É hora dos Caçadores Silenciosos terem uma última reunião.",
  ui_story_5076_50761601_X45_dialog_content = "<color=#e8d9bb>Então, as estrelas partiram mais uma vez, recusando-se a se curvar. Depois de todas aquelas batalhas lutadas pelo Deus da Luz em retirada, desta vez, a luta finalmente é por elas mesmas.</color>",
  ui_story_5076_50761601_46_dialog_content = "Eles estão aqui, Aquiles.",
  ui_story_5076_50761601_47_dialog_content = "Adras, Freya, Friegson, e até mesmo Cynthia... Todos estão aqui agora.",
  ui_story_5076_50761601_48_dialog_content = "E você tem certeza de que isso vai funcionar, Ludweiss?",
  ui_story_5076_50761601_49_dialog_content = "Não completamente, mas... Meu coração me diz para confiar no que vi quando estava inconsciente.",
  ui_story_5076_50761601_50_dialog_content = "Em mil anos, eles ainda estarão esperando por um lugar para chamar de lar. Quando esse tempo chegar... Eles finalmente serão livres.",
  ui_story_5076_50761601_51_dialog_content = "Tenho certeza que eles encontrarão a felicidade então.",
  ui_story_5076_50761601_52_dialog_content = "Eu confio em você, Ludweiss. Mas que tipo de preço você terá que pagar para selá-los assim?",
  ui_story_5076_50761601_53_dialog_content = "Eu te disse para não subestimar nós, os Celestitas, não disse? Ninguém entende o poder da alma melhor do que nós!",
  ui_story_5076_50761601_54_dialog_content = "Os Caçadores Silenciosos receberam corpos imortais como resultado de suas modificações.",
  ui_story_5076_50761601_55_dialog_content = "E ao capturar suas emoções poderosas e transformá-las em \"pedras angulares\", suas almas podem ser seladas em um estado dormente.",
  ui_story_5076_50761601_56_dialog_content = "Eles permanecerão vigilantes dentro de seu sonho milenar, mas além disso... Eles terão que usar suas memórias para resistir à passagem do tempo.",
  ui_story_5076_50761601_57_dialog_content = "Mas...",
  ui_story_5076_50761601_58_dialog_content = "Agora!",
  ui_story_5076_50761601_59_dialog_content = "O que é isso... Uma formação mágica? Espere, o que você pensa que está fazendo, Capitão?!",
  ui_story_5076_50761601_60_dialog_content = "Você não nos chamou para a arena para...",
  ui_story_5076_50761601_61_dialog_content = "Desculpe, mas essa é a única maneira de garantir a sua paz eterna... Desejo a todos vocês os mais doces sonhos.",
  ui_story_5076_50761601_62_dialog_content = "<color=#e8d9bb>A paixão dentro de Friegson há muito foi consumida pelo fogo, deixando para trás apenas um punhado de cinzas.</color>",
  ui_story_5076_50761601_63_dialog_content = "<color=#e8d9bb>Então, a única emoção restante para selá-la pode ser apenas o ódio.</color>",
  ui_story_5076_50761601_64_dialog_content = "<color=#e8d9bb>Caelestites comuns não podem realizar tal façanha, muito menos aqueles assombrados por velhas feridas.</color>",
  ui_story_5076_50761601_65_dialog_content = "<color=#e8d9bb>No entanto, se um Celestita estiver disposto a sacrificar sua vida, queimando-se para preservar as emoções dos outros...</color>",
  ui_story_5076_50761601_66_dialog_content = "Durma!",
  ui_story_5076_50761601_67_dialog_content = "O... Por quê...?",
  ui_story_5076_50761601_68_dialog_content = "Você pode descansar agora, Friegson. Eu prometo que seus sonhos serão livres de tristeza a partir de agora.",
  ui_story_5076_50761601_69_dialog_content = "Não importa... Desde que sejam vocês me traindo... Eu não me importo...",
  ui_story_5076_50761601_70_dialog_content = "O que você fez com Friegson, Capitão? Por que você a emboscaria assim?!",
  ui_story_5076_50761601_71_dialog_content = "Ainda no escuro, estamos? O rei deseja se livrar de vocês, criaturas perigosas, e Aquiles escolheu ficar ao lado de seu rei.",
  ui_story_5076_50761601_72_dialog_content = "Lucius? Como você ainda está vivo...?",
  ui_story_5076_50761601_73_dialog_content = "Você não vai negar as palavras dele, Capitão? Apenas me diga que ele está mentindo, e eu acreditarei em você!",
  ui_story_5076_50761601_74_dialog_content = "Guardas! Capturem esses vis fugitivos!",
  ui_story_5076_50761601_75_dialog_content = "Deixo o resto com você, Capitão. Confio que você não vai decepcionar Sua Majestade, vai?",
  ui_story_5076_50761601_76_dialog_content = "Capitão!!!",
  ui_story_5076_50761601_77_dialog_content = "Esses Eclipsitas parecem ainda mais fortes do que antes! Cynthia, mantenha-se em seu...",
  ui_story_5076_50761601_78_dialog_content = "Cuidado!",
  ui_story_5076_50761601_79_dialog_content = "Cynthia? Você...",
  ui_story_5076_50761601_80_dialog_content = "Como eu disse, Freya... Eu irei antes de você. Se houver um futuro para nós lá fora, eu espero que você—",
  ui_story_5076_50761601_81_dialog_content = "Cynthia!",
  ui_story_5076_50761601_82_dialog_content = "Como eu disse antes, tenho o dever de destruir todas e quaisquer ameaças ao reino.",
  ui_story_5076_50761601_83_dialog_content = "Eu não sou mais o seu capitão. Sou um carrasco a serviço do reino.",
  ui_story_5076_50761601_84_dialog_content = "Venha, Regal.",
  ui_story_5076_50761601_85_dialog_content = "Agora que você finalmente se lembra, concentre toda a sua raiva e ódio... E desencadeie-os em mim.",
  ui_story_5076_50761601_86_dialog_content = "<size=45>Você—</size>",
  ui_story_5076_50761601_87_dialog_content = "<size=45>Claymore—!!!</size>",
  ui_story_5076_50761602_1_dialog_content = "<color=#e8d9bb>Apesar da evidente vulnerabilidade em suas emoções, a força e a vontade de combate de Adras são incrivelmente formidáveis.</color>",
  ui_story_5076_50761602_2_dialog_content = "<color=#e8d9bb>Para apoderar-se da espada que guarda a última memória de Adras, Aquiles intencionalmente recebe um golpe da espada.</color>",
  ui_story_5076_50761602_3_dialog_content = "Perdoe-me... Adras.",
  ui_story_5076_50761602_4_dialog_content = "<color=#e8d9bb>Depois de enfiar a espada que acabara de agarrar de volta em Adras, ele instantaneamente perdeu a força, desabando no chão.</color>",
  ui_story_5076_50761602_5_dialog_content = "<color=#e8d9bb>Enquanto isso, o selo direcionado a Freya e Cynthia também foi concluído.</color>",
  ui_story_5076_50761602_6_dialog_content = "Você se saiu bem, leal capitão do rei. Agora erradique esses monstros de uma vez por todas!",
  ui_story_5076_50761602_7_dialog_content = "Capitão Aquiles... Por quê...?",
  ui_story_5076_50761602_8_dialog_content = "Ludweiss diz que este é o único jeito de mudar nosso destino, Adras... Mas não se preocupe, nos veremos novamente algum dia.",
  ui_story_5076_50761602_9_dialog_content = "Quando esse dia chegar, espero que você encontre sua felicidade novamente.",
  ui_story_5076_50761602_10_dialog_content = "Acabou agora, Ludweiss?",
  ui_story_5076_50761602_11_dialog_content = "Suas almas foram seladas dentro de seus corpos imortais... Onde elas permanecerão adormecidas... até...",
  ui_story_5076_50761602_12_dialog_content = "Você disse que esse sono profundo, aliado à corrupção deles, tem a chance de danificar suas memórias e até mesmo a própria sanidade...",
  ui_story_5076_50761602_13_dialog_content = "Mas mesmo que seja apenas Adras... Ele tem tão pouca alegria em sua vida como está. Pelo menos... Ele deveria ter permissão para se apegar às suas memórias felizes, certo?",
  ui_story_5076_50761602_14_dialog_content = "Desculpe... Mas o Celestita não é todo-poderoso... Tudo que podemos fazer agora... é esperar.",
  ui_story_5076_50761602_15_dialog_content = "Espero que a loucura deles se esgote após mil anos... Se eles conseguirem se lembrar de uma única memória feliz até lá... Tudo terá valido a pena.",
  ui_story_5076_50761602_16_dialog_content = "Urgh, estou quase no meu limite... Mas ainda não cheguei a Adras...",
  ui_story_5076_50761602_17_dialog_content = "(Olhe para o céu, e as estrelas brilharão em resposta.)",
  ui_story_5076_50761602_18_dialog_content = "(O calor de sua luz ainda é o mesmo, mesmo após mil anos.)",
  ui_story_5076_50761602_19_dialog_content = "(Deixe-me ajudá-lo desta vez!)",
  ui_story_5076_50761602_20_dialog_content = "Essa voz... Você é daquele tempo distante?",
  ui_story_5076_50761602_X20_dialog_content = "Acorda, Regal!",
  ui_story_5076_50761602_X21_dialog_content = "Então vamos vê-los juntos... <color=#FFB400>Regal</color>.",
  ui_story_5076_50761602_21_dialog_content = "Entendo... Parece que meus esforços não foram em vão, afinal de contas...",
  ui_story_5076_50761602_22_dialog_content = "Essas memórias estreladas resistiram ao teste do tempo, e agora estão finalmente nas mãos de outro Celestita...",
  ui_story_5076_50761602_23_dialog_content = "Eu tenho sentido saudades todo esse tempo, e essas vozes têm tentado tão arduamente me alcançar.",
  ui_story_5076_50761602_24_dialog_content = "Nossas emoções comuns nos unem, criando laços que transcendem o fluxo do tempo...",
  ui_story_5076_50761602_25_dialog_content = "Adras! Eu posso ver agora... Esse futuro é real.",
  ui_story_5076_50761602_26_dialog_content = "Daqui a incontáveis anos, alguém estará esperando pelo seu retorno triunfante.",
  ui_story_5076_50761602_27_dialog_content = "Eu não quero...",
  ui_story_5076_50761602_28_dialog_content = "Eu não quero a vida eterna. Eu não preciso da eternidade...",
  ui_story_5076_50761602_29_dialog_content = "Tudo que eu quero... é o momento que escorregou pelos meus dedos... Isso mesmo... Tudo que eu preciso é da Marcela.",
  ui_story_5076_50761602_30_dialog_content = "Então por favor... Apenas me deixe ir! Eu não quero ser selado! Deixe-me deitar ao lado de Marcela e dormir pelo resto do tempo!",
  ui_story_5076_50761602_31_dialog_content = "Se é isso que você quer...",
  ui_story_5076_50761602_32_dialog_content = "Ajude-me, Marcela... E você também, meu distante amigo—",
  ui_story_5076_50761602_33_dialog_content = "Ajude-me a transformar a saudade dele na força que ele precisa para sobreviver!",
  ui_story_5076_50761602_34_dialog_content = "(Deixe a pessoa em suas memórias ficar ao seu lado—)",
  ui_story_5076_50761602_35_dialog_content = "... Marcela?",
  ui_story_5076_50761602_36_dialog_content = "Não chore, Adras... Estou bem aqui...",
  ui_story_5076_50761602_37_dialog_content = "Espere, Marcela! Não vá!",
  ui_story_5076_50761602_38_dialog_content = "Eu não vou a lugar nenhum, meu doce Adras. Eu sempre estarei com você, agora e para sempre...",
  ui_story_5076_50761602_39_dialog_content = "Então não tenha medo... Todos os seus amigos querem que você durma, agora descanse sua cabeça cansada...",
  ui_story_5076_50761602_40_dialog_content = "Dormir... Então finalmente podemos—",
  ui_story_5076_50761602_41_dialog_content = "Não! Por favor!",
  ui_story_5076_50761602_42_dialog_content = "Marcela! Não vá!",
  ui_story_5076_50761602_43_dialog_content = "Não chore, Adras.",
  ui_story_5076_50761602_44_dialog_content = "Nossas memórias, nossa vontade... Até mesmo nossa fé.",
  ui_story_5076_50761602_45_dialog_content = "Estamos deixando todos eles com Marcela, para que ela possa sempre estar ao seu lado.",
  ui_story_5076_50761602_46_dialog_content = "Enquanto você ainda tiver um pouco de apego a este mundo e estiver disposto a depositar sua fé na esperança.",
  ui_story_5076_50761602_47_dialog_content = "(Os seus sonhos nunca serão solitários.)",
  ui_story_5076_50761602_48_dialog_content = "Vocês sempre estarão juntos.",
  ui_story_5076_50761602_49_dialog_content = "(Venha comigo, <color=#FFB400>Adras</color>. É hora de acordar do seu <color=#FFB400>sonho</color> de mil anos—)",
  ui_story_5076_50761602_50_dialog_content = "Quando você finalmente <color=#FFB400>acordar</color>, pode ser que não se lembre de nada. Se isso acontecer, por favor, não fique triste.",
  ui_story_5076_50761602_51_dialog_content = "Essas memórias preciosas sempre estarão adormecidas em seu coração, Adras.",
  ui_story_5076_50761602_52_dialog_content = "Os sentimentos ligados a eles sempre serão uma parte da sua alma.",
  ui_story_5076_50761602_53_dialog_content = "Você nunca mais estará sozinho.",
  ui_story_5076_50761602_54_dialog_content = "Agora por favor, acalme sua mente e apenas durma...",
  ui_story_5076_50761602_55_dialog_content = "Haverá um <color=#FFB400>lar</color> para você algum dia, contanto que mantenha a esperança viva em seu coração. Quando o encontrar, a paz retornará para você—",
  ui_story_5076_50761602_56_dialog_content = "Marcela... Todo mundo...",
  ui_story_5076_50761602_57_dialog_content = "*Tosse* Desculpe, Achilles.",
  ui_story_5076_50761602_58_dialog_content = "Mas parece que... Minha jornada finalmente chegou ao fim.",
  ui_story_5076_50761602_59_dialog_content = "Ludweiss... Então este é o preço que deve ser pago? Entendo... Até mesmo um Celestita não pode suportar tanta tragédia...",
  ui_story_5076_50761602_60_dialog_content = "É por isso que... estou deixando o futuro em suas mãos.",
  ui_story_5076_50761602_61_dialog_content = "Nós realmente merecemos isso?",
  ui_story_5076_50761602_62_dialog_content = "Isso é mesmo uma pergunta? Heheh... Estou tão grato por ter conhecido todos vocês. Graças a vocês, este Celestita errante finalmente encontrou a coragem para olhar para as estrelas.",
  ui_story_5076_50761602_63_dialog_content = "Obrigado a todos... Por iluminarem <color=#FFB400>este mundo</color> com a sua luz.",
  ui_story_5076_50761602_64_dialog_content = "Eu entendo... Fique tranquilo, Ludweiss.",
  ui_story_5076_50761602_65_dialog_content = "Suas memórias, sua vontade, suas vidas...",
  ui_story_5076_50761602_66_dialog_content = "Vou carregar todos eles em meus ombros.",
  ui_story_5076_50761602_67_dialog_content = "Pode não haver um lugar para mim no futuro, mas isso não vai me impedir de abrir um caminho para meus amigos!",
  ui_story_5076_50761602_68_dialog_content = "O que você acha que está fazendo, Aquiles? Por que ainda não os matou? Você não está planejando algo, está?!",
  ui_story_5076_50761602_69_dialog_content = "Pare! Não se aproxime de mim!",
  ui_story_5076_50761602_70_dialog_content = "Há algo que eu devo fazer... Algo que eu deveria ter feito há muito tempo.",
  ui_story_5076_50761602_71_dialog_content = "Aquiles? Qual é o significado disso?!",
  ui_story_5076_50761602_72_dialog_content = "Agora que sou o único que restou... Eu tenho que encontrar um jeito... De ver todos vocês novamente...",
  ui_story_5076_50761602_73_dialog_content = "Minha missão final... É transformar meu <color=#FFB400>anseio</color>... Na pedra fundamental de um selo.",
  ui_story_5076_50761602_74_dialog_content = "...",
  ui_story_5076_50761602_75_dialog_content = "Não chore, Adras... Há alguém te esperando no seu futuro.",
  ui_story_5076_50761602_76_dialog_content = "Coisas boas sempre acontecerão enquanto você mantiver a esperança em seu coração...",
  ui_story_5076_50761602_77_dialog_content = "Então, por favor, não chore mais.",
  ui_story_5076_50761602_78_dialog_content = "<color=#e8d9bb>Todo esse tempo, todos se acostumaram com a presença imponente do grande herói Adras.</color>",
  ui_story_5076_50761602_79_dialog_content = "<color=#e8d9bb>É tão reconfortante, mas tão... solitário. Se ele deve ser colocado em um sono de mil anos, pelo menos, ele deveria ter companhia.</color>",
  ui_story_5076_50761602_80_dialog_content = "<color=#e8d9bb>Esta é a primeira vez que \"eu\" toco em uma espada. Uma arma pesada, não é algo que um Celestita gostaria de manusear.</color>",
  ui_story_5076_50761602_81_dialog_content = "<color=#e8d9bb>Mas isso é diferente.</color>",
  ui_story_5076_50761602_82_dialog_content = "<color=#e8d9bb>Este não é uma arma; é um coração quente, abrigando o amor sincero do meu querido amigo.</color>",
  ui_story_5076_50761602_83_dialog_content = "<color=#e8d9bb>Quando eu o desenho e coloco em Adras, um sorriso adorna seu rosto, como uma criança que acabou de encontrar sua posse há muito perdida.</color>",
  ui_story_5076_50761602_84_dialog_content = "<color=#e8d9bb>Deve ser incrivelmente difícil suportar períodos tão longos de solidão.</color>",
  ui_story_5076_50761602_85_dialog_content = "<color=#e8d9bb>Tudo o que posso fazer é oferecer meus melhores votos, esperando que ele possa encontrar conforto com o que está em seu coração ao fechar os olhos.</color>",
  ui_story_5076_50761602_86_dialog_content = "<color=#e8d9bb>Se as estrelas que riscam o céu pudessem um dia encontrar onde pertencem na suavidade do tempo...</color>",
  ui_story_5076_50761602_87_dialog_content = "<color=#e8d9bb>May você recebe felicidade atrasada.</color>",
  ui_story_5076_50761602_88_dialog_content = "Bons sonhos, Adras."
}
return config
